// Fill out your copyright notice in the Description page of Project Settings.

#pragma once

#include "CoreMinimal.h"
#include "Engine/DataAsset.h"
#include "Cosmetic/WjWorldCosmeticTypes.h"
#include "WjWorldCosmeticDataAsset.generated.h"

/**
 * 개별 코스메틱 아이템 정의
 * ItemId(FName)를 중간 키로 사용하여 Steam ItemDefId와 비주얼 에셋을 매핑
 */
USTRUCT(BlueprintType)
struct WJWORLD_API FCosmeticItemDefinition
{
	GENERATED_BODY()

	/** 플랫폼 독립적 아이템 식별자 (중간 키) */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	FName ItemId;

	/** Steam Inventory Item Definition ID (플랫폼 종속) */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	int32 SteamItemDefId = 0;

	/** 표시 이름 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	FText DisplayName;

	/** 설명 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	FText Description;

	/** 장착 슬롯 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	ECosmeticSlot Slot = ECosmeticSlot::None;

	/** 희귀도 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	ECosmeticRarity Rarity = ECosmeticRarity::Common;

	/** 메시 에셋 (비동기 로드용) */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	TSoftObjectPtr<USkeletalMesh> SkeletalMesh;

	/** 스태틱 메시 에셋 (Back, Effect 등 슬롯용) */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	TSoftObjectPtr<UStaticMesh> StaticMesh;

	/** 아이콘 텍스처 (UI용) */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	TSoftObjectPtr<UTexture2D> Icon;

	/** 가격 (상점 표시용, 실제 결제는 Steam 처리) */
	UPROPERTY(EditAnywhere, BlueprintReadOnly)
	int32 Price = 0;

	/** 무료 재화(Coin) 가격 (0 = Coin으로 구매 불가) */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Price")
	int32 CoinPrice = 0;

	/** 유료 재화(Gem) 가격 (0 = Gem으로 구매 불가) */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Price")
	int32 GemPrice = 0;

	/** 부착 소켓 이름 (비어있으면 슬롯 기본값 사용) */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Attachment")
	FName AttachSocketName;

	/** 부착 시 상대 위치 오프셋 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Attachment")
	FVector AttachLocationOffset = FVector::ZeroVector;

	/** 부착 시 상대 회전 오프셋 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Attachment")
	FRotator AttachRotationOffset = FRotator::ZeroRotator;

	/** 부착 시 스케일 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Attachment")
	FVector AttachScale = FVector::OneVector;

	bool IsValid() const { return !ItemId.IsNone(); }
};

/**
 * 코스메틱 카탈로그 데이터 에셋
 * 전체 코스메틱 아이템 목록을 관리하며, 양방향 조회(ItemId ↔ SteamItemDefId) 지원
 */
UCLASS(BlueprintType)
class WJWORLD_API UWjWorldCosmeticCatalogDataAsset : public UPrimaryDataAsset
{
	GENERATED_BODY()

public:
	/** 전체 아이템 정의 목록 */
	UPROPERTY(EditAnywhere, BlueprintReadOnly, Category = "Cosmetic")
	TArray<FCosmeticItemDefinition> Items;

	/** ItemId로 아이템 정의 조회 */
	const FCosmeticItemDefinition* FindByItemId(FName ItemId) const;

	/** SteamItemDefId로 아이템 정의 조회 */
	const FCosmeticItemDefinition* FindBySteamItemDefId(int32 SteamItemDefId) const;

	/** SteamItemDefId → ItemId 변환 */
	FName SteamItemDefIdToItemId(int32 SteamItemDefId) const;

	/** ItemId → SteamItemDefId 변환 */
	int32 ItemIdToSteamItemDefId(FName ItemId) const;

	/** 특정 슬롯의 모든 아이템 반환 */
	TArray<const FCosmeticItemDefinition*> GetItemsBySlot(ECosmeticSlot Slot) const;

//#if WITH_EDITOR
//	virtual void PreSave(FObjectPreSaveContext SaveContext) override;
//#endif

protected:
	/** 내부 검색 최적화용 인덱스 (런타임에 빌드) */
	void BuildLookupMaps() const;

	mutable TMap<FName, int32> ItemIdToIndex;
	mutable TMap<int32, int32> SteamDefIdToIndex;
	mutable bool bLookupDirty = true;
};

// Fill out your copyright notice in the Description page of Project Settings.

#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "Cosmetic/WjWorldCosmeticTypes.h"
#include "Engine/StreamableManager.h"
#include "WjWorldCosmeticComponent.generated.h"

class UWjWorldCosmeticCatalogDataAsset;
struct FCosmeticItemDefinition;

/**
 * 캐릭터에 부착되어 코스메틱 비주얼을 적용하는 컴포넌트
 * - 로드아웃 기반 비주얼 적용
 * - 비동기 에셋 로드 (FStreamableManager)
 * - 기본 스킨 백업/복원
 */
UCLASS(ClassGroup=(Custom), meta=(BlueprintSpawnableComponent))
class WJWORLD_API UWjWorldCosmeticComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	UWjWorldCosmeticComponent();

	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

	/** 카탈로그 설정 */
	void SetCatalog(UWjWorldCosmeticCatalogDataAsset* InCatalog);

	/** 전체 로드아웃 적용 */
	UFUNCTION(BlueprintCallable, Category = "Cosmetic")
	void ApplyLoadout(const FCosmeticLoadout& InLoadout);

	/** 개별 슬롯에 아이템 적용 */
	UFUNCTION(BlueprintCallable, Category = "Cosmetic")
	void ApplySlot(ECosmeticSlot Slot, FName ItemId);

	/** 개별 슬롯 제거 (기본 스킨으로 복원) */
	UFUNCTION(BlueprintCallable, Category = "Cosmetic")
	void ClearSlot(ECosmeticSlot Slot);

	/** 모든 코스메틱 제거 (기본 스킨 복원) */
	UFUNCTION(BlueprintCallable, Category = "Cosmetic")
	void ClearAll();

	/** 현재 적용된 로드아웃 */
	UFUNCTION(BlueprintCallable, Category = "Cosmetic")
	const FCosmeticLoadout& GetAppliedLoadout() const { return AppliedLoadout; }

protected:
	/** CosmeticSubsystem의 OnLoadoutChanged 핸들러 */
	UFUNCTION()
	void OnLoadoutChangedHandler(ECosmeticSlot Slot, FName ItemId);

private:
	/** 비동기 에셋 로드 후 메시 적용 */
	void OnAssetLoaded(ECosmeticSlot Slot, FName ItemId);

	/** 슬롯에 해당하는 메시 컴포넌트 반환 또는 생성 */
	UMeshComponent* GetOrCreateSlotMeshComponent(ECosmeticSlot Slot);

	/** 기본 메시 백업 */
	void BackupDefaultMeshes();

	/** 기본 메시로 복원 */
	void RestoreDefaultMesh(ECosmeticSlot Slot);

	UPROPERTY()
	TObjectPtr<UWjWorldCosmeticCatalogDataAsset> Catalog;

	/** 현재 적용된 로드아웃 */
	FCosmeticLoadout AppliedLoadout;

	/** 슬롯별 동적 생성된 메시 컴포넌트 */
	UPROPERTY()
	TMap<ECosmeticSlot, TObjectPtr<UMeshComponent>> SlotMeshComponents;

	/** 기본 메시 백업 (Head/Body 슬롯용) */
	UPROPERTY()
	TMap<ECosmeticSlot, TSoftObjectPtr<USkeletalMesh>> DefaultMeshes;

	/** 비동기 로드 핸들 */
	FStreamableManager StreamableManager;
	TMap<ECosmeticSlot, TSharedPtr<FStreamableHandle>> ActiveStreamHandles;

	/** 기본 메시 백업 완료 여부 */
	bool bDefaultMeshesBackedUp = false;

	/** 슬롯별 기본 소켓 이름 반환 */
	static FName GetDefaultSocketName(ECosmeticSlot Slot);
};

