    17→void UWjWorldCosmeticComponent::BeginPlay()
    18→{
    19→	Super::BeginPlay();
    20→
    21→	BackupDefaultMeshes();
    22→
    23→	// CosmeticSubsystem 구독 및 초기화
    24→	if (UGameInstance* GI = GetWorld()->GetGameInstance())
    25→	{
    26→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>())
    27→		{
    28→			// 카탈로그 설정 (모든 캐릭터)
    29→			SetCatalog(CosmeticSub->GetCatalog());
    30→
    31→			// 로컬 플레이어만 델리게이트 구독 및 초기 로드아웃 적용
    32→			// 3자 캐릭터는 OnRep_PlayerState() → OnPawnSet() 경로로 PlayerState의 로드아웃 적용
    33→			APawn* OwnerPawn = Cast<APawn>(GetOwner());
    34→			if (OwnerPawn && OwnerPawn->IsLocallyControlled())
    35→			{
    36→				CosmeticSub->OnLoadoutChanged.AddDynamic(this, &ThisClass::OnLoadoutChangedHandler);
    37→				ApplyLoadout(CosmeticSub->GetLoadout());
    38→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent: 로컬 플레이어 초기화 완료"));
    39→			}
    40→			else
    41→			{
    42→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent: 3자 캐릭터 - PlayerState 리플리케이션 대기"));
    43→			}
    44→		}
    45→	}
    46→}
    47→
    48→void UWjWorldCosmeticComponent::EndPlay(const EEndPlayReason::Type EndPlayReason)
    49→{
    50→	// 비동기 로드 핸들 정리
    51→	for (auto& Pair : ActiveStreamHandles)
    52→	{
    53→		if (Pair.Value.IsValid())
    54→		{
    55→			Pair.Value->CancelHandle();
    56→		}
    57→	}
    58→	ActiveStreamHandles.Reset();
    59→
    60→	// CosmeticSubsystem 구독 해제
    61→	if (UGameInstance* GI = GetWorld()->GetGameInstance())
    62→	{
    63→		if (UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>())
    64→		{
    65→			CosmeticSub->OnLoadoutChanged.RemoveDynamic(this, &ThisClass::OnLoadoutChangedHandler);
    66→		}
    67→	}
    68→
    69→	Super::EndPlay(EndPlayReason);
    70→}
    71→
    72→void UWjWorldCosmeticComponent::SetCatalog(UWjWorldCosmeticCatalogDataAsset* InCatalog)
    73→{
    74→	Catalog = InCatalog;
    75→}
    76→
    77→void UWjWorldCosmeticComponent::ApplyLoadout(const FCosmeticLoadout& InLoadout)
    78→{
    79→	APawn* OwnerPawn = Cast<APawn>(GetOwner());
    80→	FString OwnerName = OwnerPawn ? OwnerPawn->GetName() : TEXT("Unknown");
    81→	bool bIsLocal = OwnerPawn ? OwnerPawn->IsLocallyControlled() : false;
    82→
    83→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent::ApplyLoadout - Owner: %s, IsLocal: %d, Entries: %d"),
    84→		*OwnerName, bIsLocal, InLoadout.Entries.Num());
    85→
    86→	// 기존 코스메틱 제거
    87→	ClearAll();
    88→
    89→	// 새 로드아웃 적용
    90→	for (const FCosmeticSlotEntry& Entry : InLoadout.Entries)
    91→	{
    92→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("  - Applying Slot %d: %s"),
    93→			static_cast<int32>(Entry.Slot), *Entry.ItemId.ToString());
    94→		ApplySlot(Entry.Slot, Entry.ItemId);
    95→	}
    96→}
    97→
    98→void UWjWorldCosmeticComponent::ApplySlot(ECosmeticSlot Slot, FName ItemId)
    99→{
   100→	if (Slot == ECosmeticSlot::None || ItemId.IsNone())
   101→	{
   102→		return;
   103→	}
   104→
   105→	if (!Catalog)
   106→	{
   107→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("카탈로그가 설정되지 않았습니다."));
   108→		return;
   109→	}
   110→
   111→	const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
   112→	if (!Def)
   113→	{
   114→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("카탈로그에서 아이템 '%s'을 찾을 수 없습니다."), *ItemId.ToString());
   115→		return;
   116→	}
   117→
   118→	// 기존 핸들 취소
   119→	if (TSharedPtr<FStreamableHandle>* ExistingHandle = ActiveStreamHandles.Find(Slot))
   120→	{
   121→		if (ExistingHandle->IsValid())
   122→		{
   123→			(*ExistingHandle)->CancelHandle();
   124→		}
   125→	}
   126→
   127→	AppliedLoadout.Equip(Slot, ItemId);
   128→
   129→	// 비동기 에셋 로드
   130→	TArray<FSoftObjectPath> AssetsToLoad;
   131→
   132→	if (!Def->SkeletalMesh.IsNull())
   133→	{
   134→		AssetsToLoad.Add(Def->SkeletalMesh.ToSoftObjectPath());
   135→	}
   136→	if (!Def->StaticMesh.IsNull())
   137→	{
   138→		AssetsToLoad.Add(Def->StaticMesh.ToSoftObjectPath());
   139→	}
   140→
   141→	if (AssetsToLoad.Num() > 0)
   142→	{
   143→		TSharedPtr<FStreamableHandle> Handle = StreamableManager.RequestAsyncLoad(
   144→			AssetsToLoad,
   145→			FStreamableDelegate::CreateUObject(this, &ThisClass::OnAssetLoaded, Slot, ItemId)
   146→		);
   147→		ActiveStreamHandles.Add(Slot, Handle);
   148→
   149→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("비동기 로드 시작: 슬롯 %d ← %s (%d 에셋)"),
   150→			static_cast<int32>(Slot), *ItemId.ToString(), AssetsToLoad.Num());
   151→	}
   152→}
   153→
   154→void UWjWorldCosmeticComponent::ClearSlot(ECosmeticSlot Slot)
   155→{
   156→	// 비동기 핸들 취소
   157→	if (TSharedPtr<FStreamableHandle>* Handle = ActiveStreamHandles.Find(Slot))
   158→	{
   159→		if (Handle->IsValid())
   160→		{
   161→			(*Handle)->CancelHandle();
   162→		}
   163→		ActiveStreamHandles.Remove(Slot);
   164→	}
   165→
   166→	AppliedLoadout.Unequip(Slot);
   167→	RestoreDefaultMesh(Slot);
   168→
   169→	// 동적 메시 컴포넌트 제거
   170→	if (TObjectPtr<UMeshComponent>* MeshComp = SlotMeshComponents.Find(Slot))
   171→	{
   172→		if (*MeshComp)
   173→		{
   174→			(*MeshComp)->DestroyComponent();
   175→		}
   176→		SlotMeshComponents.Remove(Slot);
   177→	}
   178→}
   179→
   180→void UWjWorldCosmeticComponent::ClearAll()
   181→{
   182→	TArray<ECosmeticSlot> Slots = AppliedLoadout.GetEquippedSlots();
   183→
   184→	for (ECosmeticSlot Slot : Slots)
   185→	{
   186→		ClearSlot(Slot);
   187→	}
   188→
   189→	AppliedLoadout.Reset();
   190→}
   191→
   192→void UWjWorldCosmeticComponent::OnAssetLoaded(ECosmeticSlot Slot, FName ItemId)
   193→{
   194→	if (!IsValid(this) || !GetOwner())
   195→	{
   196→		return;
   197→	}
   198→
   199→	// 로드 완료 시 해당 슬롯이 여전히 같은 아이템인지 확인
   200→	FName CurrentItem = AppliedLoadout.GetEquippedItem(Slot);
   201→	if (CurrentItem != ItemId)
   202→	{
   203→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("비동기 로드 완료되었으나 슬롯이 변경됨 (기대: %s, 현재: %s)"),
   204→			*ItemId.ToString(), *CurrentItem.ToString());
   205→		return;
   206→	}
   207→
   208→	if (!Catalog)
   209→	{
   210→		return;
   211→	}
   212→
   213→	const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
   214→	if (!Def)
   215→	{
   216→		return;
   217→	}
   218→
   219→	ACharacter* OwnerCharacter = Cast<ACharacter>(GetOwner());
   220→	if (!OwnerCharacter)
   221→	{
   222→		return;
   223→	}
   224→
   225→	// 소켓 이름 결정 (아이템 정의 우선, 없으면 슬롯 기본값)
   226→	FName SocketName = Def->AttachSocketName.IsNone() ? GetDefaultSocketName(Slot) : Def->AttachSocketName;
   227→
   228→	// SkeletalMesh 적용 (Head, Body 슬롯)
   229→	if (!Def->SkeletalMesh.IsNull() && Def->SkeletalMesh.IsValid())
   230→	{
   231→		USkeletalMesh* LoadedMesh = Def->SkeletalMesh.Get();
   232→		if (LoadedMesh)
   233→		{
   234→			// Body 슬롯: 캐릭터의 메인 메시 교체
   235→			if (Slot == ECosmeticSlot::Body)
   236→			{
   237→				USkeletalMeshComponent* MeshComp = OwnerCharacter->GetMesh();
   238→				if (MeshComp)
   239→				{
   240→					MeshComp->SetSkeletalMesh(LoadedMesh);
   241→					UE_LOG(LogWjWorldCosmetic, Log, TEXT("Body 메시 적용: %s"), *LoadedMesh->GetName());
   242→				}
   243→			}
   244→			else
   245→			{
   246→				// 다른 슬롯: 소켓에 부착
   247→				USkeletalMeshComponent* SlotMesh = NewObject<USkeletalMeshComponent>(OwnerCharacter);
   248→				SlotMesh->SetSkeletalMesh(LoadedMesh);
   249→				SlotMesh->AttachToComponent(
   250→					OwnerCharacter->GetMesh(),
   251→					FAttachmentTransformRules::SnapToTargetNotIncludingScale,
   252→					SocketName
   253→				);
   254→
   255→				// 오프셋 적용
   256→				SlotMesh->SetRelativeLocation(Def->AttachLocationOffset);
   257→				SlotMesh->SetRelativeRotation(Def->AttachRotationOffset);
   258→				SlotMesh->SetRelativeScale3D(Def->AttachScale);
   259→
   260→				SlotMesh->RegisterComponent();
   261→				SlotMeshComponents.Add(Slot, SlotMesh);
   262→
   263→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("슬롯 %d 메시 소켓 부착: %s → %s"),
   264→					static_cast<int32>(Slot), *LoadedMesh->GetName(), *SocketName.ToString());
   265→			}
   266→		}
   267→	}
   268→
   269→	// StaticMesh 적용 (Back, Effect 슬롯)
   270→	if (!Def->StaticMesh.IsNull() && Def->StaticMesh.IsValid())
   271→	{
   272→		UStaticMesh* LoadedStaticMesh = Def->StaticMesh.Get();
   273→		if (LoadedStaticMesh)
   274→		{
   275→			UStaticMeshComponent* SlotStaticMesh = NewObject<UStaticMeshComponent>(OwnerCharacter);
   276→			SlotStaticMesh->SetStaticMesh(LoadedStaticMesh);
   277→			SlotStaticMesh->AttachToComponent(
   278→				OwnerCharacter->GetMesh(),
   279→				FAttachmentTransformRules::SnapToTargetNotIncludingScale,
   280→				SocketName
   281→			);
   282→
   283→			// 오프셋 적용
   284→			SlotStaticMesh->SetRelativeLocation(Def->AttachLocationOffset);
   285→			SlotStaticMesh->SetRelativeRotation(Def->AttachRotationOffset);
   286→			SlotStaticMesh->SetRelativeScale3D(Def->AttachScale);
   287→
   288→			SlotStaticMesh->RegisterComponent();
   289→			SlotMeshComponents.Add(Slot, SlotStaticMesh);
   290→
   291→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("슬롯 %d 스태틱 메시 소켓 부착: %s → %s"),
   292→				static_cast<int32>(Slot), *LoadedStaticMesh->GetName(), *SocketName.ToString());
   293→		}
   294→	}
   295→
   296→	// 로드 핸들 정리
   297→	ActiveStreamHandles.Remove(Slot);
   298→}
   299→
   300→UMeshComponent* UWjWorldCosmeticComponent::GetOrCreateSlotMeshComponent(ECosmeticSlot Slot)
   301→{
   302→	if (TObjectPtr<UMeshComponent>* Found = SlotMeshComponents.Find(Slot))
   303→	{
   304→		return *Found;
   305→	}
   306→	return nullptr;
   307→}
   308→
   309→void UWjWorldCosmeticComponent::BackupDefaultMeshes()
   310→{
   311→	if (bDefaultMeshesBackedUp)
   312→	{
   313→		return;
   314→	}
   315→
   316→	ACharacter* OwnerCharacter = Cast<ACharacter>(GetOwner());
   317→	if (!OwnerCharacter)
   318→	{
   319→		return;
   320→	}
   321→
   322→	USkeletalMeshComponent* MeshComp = OwnerCharacter->GetMesh();
   323→	if (MeshComp && MeshComp->GetSkeletalMeshAsset())
   324→	{
   325→		DefaultMeshes.Add(ECosmeticSlot::Body, MeshComp->GetSkeletalMeshAsset());
   326→	}
   327→
   328→	bDefaultMeshesBackedUp = true;
   329→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("기본 메시 백업 완료"));
   330→}
   331→
   332→void UWjWorldCosmeticComponent::RestoreDefaultMesh(ECosmeticSlot Slot)
   333→{
   334→	if (Slot != ECosmeticSlot::Body)
   335→	{
   336→		return;
   337→	}
   338→
   339→	ACharacter* OwnerCharacter = Cast<ACharacter>(GetOwner());
   340→	if (!OwnerCharacter)
   341→	{
   342→		return;
   343→	}
   344→
   345→	if (const TSoftObjectPtr<USkeletalMesh>* DefaultMesh = DefaultMeshes.Find(Slot))
   346→	{
   347→		if (DefaultMesh->IsValid())
   348→		{
   349→			USkeletalMeshComponent* MeshComp = OwnerCharacter->GetMesh();
   350→			if (MeshComp)
   351→			{
   352→				MeshComp->SetSkeletalMesh(DefaultMesh->Get());
   353→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("기본 메시 복원: 슬롯 %d"), static_cast<int32>(Slot));
   354→			}
   355→		}
   356→	}
   357→}
   358→
   359→void UWjWorldCosmeticComponent::OnLoadoutChangedHandler(ECosmeticSlot Slot, FName ItemId)
   360→{
   361→	// 로컬 플레이어 캐릭터만 처리 (멀티플레이어에서 다른 플레이어 캐릭터 제외)
   362→	APawn* OwnerPawn = Cast<APawn>(GetOwner());
   363→	if (!OwnerPawn)
   364→	{
   365→		return;
   366→	}
   367→
   368→	// 로컬 컨트롤 여부 확인
   369→	if (!OwnerPawn->IsLocallyControlled())
   370→	{
   371→		return;
   372→	}
   373→
   374→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent: 로드아웃 변경 감지 - 슬롯 %d, 아이템 %s"),
   375→		static_cast<int32>(Slot), *ItemId.ToString());
   376→
   377→	if (ItemId.IsNone())
   378→	{
   379→		// 아이템 해제
   380→		ClearSlot(Slot);
   381→	}
   382→	else
   383→	{
   384→		// 아이템 장착
   385→		ApplySlot(Slot, ItemId);
   386→	}
   387→}
   388→
   389→FName UWjWorldCosmeticComponent::GetDefaultSocketName(ECosmeticSlot Slot)
   390→{
   391→	switch (Slot)
   392→	{
   393→	case ECosmeticSlot::Head:
   394→		return FName(TEXT("head"));  // 스켈레톤의 head 본/소켓
   395→	case ECosmeticSlot::Body:
   396→		return NAME_None;  // Body는 메시 교체 방식
   397→	case ECosmeticSlot::Back:
   398→		return FName(TEXT("spine_03"));  // 등 부착용
   399→	case ECosmeticSlot::Effect:
   400→		return FName(TEXT("root"));  // 이펙트는 루트
   401→	default:
   402→		return NAME_None;
   403→	}
   404→}
