{
	// 로컬 플레이어 캐릭터만 처리 (멀티플레이어에서 다른 플레이어 캐릭터 제외)
	APawn* OwnerPawn = Cast<APawn>(GetOwner());
	if (!OwnerPawn)
	{
		return;
	}

	// 로컬 컨트롤 여부 확인
	if (!OwnerPawn->IsLocallyControlled())
	{
		return;
