	/** 코스메틱 로드아웃으로 프리뷰 설정 */
	void SetupPreview(const FCosmeticLoadout& Loadout);

	/** 렌더 타겟 반환 */
	UTextureRenderTarget2D* GetRenderTarget() const { return RenderTarget; }

	/** alpha 반전 처리된 프리뷰 머티리얼 반환 (Image 브러시용) */
