   216→		if (CurrentCharges <= 0)
   217→		{
   218→			float RefillRemaining = AbilityInstance->GetChargeRefillTimeRemaining();
   219→			if (RefillRemaining > 0.f)
   220→			{
   221→				if (CooldownOverlay)
   222→				{
   223→					CooldownOverlay->SetVisibility(ESlateVisibility::HitTestInvisible);
   224→				}
   225→				if (CooldownText)
