   231→			}
   232→		}
   233→
   234→		// 충전이 남아있으면 쿨다운 오버레이 숨김
   235→		if (CooldownOverlay)
   236→		{
   237→			CooldownOverlay->SetVisibility(ESlateVisibility::Collapsed);
   238→		}
   239→		if (CooldownText)
   240→		{
   241→			CooldownText->SetVisibility(ESlateVisibility::Collapsed);
