   255→	{
   256→		return;
   257→	}
   258→
   259→	UAbilitySystemComponent* ASC = CharacterPlay->GetAbilitySystemComponent();
   260→	if (!ASC)
   261→	{
   262→		return;
   263→	}
   264→
   265→	// 쿨다운 태그로 잔여 시간 조회
   266→	const FGameplayTagContainer* CooldownTags = AbilityInstance->GetCooldownTags();
   267→	if (!CooldownTags || CooldownTags->Num() == 0)
   268→	{
   269→		if (CooldownOverlay)
   270→		{
   271→			CooldownOverlay->SetVisibility(ESlateVisibility::Collapsed);
   272→		}
   273→		if (CooldownText)
   274→		{
   275→			CooldownText->SetVisibility(ESlateVisibility::Collapsed);
   276→		}
   277→		return;
   278→	}
   279→
   280→	float Remaining = 0.f;
   281→	FGameplayEffectQuery Query = FGameplayEffectQuery::MakeQuery_MatchAnyOwningTags(*CooldownTags);
   282→	TArray<float> Durations = ASC->GetActiveEffectsTimeRemaining(Query);
   283→
   284→	for (float Time : Durations)
   285→	{
   286→		if (Time > Remaining)
   287→		{
   288→			Remaining = Time;
   289→		}
   290→	}
   291→
   292→	if (Remaining > 0.f)
   293→	{
   294→		if (CooldownOverlay)
   295→		{
   296→			CooldownOverlay->SetVisibility(ESlateVisibility::HitTestInvisible);
   297→		}
