   301→			CooldownText->SetText(FText::FromString(FString::Printf(TEXT("%.1f"), Remaining)));
   302→		}
   303→	}
   304→	else
   305→	{
   306→		if (CooldownOverlay)
   307→		{
   308→			CooldownOverlay->SetVisibility(ESlateVisibility::Collapsed);
   309→		}
   310→		if (CooldownText)
