	}

	CachedAbilityInstance = AbilityInstance;
	bAbilityCached = true;

	// 초기화: 아이콘, 키 바인딩 텍스트
	InitializeIcon();

	if (KeyBindText)
	{
		KeyBindText->SetText(ResolveKeyBindText());
	}

	return true;
}

