   190→bool USessionManager::FindSessions(ENetworkMode NetworkMode, int32 MaxSearchResults)
   191→{
   192→	if (!SessionInterface.IsValid())
   193→	{
   194→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   195→		return false;
   196→	}
   197→
   198→	// 이전 검색이 진행 중이면 대기열에 등록 (완료 후 자동 실행)
   199→	if (bIsSearchInProgress)
   200→	{
   201→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Previous search in progress, queuing new %s search"),
   202→			NetworkMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
   203→		PendingSearchRequest = TPair<ENetworkMode, int32>(NetworkMode, MaxSearchResults);
   204→		return true;
   205→	}
   206→
   207→	// 검색 네트워크 모드 저장 (JoinSession에서 NetDriver 전환용)
   208→	LastSearchNetworkMode = NetworkMode;
   209→
   210→	// 검색 설정
   211→	SessionSearch = MakeShareable(new FOnlineSessionSearch());
   212→	SessionSearch->MaxSearchResults = MaxSearchResults;
   213→
   214→	// 네트워크 모드에 따른 검색 설정
   215→	if (NetworkMode == ENetworkMode::Steam)
   216→	{
   217→		SessionSearch->bIsLanQuery = false;
   218→		SessionSearch->QuerySettings.Set(SEARCH_LOBBIES, true, EOnlineComparisonOp::Equals);
   219→	}
   220→	else // LAN
   221→	{
   222→		SessionSearch->bIsLanQuery = true;
   223→		SessionSearch->QuerySettings.Set(SEARCH_LOBBIES, false, EOnlineComparisonOp::Equals);
   224→	}
   225→
   226→	// 검색 시작
   227→	const ULocalPlayer* LocalPlayer = GetWorld()->GetFirstLocalPlayerFromController();
   228→	bool bSuccess = SessionInterface->FindSessions(*LocalPlayer->GetPreferredUniqueNetId(), SessionSearch.ToSharedRef());
   229→
   230→	if (bSuccess)
   231→	{
   232→		bIsSearchInProgress = true;
   233→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Searching for %s sessions..."),
   234→			NetworkMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
   235→	}
   236→	else
