   244→bool USessionManager::JoinSession(int32 RoomIndex)
   245→{
   246→	if (!SessionInterface.IsValid())
   247→	{
   248→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   249→		return false;
   250→	}
   251→
   252→	if (!SessionSearch.IsValid() || SessionSearch->SearchResults.Num() == 0)
   253→	{
   254→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: No search results available"));
   255→		return false;
   256→	}
   257→
   258→	if (!SessionSearch->SearchResults.IsValidIndex(RoomIndex))
   259→	{
   260→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Invalid room index %d"), RoomIndex);
   261→		return false;
   262→	}
   263→
   264→	// ⭐ 중요: 기존 세션이 있다면 먼저 제거
   265→	auto ExistingSession = SessionInterface->GetNamedSession(SESSION_NAME);
   266→	if (ExistingSession != nullptr)
   267→	{
   268→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Destroying existing session before joining..."));
   269→		
   270→		SessionInterface->DestroySession(SESSION_NAME);
   271→		
   272→		int32 WaitCount = 0;
   273→		while (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr && WaitCount < 100)
   274→		{
   275→			FPlatformProcess::Sleep(0.01f);
   276→			WaitCount++;
   277→		}
   278→		
   279→		if (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr)
   280→		{
   281→			UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to destroy existing session"));
   282→			return false;
   283→		}
   284→		
   285→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Existing session destroyed successfully"));
   286→	}
   287→
   288→	LastJoinedRoomIndex = RoomIndex;
   289→
   290→	// 선택된 세션에 참가
   291→	const ULocalPlayer* LocalPlayer = GetWorld()->GetFirstLocalPlayerFromController();
   292→	bool bSuccess = SessionInterface->JoinSession(*LocalPlayer->GetPreferredUniqueNetId(), SESSION_NAME, SessionSearch->SearchResults[RoomIndex]);
   293→
   294→	if (bSuccess)
   295→	{
   296→		bIsHost = false;
   297→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Joining session at index %d"), RoomIndex);
   298→	}
   299→	else
   300→	{
   301→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to join session"));
   302→	}
   303→
   304→	return bSuccess;
   305→}
