   409→void USessionManager::OnFindSessionsComplete(bool bWasSuccessful)
   410→{
   411→	bIsSearchInProgress = false;
   412→
   413→	UE_LOG(LogWjWorld, Log, TEXT("SessionManager: OnFindSessionsComplete - Success: %d"), bWasSuccessful);
   414→
   415→	// 대기 중인 검색 요청이 있으면 즉시 실행
   416→	if (PendingSearchRequest.IsSet())
   417→	{
   418→		ENetworkMode PendingMode = PendingSearchRequest.GetValue().Key;
   419→		int32 PendingMax = PendingSearchRequest.GetValue().Value;
   420→		PendingSearchRequest.Reset();
   421→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Executing pending %s search"),
   422→			PendingMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
   423→		FindSessions(PendingMode, PendingMax);
   424→		return;
   425→	}
   426→
   427→	// 마이그레이션 세션 검색인 경우
   428→	if (!PendingMigrationTag.IsEmpty())
   429→	{
   430→		FString SearchTag = PendingMigrationTag;
   431→		PendingMigrationTag.Empty();
   432→
   433→		if (bWasSuccessful && SessionSearch.IsValid())
   434→		{
   435→			for (int32 i = 0; i < SessionSearch->SearchResults.Num(); i++)
   436→			{
   437→				FString FoundTag;
   438→				SessionSearch->SearchResults[i].Session.SessionSettings.Get(FName("MIGRATION_TAG"), FoundTag);
   439→
   440→				if (FoundTag == SearchTag)
   441→				{
   442→					UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Found migration session with tag '%s' at index %d"), *SearchTag, i);
   443→					JoinSession(i);
   444→					return;
   445→				}
   446→			}
   447→
   448→			UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Migration session with tag '%s' not found among %d results"),
   449→				*SearchTag, SessionSearch->SearchResults.Num());
   450→		}
   451→
   452→		// 마이그레이션 세션 미발견 → 빈 결과로 브로드캐스트하여 GameInstance가 재시도 처리
   453→		OnRoomsFoundEvent.Broadcast(false, TArray<FRoomInfo>());
   454→		return;
   455→	}
   456→
   457→	// 일반 세션 검색
   458→	TArray<FRoomInfo> Rooms;
   459→
   460→	if (bWasSuccessful && SessionSearch.IsValid())
   461→	{
   462→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Found %d sessions"), SessionSearch->SearchResults.Num());
   463→
   464→		for (int32 i = 0; i < SessionSearch->SearchResults.Num(); i++)
   465→		{
   466→			const FOnlineSessionSearchResult& Result = SessionSearch->SearchResults[i];
   467→
   468→			UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Session[%d] Details:"), i);
   469→			UE_LOG(LogWjWorld, Log, TEXT("  - IsValid: %d"), Result.IsValid());
   470→			UE_LOG(LogWjWorld, Log, TEXT("  - Ping: %d"), Result.PingInMs);
   471→			UE_LOG(LogWjWorld, Log, TEXT("  - NumPublicConnections: %d"), Result.Session.SessionSettings.NumPublicConnections);
   472→			UE_LOG(LogWjWorld, Log, TEXT("  - NumOpenPublicConnections: %d"), Result.Session.NumOpenPublicConnections);
   473→
   474→			FRoomInfo RoomInfo = ConvertSearchResultToRoomInfo(Result, i);
   475→			UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Room[%d] Name='%s' Mode='%s' Players=%d/%d"),
   476→				i, *RoomInfo.RoomName, *RoomInfo.GameMode,
   477→				RoomInfo.CurrentPlayers, RoomInfo.MaxPlayers);
   478→
   479→			Rooms.Add(RoomInfo);
   480→		}
   481→	}
   482→	else
   483→	{
   484→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: No sessions found or search failed"));
   485→	}
   486→
   487→	OnRoomsFoundEvent.Broadcast(bWasSuccessful, Rooms);
   488→}
