   490→void USessionManager::OnJoinSessionComplete(FName SessionName, EOnJoinSessionCompleteResult::Type Result)
   491→{
   492→	bool bWasSuccessful = (Result == EOnJoinSessionCompleteResult::Success);
   493→	UE_LOG(LogWjWorld, Log, TEXT("SessionManager: OnJoinSessionComplete - Success: %d, Result: %d"), bWasSuccessful, (int32)Result);
   494→
   495→	if (bWasSuccessful)
   496→	{
   497→		bIsInSession = true;
   498→
   499→		if (SessionInterface.IsValid())
   500→		{
   501→			FString ConnectInfo;
   502→			SessionInterface->GetResolvedConnectString(SessionName, ConnectInfo);
   503→
   504→			UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: GetResolvedConnectString returned: '%s'"), *ConnectInfo);
   505→
   506→			// ⭐ 포트가 0이면 7777로 교체
   507→			if (ConnectInfo.Contains(TEXT(":0")))
   508→			{
   509→				// IP 주소 추출 (":"앞부분)
   510→				FString IPAddress;
   511→				FString PortString;
   512→
   513→				if (ConnectInfo.Split(TEXT(":"), &IPAddress, &PortString))
   514→				{
   515→					// 올바른 포트로 재조립
   516→					ConnectInfo = IPAddress + TEXT(":7777");
   517→					UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Fixed ConnectInfo: %s"), *ConnectInfo);
   518→				}
   519→				else
   520→				{
   521→					// Split 실패 시 Fallback
   522→					ConnectInfo = TEXT("127.0.0.1:7777");
   523→					UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Using fallback: %s"), *ConnectInfo);
   524→				}
   525→			}
   526→
   527→			// 검색 시 사용한 네트워크 모드에 맞게 NetDriver 전환
   528→			ApplyNetDriverForMode(LastSearchNetworkMode);
   529→
   530→			APlayerController* PC = GetWorld()->GetFirstPlayerController();
   531→			if (PC && !ConnectInfo.IsEmpty())
   532→			{
   533→				UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Traveling to: %s"), *ConnectInfo);
   534→				PC->ClientTravel(ConnectInfo, ETravelType::TRAVEL_Absolute);
   535→			}
   536→			else
   537→			{
   538→				UE_LOG(LogWjWorld, Error, TEXT("SessionManager: ConnectInfo is empty or PC is null"));
   539→			}
   540→		}
   541→	}
   542→
   543→	OnRoomJoinedEvent.Broadcast(bWasSuccessful);
   544→}
