   573→bool USessionManager::CreateMigrationSession(const FRoomSettings& Settings, const FString& MigrationTag)
   574→{
   575→	if (!SessionInterface.IsValid())
   576→	{
   577→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: SessionInterface is invalid"));
   578→		return false;
   579→	}
   580→
   581→	// 기존 세션 제거
   582→	auto ExistingSession = SessionInterface->GetNamedSession(SESSION_NAME);
   583→	if (ExistingSession != nullptr)
   584→	{
   585→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: Migration - Destroying existing session..."));
   586→
   587→		SessionInterface->DestroySession(SESSION_NAME);
   588→
   589→		int32 WaitCount = 0;
   590→		while (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr && WaitCount < 100)
   591→		{
   592→			FPlatformProcess::Sleep(0.01f);
   593→			WaitCount++;
   594→		}
   595→
   596→		if (SessionInterface->GetNamedSession(SESSION_NAME) != nullptr)
   597→		{
   598→			UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Migration - Failed to destroy existing session"));
   599→			return false;
   600→		}
   601→	}
   602→
   603→	// 네트워크 모드에 맞게 NetDriver 전환
   604→	ApplyNetDriverForMode(Settings.NetworkMode);
   605→
   606→	// 세션 설정 (CreateSession과 동일하되 MIGRATION_TAG 추가)
   607→	FOnlineSessionSettings SessionSettings;
   608→	SessionSettings.NumPublicConnections = Settings.MaxPlayers;
   609→	SessionSettings.bShouldAdvertise = true;
   610→	SessionSettings.bAllowJoinInProgress = true;
   611→	SessionSettings.bAllowJoinViaPresence = false;
   612→	SessionSettings.bAllowJoinViaPresenceFriendsOnly = false;
   613→
   614→	// 네트워크 모드에 따른 설정
   615→	// Steam: bUsesPresence와 bUseLobbiesIfAvailable은 반드시 같은 값이어야 함
   616→	if (Settings.NetworkMode == ENetworkMode::Steam)
   617→	{
   618→		SessionSettings.bIsLANMatch = false;
   619→		SessionSettings.bUsesPresence = true;
   620→		SessionSettings.bUseLobbiesIfAvailable = true;
   621→	}
   622→	else // LAN
   623→	{
   624→		SessionSettings.bIsLANMatch = true;
   625→		SessionSettings.bUsesPresence = false;
   626→		SessionSettings.bUseLobbiesIfAvailable = false;
   627→	}
   628→
   629→	// 커스텀 데이터 설정
   630→	SessionSettings.Set(FName("ROOM_NAME"), Settings.RoomName, EOnlineDataAdvertisementType::ViaOnlineService);
   631→	SessionSettings.Set(FName("GAME_MODE"), Settings.GameMode, EOnlineDataAdvertisementType::ViaOnlineService);
   632→	SessionSettings.Set(FName("MAP_NAME"), Settings.MapName, EOnlineDataAdvertisementType::ViaOnlineService);
   633→	SessionSettings.Set(FName("IS_PRIVATE"), Settings.bIsPrivate, EOnlineDataAdvertisementType::ViaOnlineService);
   634→
   635→	SessionSettings.Set(FName("IN_PROGRESS"), false, EOnlineDataAdvertisementType::ViaOnlineService);
   636→
   637→	// 마이그레이션 태그 추가
   638→	SessionSettings.Set(FName("MIGRATION_TAG"), MigrationTag, EOnlineDataAdvertisementType::ViaOnlineService);
   639→
   640→	// 세션 생성
   641→	const ULocalPlayer* LocalPlayer = GetWorld()->GetFirstLocalPlayerFromController();
   642→	bool bSuccess = SessionInterface->CreateSession(*LocalPlayer->GetPreferredUniqueNetId(), SESSION_NAME, SessionSettings);
   643→
   644→	if (bSuccess)
   645→	{
   646→		LastRoomSettings = Settings;
   647→		bIsHost = true;
   648→		UE_LOG(LogWjWorld, Log, TEXT("SessionManager: Creating migration session '%s' with tag '%s'"),
   649→			*Settings.RoomName, *MigrationTag);
   650→	}
   651→	else
   652→	{
   653→		UE_LOG(LogWjWorld, Error, TEXT("SessionManager: Failed to create migration session"));
   654→	}
   655→
   656→	return bSuccess;
   657→}
