   717→FRoomInfo USessionManager::ConvertSearchResultToRoomInfo(const FOnlineSessionSearchResult& SearchResult, int32 Index)
   718→{
   719→	FRoomInfo RoomInfo;
   720→
   721→	// 기본 정보
   722→	RoomInfo.SearchResultIndex = Index;
   723→	
   724→	// ⭐ 수정: 플레이어 수 계산
   725→	// NumOpenPublicConnections = 열린 슬롯 수
   726→	// 현재 플레이어 = 전체 - 열린 슬롯
   727→	int32 MaxPlayers = SearchResult.Session.SessionSettings.NumPublicConnections;
   728→	int32 OpenSlots = SearchResult.Session.NumOpenPublicConnections;
   729→	
   730→	RoomInfo.MaxPlayers = MaxPlayers;
   731→	RoomInfo.CurrentPlayers = MaxPlayers - OpenSlots;
   732→	
   733→	// ⭐ 최소 1명 보장 (호스트)
   734→	if (RoomInfo.CurrentPlayers <= 0)
   735→	{
   736→		RoomInfo.CurrentPlayers = 1;
   737→	}
   738→	
   739→	RoomInfo.Ping = SearchResult.PingInMs;
   740→
   741→	// 커스텀 데이터
   742→	SearchResult.Session.SessionSettings.Get(FName("ROOM_NAME"), RoomInfo.RoomName);
   743→	SearchResult.Session.SessionSettings.Get(FName("GAME_MODE"), RoomInfo.GameMode);
   744→	SearchResult.Session.SessionSettings.Get(FName("IS_PRIVATE"), RoomInfo.bIsPrivate);
   745→
   746→	// 호스트 이름
   747→	if (SearchResult.Session.OwningUserName.IsEmpty())
   748→	{
   749→		RoomInfo.HostName = TEXT("Unknown");
   750→	}
   751→	else
   752→	{
   753→		RoomInfo.HostName = SearchResult.Session.OwningUserName;
   754→	}
   755→
   756→	// 진행 상태 — 세션 커스텀 설정에서 실제 값 읽기
   757→	SearchResult.Session.SessionSettings.Get(FName("IN_PROGRESS"), RoomInfo.bInProgress);
   758→	RoomInfo.bAllowJoinInProgress = SearchResult.Session.SessionSettings.bAllowJoinInProgress;
   759→
   760→	return RoomInfo;
   761→}
