   763→bool USessionManager::UpdateSessionInProgress(bool bInProgress)
   764→{
   765→	if (!SessionInterface.IsValid())
   766→	{
   767→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: UpdateSessionInProgress - SessionInterface invalid"));
   768→		return false;
   769→	}
   770→
   771→	FNamedOnlineSession* Session = SessionInterface->GetNamedSession(SESSION_NAME);
   772→	if (!Session)
   773→	{
   774→		UE_LOG(LogWjWorld, Warning, TEXT("SessionManager: UpdateSessionInProgress - No active session"));
   775→		return false;
   776→	}
   777→
   778→	Session->SessionSettings.Set(FName("IN_PROGRESS"), bInProgress, EOnlineDataAdvertisementType::ViaOnlineService);
   779→	SessionInterface->UpdateSession(SESSION_NAME, Session->SessionSettings);
   780→
   781→	UE_LOG(LogWjWorld, Log, TEXT("SessionManager: UpdateSessionInProgress(%s)"), bInProgress ? TEXT("true") : TEXT("false"));
   782→	return true;
   783→}
