    78→TArray<FPlayerDisplayInfo> AWjWorldGameStateWaitingRoom::GetPlayerList() const
    79→{
    80→	TArray<FPlayerDisplayInfo> PlayerList;
    81→
    82→	for (APlayerState* PS : PlayerArray)
    83→	{
    84→		AWjWorldPlayerStateBase* WjPS = Cast<AWjWorldPlayerStateBase>(PS);
    85→		if (!WjPS)
    86→		{
    87→			continue;
    88→		}
    89→
    90→		// ⭐ 이름이 비어있으면 스킵 (아직 완전히 초기화되지 않음)
    91→		FString PlayerName = WjPS->GetPlayerName();
    92→		if (PlayerName.IsEmpty())
    93→		{
    94→			UE_LOG(LogWjWorld, Verbose, TEXT("GameStateWaitingRoom: Skipping PlayerState with empty name (ID: %d)"), 
    95→				WjPS->GetPlayerId());
    96→			continue;
    97→		}
    98→
    99→		FPlayerDisplayInfo Info;
   100→		Info.PlayerName = PlayerName;
   101→		Info.bIsReady = WjPS->IsReady();
   102→		Info.PlayerID = WjPS->GetPlayerId();
   103→		Info.bIsHost = (HostPlayerID != -1 && WjPS->GetPlayerId() == HostPlayerID);
   104→
   105→		PlayerList.Add(Info);
   106→	}
   107→
   108→	return PlayerList;
   109→}
