   270→void AWjWorldGameStateWaitingRoom::BroadcastPlayerListChanged()
   271→{
   272→	TArray<FPlayerDisplayInfo> PlayerList = GetPlayerList();
   273→
   274→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Broadcasting player list change - %d players"), PlayerList.Num());
   275→
   276→	// GameInstance에 플레이어 목록 캐시 (호스트 마이그레이션용)
   277→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   278→	{
   279→		GI->CachePlayerList(PlayerList);
   280→	}
   281→
   282→	// 이벤트 브로드캐스트
   283→	OnPlayerListChanged.Broadcast(PlayerList);
   284→}
