   175→
   176→void UWjWorldGameInstance::HandleNetworkFailure(UWorld* World, UNetDriver* NetDriver,
   177→	ENetworkFailure::Type FailureType, const FString& ErrorString)
   178→{
   179→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: HandleNetworkFailure called - Type: %d, Error: %s"),
   180→		static_cast<int32>(FailureType), *ErrorString);
   181→
   182→	// 이미 마이그레이션 중이면 무시
   183→	if (MigrationContext.bIsMigrating)
   184→	{
   185→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure ignored - already migrating"));
   186→		return;
   187→	}
   188→
   189→	// 자신이 호스트(서버)면 마이그레이션 불필요
   190→	if (World && World->GetAuthGameMode() != nullptr)
   191→	{
   192→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure on server - ignoring (Type: %d, Error: %s)"),
   193→			static_cast<int32>(FailureType), *ErrorString);
   194→		return;
   195→	}
   196→
   197→	// 게임 종료 후 WaitingRoom 복귀 중 호스트 퇴장 → 마이그레이션 없이 로비 복귀
   198→	if (bGameEndTraveling)
   199→	{
   200→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure during game-end travel - skipping migration, returning to lobby"));
   201→		bGameEndTraveling = false;
   202→		MigrationFailed();
   203→		return;
   204→	}
   205→
   206→	// 연결 관련 Failure 타입은 모두 마이그레이션 시도
   207→	// (Steam P2P에서는 다양한 에러 타입이 발생할 수 있음)
   208→	switch (FailureType)
   209→	{
   210→	case ENetworkFailure::ConnectionLost:
   211→	case ENetworkFailure::FailureReceived:
   212→	case ENetworkFailure::ConnectionTimeout:
   213→	case ENetworkFailure::PendingConnectionFailure:
   214→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure detected - Type: %d, Error: %s. Beginning host migration."),
   215→			static_cast<int32>(FailureType), *ErrorString);
   216→		BeginHostMigration();
   217→		break;
   218→	default:
   219→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure type %d not handled for migration"),
   220→			static_cast<int32>(FailureType));
   221→		break;
   222→	}
   223→}
   224→
   225→void UWjWorldGameInstance::HandleTravelFailure(UWorld* World, ETravelFailure::Type FailureType, const FString& ErrorString)
   226→{
   227→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: HandleTravelFailure called - Type: %d, Error: %s"),
   228→		static_cast<int32>(FailureType), *ErrorString);
   229→
   230→	// 이미 마이그레이션 중이면 무시
   231→	if (MigrationContext.bIsMigrating)
   232→	{
   233→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: TravelFailure ignored - already migrating"));
   234→		return;
   235→	}
   236→
   237→	// 자신이 호스트(서버)면 마이그레이션 불필요
   238→	if (World && World->GetAuthGameMode() != nullptr)
   239→	{
   240→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure on server - ignoring"));
   241→		return;
   242→	}
   243→
   244→	// 게임 종료 후 WaitingRoom 복귀 중 호스트 퇴장 → 마이그레이션 없이 로비 복귀
   245→	if (bGameEndTraveling)
   246→	{
   247→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure during game-end travel - skipping migration, returning to lobby"));
   248→		bGameEndTraveling = false;
   249→		MigrationFailed();
   250→		return;
   251→	}
   252→
   253→	// ServerTravel 실패 시 호스트 마이그레이션 시도
   254→	switch (FailureType)
   255→	{
   256→	case ETravelFailure::ServerTravelFailure:
   257→	case ETravelFailure::ClientTravelFailure:
   258→	case ETravelFailure::TravelFailure:
   259→	case ETravelFailure::PackageMissing:
   260→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: TravelFailure detected - Type: %d. Beginning host migration."),
   261→			static_cast<int32>(FailureType));
   262→		BeginHostMigration();
   263→		break;
   264→	default:
   265→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: TravelFailure type %d not handled for migration"),
   266→			static_cast<int32>(FailureType));
   267→		break;
   268→	}
   269→}
