   418→void UWjWorldGameInstance::MigrationCreateSession()
   419→{
   420→	SetMigrationState(EHostMigrationState::CreatingSession);
   421→
   422→	if (!SessionManager)
   423→	{
   424→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: MigrationCreateSession - SessionManager is null"));
   425→		MigrationFailed();
   426→		return;
   427→	}
   428→
   429→	// 콜백 바인딩
   430→	SessionManager->OnRoomCreatedEvent.AddDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   431→
   432→	bool bSuccess = SessionManager->CreateMigrationSession(
   433→		MigrationContext.CachedRoomSettings,
   434→		MigrationContext.MigrationSessionTag);
   435→
   436→	if (!bSuccess)
   437→	{
   438→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   439→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to create migration session"));
   440→		MigrationRetryOrFail();
   441→	}
   442→}
   443→
   444→void UWjWorldGameInstance::OnMigrationSessionCreated(bool bWasSuccessful)
   445→{
   446→	if (SessionManager)
   447→	{
   448→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   449→	}
   450→
   451→	if (bWasSuccessful)
   452→	{
   453→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session created - ServerTraveling to WaitingRoom"));
   454→		SetMigrationState(EHostMigrationState::Complete);
   455→
   456→		UWorld* World = GetWorld();
   457→		if (World)
   458→		{
   459→			World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   460→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   461→			World->ServerTravel(Settings->GetWaitingRoomOpenLevelURL());
   462→		}
   463→	}
   464→	else
   465→	{
   466→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration session creation failed"));
   467→		MigrationRetryOrFail();
   468→	}
   469→}
   470→
   471→void UWjWorldGameInstance::MigrationSearchForNewHost()
   472→{
   473→	SetMigrationState(EHostMigrationState::SearchingSession);
   474→
   475→	if (!SessionManager)
   476→	{
   477→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: MigrationSearchForNewHost - SessionManager is null"));
   478→		MigrationFailed();
   479→		return;
   480→	}
   481→
   482→	// 콜백 바인딩
   483→	SessionManager->OnRoomsFoundEvent.AddDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   484→
   485→	bool bSuccess = SessionManager->FindMigrationSession(MigrationContext.MigrationSessionTag);
   486→
   487→	if (!bSuccess)
   488→	{
   489→		SessionManager->OnRoomsFoundEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   490→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to start migration session search"));
   491→		MigrationRetryOrFail();
   492→	}
   493→}
   494→
   495→void UWjWorldGameInstance::OnMigrationSearchResult(bool bWasSuccessful, const TArray<FRoomInfo>& Rooms)
   496→{
   497→	if (SessionManager)
   498→	{
   499→		SessionManager->OnRoomsFoundEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   500→	}
   501→
   502→	if (bWasSuccessful)
   503→	{
   504→		// JoinSession은 FindMigrationSession 내부에서 자동으로 호출됨
   505→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session found and joining"));
   506→		SetMigrationState(EHostMigrationState::JoiningSession);
   507→
   508→		UWorld* World = GetWorld();
   509→		if (World)
   510→		{
   511→			World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   512→		}
   513→		// JoinSession → ClientTravel이 자동으로 발생
   514→	}
   515→	else
   516→	{
   517→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration session not found - will retry"));
   518→		MigrationRetryOrFail();
   519→	}
   520→}
   521→
   522→void UWjWorldGameInstance::MigrationRetryOrFail()
   523→{
   524→	MigrationContext.RetryCount++;
   525→
   526→	// 타임아웃 체크
   527→	double ElapsedTime = FPlatformTime::Seconds() - MigrationContext.MigrationStartTime;
   528→	if (ElapsedTime >= FHostMigrationContext::MigrationTimeout)
   529→	{
   530→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration timed out after %.1f seconds"), ElapsedTime);
   531→		MigrationFailed();
   532→		return;
   533→	}
   534→
   535→	// 최대 재시도 횟수 체크
   536→	if (MigrationContext.RetryCount >= FHostMigrationContext::MaxRetryCount)
   537→	{
   538→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration max retries (%d) reached"), FHostMigrationContext::MaxRetryCount);
   539→		MigrationFailed();
   540→		return;
   541→	}
   542→
   543→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration retry %d/%d in %.1f seconds"),
   544→		MigrationContext.RetryCount, FHostMigrationContext::MaxRetryCount, FHostMigrationContext::RetryInterval);
   545→
   546→	UWorld* World = GetWorld();
   547→	if (World)
   548→	{
   549→		if (MigrationContext.bIsNewHost)
   550→		{
   551→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   552→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationCreateSession),
   553→				FHostMigrationContext::RetryInterval, false);
   554→		}
   555→		else
   556→		{
   557→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   558→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationSearchForNewHost),
   559→				FHostMigrationContext::RetryInterval, false);
   560→		}
   561→	}
   562→}
   563→
   564→void UWjWorldGameInstance::OnMigrationTimeout()
   565→{
   566→	UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration timeout (%.0f seconds)"),
   567→		FHostMigrationContext::MigrationTimeout);
   568→	MigrationFailed();
   569→}
   570→
   571→void UWjWorldGameInstance::MigrationFailed()
   572→{
   573→	SetMigrationState(EHostMigrationState::Failed);
   574→
   575→	UWorld* World = GetWorld();
   576→	if (World)
   577→	{
   578→		World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   579→		World->GetTimerManager().ClearTimer(MigrationRetryHandle);
   580→	}
   581→
   582→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration failed - returning to lobby"));
   583→
   584→	// 세션 정리
   585→	if (SessionManager)
   586→	{
   587→		SessionManager->DestroySession();
   588→	}
   589→
   590→	// 마이그레이션 컨텍스트 리셋
   591→	MigrationContext.Reset();
   592→	bGameEndTraveling = false;
   593→	SetMigrationState(EHostMigrationState::None);
   594→
   595→	// 로비로 복귀
   596→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   597→	UGameplayStatics::OpenLevel(this, FName(*Settings->GetLobbyMapPath()));
   598→}
   599→
   600→void UWjWorldGameInstance::SetMigrationState(EHostMigrationState NewState)
   601→{
   602→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration state: %d → %d"),
   603→		static_cast<int32>(MigrationState), static_cast<int32>(NewState));
   604→	MigrationState = NewState;
   605→}
