    37→
    38→	// MinigameCatalog에서 AllowedAbilityTags, StatNamespace 설정
    39→	if (GameState && GameMode.IsValid())
    40→	{
    41→		const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
    42→		if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
    43→		{
    44→			UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
    45→			FString CurrentGameModeId = GameMode->GetMapOption();
    46→			// GameModeId는 URL Options에서 직접 가져오기
    47→			const FWjWorldMinigameDefinition* Def = nullptr;
    48→			if (Catalog)
    49→			{
    50→				// GameModePlay의 InitGame에서 파싱된 GameModeId를 사용해야 하므로
    51→				// 카탈로그에서 현재 GameRule 클래스를 기준으로 찾기
    52→				for (const FWjWorldMinigameDefinition& MiniDef : Catalog->Minigames)
    53→				{
    54→					if (MiniDef.GameRuleClass == GetClass())
    55→					{
    56→						Def = &MiniDef;
    57→						break;
    58→					}
    59→				}
    60→			}
    61→
    62→			if (Def)
    63→			{
    64→				GameState->SetAllowedAbilityTags(Def->AllowedAbilityTags);
    65→				GameState->SetStatNamespace(Def->StatNamespace);
    66→				GameState->SetDefaultCameraMode(Def->DefaultCameraMode);
    67→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: AllowedAbilityTags set (%d tags), StatNamespace='%s', CameraMode=%d"),
    68→					Def->AllowedAbilityTags.Num(), *Def->StatNamespace.ToString(), static_cast<int32>(Def->DefaultCameraMode));
    69→			}
    70→		}
    71→	}
    72→
    73→	UWorld* World = GetWorld();
    74→	if (World)
    75→	{
    76→		World->GetTimerManager().SetTimer(DelayStartHandle, FTimerDelegate::CreateLambda([this]() {
    77→			if (GameMode.IsValid())
    78→			{
    79→				GameMode->StartGame(SecondsForGameStartCount);
    80→			}
    81→			}), StartDelay, false);
    82→
    83→		ChangeGamePhase(EGamePhase::Ready);
    84→	}
    85→
    86→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Ready"));
    87→}
