   114→void UWjWorldGameRuleBase::OnGameEnd()
   115→{
   116→	if (!HasAuthority()) return;
   117→
   118→	UWorld* World = GetWorld();
   119→	if (World)
   120→	{
   121→		// 세션 종료 (InProgress → Ended) - WaitingRoom 복귀 후 다시 StartSession 가능하게
   122→		if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(World->GetGameInstance()))
   123→		{
   124→			GI->EndGame();
   125→		}
   126→
   127→		// ServerTravel URL 미리 계산 (타이머 콜백에서 this 접근 문제 방지)
   128→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   129→		FString TravelURL = Settings->GetWaitingRoomServerTravelURL();
   130→
   131→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase::OnGameEnd - Will travel to: %s in %f seconds"), *TravelURL, SecondsForGotoWaitingRoom);
   132→
   133→		// Lobby 맵을 사용하되 GameMode는 WaitingRoom으로 오버라이드
   134→		// World를 WeakPtr로 캡처하여 타이머 콜백에서 안전하게 접근
   135→		TWeakObjectPtr<UWorld> WeakWorld = World;
   136→		World->GetTimerManager().SetTimer(GotoWaitingRoomHandle, FTimerDelegate::CreateLambda([WeakWorld, TravelURL]() {
   137→			if (UWorld* ValidWorld = WeakWorld.Get())
   138→			{
   139→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase - Executing ServerTravel to: %s"), *TravelURL);
   140→				ValidWorld->ServerTravel(TravelURL);
   141→			}
   142→			else
   143→			{
   144→				UE_LOG(LogWjWorld, Error, TEXT("GameRuleBase - ServerTravel failed: World is invalid"));
   145→			}
   146→		}), SecondsForGotoWaitingRoom, false);
   147→
   148→		ChangeGamePhase(EGamePhase::Finished);
   149→	}
   150→
   151→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Game Ended"));
   152→}
