    86→void UWjWorldGameRuleApproachingWall::OnGameStart()
    87→{
    88→	if (!HasAuthority()) return;
    89→
    90→	Super::OnGameStart();
    91→
    92→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnGameStart() - Players: %d (Min: %d)"),
    93→		TotalPlayerCount, MinimumPlayerCount);
    94→
    95→	bIsGameStarted = true;
    96→
    97→	// 엣지 케이스: 플레이어가 없거나 부족한 경우
    98→	if (TotalPlayerCount <= 0)
    99→	{
   100→		UE_LOG(LogWjWorld, Warning, TEXT("UWjWorldGameRuleApproachingWall::OnGameStart - No players, ending game"));
   101→		bGameOverConditionMet = true;
   102→		WinnerPlayer = nullptr;
   103→		OnGameEnd();
   104→		return;
   105→	}
   106→
   107→	// 엣지 케이스: 플레이어가 1명뿐인 경우 즉시 승리
   108→	if (TotalPlayerCount == 1 && AlivePlayerCount == 1)
   109→	{
   110→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnGameStart - Solo player wins by default"));
   111→		if (AlivePlayers.Num() > 0 && AlivePlayers[0].IsValid())
   112→		{
   113→			WinnerPlayer = AlivePlayers[0];
   114→		}
   115→		bGameOverConditionMet = true;
   116→		OnGameEnd();
   117→		return;
   118→	}
   119→
   120→	InternalGameStartProcess();
   121→}
