   148→void UWjWorldGameRuleApproachingWall::OnPlayerJoined(AWjWorldPlayerStatePlay* Player)
   149→{
   150→	Super::OnPlayerJoined(Player);
   151→
   152→	if (!HasAuthority() || !Player) return;
   153→
   154→	// 게임 진행 중 입장한 관전자는 참여자로 등록하지 않음
   155→	if (IsGameInProgress())
   156→	{
   157→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerJoined - Spectator joined mid-game: %s"),
   158→			*Player->GetPlayerName());
   159→		return;
   160→	}
   161→
   162→	// 플레이어를 생존자/참여자 목록에 추가
   163→	AlivePlayers.Add(Player);
   164→	AllParticipants.Add(Player);
   165→	AlivePlayerCount++;
   166→	TotalPlayerCount++;
   167→
   168→	UpdateGameData();
   169→
   170→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerJoined - Player: %s, Alive: %d, Total: %d"),
   171→		*Player->GetPlayerName(), AlivePlayerCount, TotalPlayerCount);
   172→}
