   174→void UWjWorldGameRuleApproachingWall::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   175→{
   176→	Super::OnPlayerLeft(Player);
   177→
   178→	if (!HasAuthority() || !Player) return;
   179→
   180→	// 관전자(참여자 목록에 없는 플레이어)는 게임 카운터에 영향 없음
   181→	if (AllParticipants.Remove(Player) == 0)
   182→	{
   183→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerLeft - Spectator left: %s"), *Player->GetPlayerName());
   184→		return;
   185→	}
   186→
   187→	// 플레이어의 캐릭터 처리 (좀비 상태 방지)
   188→	APawn* PlayerPawn = Player->GetPawn();
   189→	AWjWorldCharacterPlay* PlayerCharacter = Cast<AWjWorldCharacterPlay>(PlayerPawn);
   190→	if (PlayerCharacter && !PlayerCharacter->IsEliminated())
   191→	{
   192→		// 캐릭터를 제거 상태로 만들고 파괴
   193→		PlayerCharacter->OnEliminated();
   194→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerLeft - Character eliminated for leaving player"));
   195→	}
   196→
   197→	// 플레이어가 나가면 생존자 목록에서 제거
   198→	if (AlivePlayers.Remove(Player) > 0)
   199→	{
   200→		AlivePlayerCount--;
   201→	}
   202→	TotalPlayerCount--;
   203→
   204→	UpdateGameData();
   205→
   206→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerLeft - Player: %s, Alive: %d, Total: %d"),
   207→		*Player->GetPlayerName(), AlivePlayerCount, TotalPlayerCount);
   208→
   209→	// 엣지 케이스: 모든 플레이어가 나간 경우
   210→	if (TotalPlayerCount <= 0)
   211→	{
   212→		UE_LOG(LogWjWorld, Warning, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerLeft - All players left, ending game"));
   213→		bGameOverConditionMet = true;
   214→		WinnerPlayer = nullptr; // 승자 없음
   215→		OnGameEnd();
   216→		return;
   217→	}
   218→
   219→	// 남은 플레이어 수 확인하여 승리 조건 체크
   220→	if (bIsGameStarted && CheckWinCondition())
   221→	{
   222→		// 마지막 생존자를 승자로 설정
   223→		if (AlivePlayerCount == 1 && AlivePlayers.Num() > 0)
   224→		{
   225→			for (const auto& AlivePlayer : AlivePlayers)
   226→			{
   227→				if (AlivePlayer.IsValid())
   228→				{
   229→					WinnerPlayer = AlivePlayer;
   230→					break;
   231→				}
   232→			}
   233→		}
   234→		bGameOverConditionMet = true;
   235→		OnGameEnd();
   236→	}
   237→}
