   239→void UWjWorldGameRuleApproachingWall::OnPlayerEliminated(AWjWorldCharacterPlay* EliminatedCharacter)
   240→{
   241→	if (!HasAuthority() || !EliminatedCharacter) return;
   242→
   243→	// 이미 제거된 캐릭터면 무시
   244→	if (EliminatedCharacter->IsEliminated()) return;
   245→
   246→	// 공격자가 있으면 킬 스탯 기록
   247→	AWjWorldCharacterPlay* Attacker = EliminatedCharacter->GetLastAttacker();
   248→	if (Attacker && !Attacker->IsEliminated())
   249→	{
   250→		AWjWorldPlayerStatePlay* AttackerPS = Attacker->GetPlayerState<AWjWorldPlayerStatePlay>();
   251→		if (AttackerPS)
   252→		{
   253→			RecordKillStat(AttackerPS);
   254→			UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerEliminated - Kill recorded for %s"),
   255→				*AttackerPS->GetPlayerName());
   256→		}
   257→	}
   258→
   259→	// 캐릭터 사망 처리
   260→	EliminatedCharacter->OnEliminated();
   261→
   262→	// PlayerState 가져오기 + AW PlayerData 업데이트
   263→	AWjWorldPlayerStatePlay* PlayerState = EliminatedCharacter->GetPlayerState<AWjWorldPlayerStatePlay>();
   264→	if (PlayerState)
   265→	{
   266→		if (UApproachingWallPlayerDataComponent* PlayerData = PlayerState->GetGameData<UApproachingWallPlayerDataComponent>())
   267→		{
   268→			PlayerData->OnEliminated();
   269→		}
   270→
   271→		// 생존자 목록에서 제거
   272→		if (AlivePlayers.Remove(PlayerState) > 0)
   273→		{
   274→			AlivePlayerCount--;
   275→		}
   276→
   277→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerEliminated - Player: %s eliminated. Alive: %d"),
   278→			*PlayerState->GetPlayerName(), AlivePlayerCount);
   279→	}
   280→
   281→	UpdateGameData();
   282→
   283→	// 엣지 케이스: 동시에 모두 제거된 경우 (AlivePlayerCount == 0)
   284→	if (AlivePlayerCount == 0)
   285→	{
   286→		UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::OnPlayerEliminated - All players eliminated simultaneously (Draw)"));
   287→		bGameOverConditionMet = true;
   288→		WinnerPlayer = nullptr; // 무승부
   289→		OnGameEnd();
   290→		return;
   291→	}
   292→
   293→	// 승리 조건 체크
   294→	if (bIsGameStarted && CheckWinCondition())
   295→	{
   296→		bGameOverConditionMet = true;
   297→
   298→		// 마지막 생존자를 승자로 설정
   299→		if (AlivePlayerCount == 1 && AlivePlayers.Num() > 0)
   300→		{
   301→			for (const auto& AlivePlayer : AlivePlayers)
   302→			{
   303→				if (AlivePlayer.IsValid())
   304→				{
   305→					WinnerPlayer = AlivePlayer;
   306→					break;
   307→				}
   308→			}
   309→		}
   310→
   311→		UE_LOG(LogWjWorld, Log, TEXT("Win condition met! Winner: %s"),
