   332→void UWjWorldGameRuleApproachingWall::TickGameRule(float DeltaTime)
   333→{
   334→	if (!HasAuthority()) return;
   335→	if (!bGameStartInternalProcessDone) return;
   336→
   337→	TimeSinceLastBrickMoveSignal += DeltaTime;
   338→
   339→	if (TimeSinceLastBrickMoveSignal >= BrickMoveSignalInterval
   340→		&& bGameOverConditionMet == false)
   341→	{
   342→		// 오차 누적 방지
   343→		TimeSinceLastBrickMoveSignal -= BrickMoveSignalInterval;
   344→
   345→		++BrickMoveSignalCount;
   346→
   347→		bool bAnySafeZoneExist = false;
   348→		ShrinkSafeZones(bAnySafeZoneExist);
   349→
   350→		if (bAnySafeZoneExist)
   351→		{
   352→			// 중앙 할당: 이동 시작 전에 각 벽돌에 타겟 배정
   353→			AssignBrickTargets();
   354→
   355→			if (WallManager)
   356→			{
   357→				WallManager->WallMoveStart(UWjWorldWallManager::GetBrickMovementAllowedTime(BrickMoveSignalCount));
   358→			}
   359→
   360→			GameLevelUp(BrickMoveSignalCount);
   361→			UpdateGameData();
   362→
   363→			if (PredictNextLevelIsLast())
   364→			{
   365→				OnGameEndPredict(BrickMoveSignalInterval);
   366→			}
   367→		}
   368→		else
   369→		{
   370→			bGameOverConditionMet = true;
   371→			UE_LOG(LogWjWorld, Log, TEXT("No Safe Zone Exist. Game Over Condition Met."));
   372→
   373→			// 안전 구역이 없어져서 게임이 끝날 때, 마지막 생존자가 승자
   374→			if (AlivePlayerCount == 1 && AlivePlayers.Num() > 0)
   375→			{
   376→				for (const auto& AlivePlayer : AlivePlayers)
   377→				{
   378→					if (AlivePlayer.IsValid())
   379→					{
   380→						WinnerPlayer = AlivePlayer;
   381→						break;
   382→					}
   383→				}
   384→				UE_LOG(LogWjWorld, Log, TEXT("Last player standing wins: %s"),
   385→					WinnerPlayer.IsValid() ? *WinnerPlayer->GetPlayerName() : TEXT("None"));
   386→			}
   387→
   388→			OnGameEnd();
   389→		}
   390→	}
   391→
   392→	if (WallManager)
   393→	{
   394→		WallManager->Tick(DeltaTime);
   395→	}
   396→}
