   489→void UWjWorldGameRuleApproachingWall::ShrinkSafeZones(bool& bAnySafeZoneExist)
   490→{
   491→	FloodFillPoints.Empty();
   492→
   493→	for (auto Iter = CurrentSafeZonePoints.CreateIterator(); Iter; ++Iter)
   494→	{
   495→		FIntPoint& SafeZonePoint = *Iter;
   496→		// 4방향만 체크 (대각선 제외)
   497→		TArray<FIntPoint> AdjacentPoints = {
   498→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y),
   499→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y),
   500→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y + 1),
   501→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y - 1)
   502→		};
   503→
   504→		for (const FIntPoint& AdjacentPoint : AdjacentPoints)
   505→		{
   506→			if (CurrentSafeZonePoints.Contains(AdjacentPoint) == false)
   507→			{
   508→				FloodFillPoints.Add(SafeZonePoint);
   509→				break;
   510→			}
   511→		}
   512→	}
   513→
   514→	for(const FIntPoint& PointToRemove : FloodFillPoints)
   515→	{
   516→		CurrentSafeZonePoints.Remove(PointToRemove);
   517→	}
   518→
   519→	bAnySafeZoneExist = CurrentSafeZonePoints.Num() > 1;
   520→}
