   522→bool UWjWorldGameRuleApproachingWall::PredictNextLevelIsLast()
   523→{
   524→	TSet<FIntPoint> SimulatedSafeZones = CurrentSafeZonePoints;
   525→	TSet<FIntPoint> SimulatedFloodFillPoints;
   526→
   527→	for (auto Iter = SimulatedSafeZones.CreateIterator(); Iter; ++Iter)
   528→	{
   529→		FIntPoint& SafeZonePoint = *Iter;
   530→		// 4방향만 체크 (대각선 제외)
   531→		TArray<FIntPoint> AdjacentPoints = {
   532→			FIntPoint(SafeZonePoint.X + 1, SafeZonePoint.Y),
   533→			FIntPoint(SafeZonePoint.X - 1, SafeZonePoint.Y),
   534→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y + 1),
   535→			FIntPoint(SafeZonePoint.X, SafeZonePoint.Y - 1)
   536→		};
   537→
   538→		for (const FIntPoint& AdjacentPoint : AdjacentPoints)
   539→		{
   540→			if (SimulatedSafeZones.Contains(AdjacentPoint) == false)
   541→			{
   542→				SimulatedFloodFillPoints.Add(SafeZonePoint);
   543→				break;
   544→			}
   545→		}
   546→	}
   547→
   548→	for (const FIntPoint& PointToRemove : SimulatedFloodFillPoints)
   549→	{
   550→		SimulatedSafeZones.Remove(PointToRemove);
   551→	}
   552→
   553→	return SimulatedSafeZones.Num() <= 1;
   554→}
