   556→void UWjWorldGameRuleApproachingWall::AssignBrickTargets()
   557→{
   558→	if (FloodFillPoints.Num() == 0) return;
   559→
   560→	UWorld* World = GetWorld();
   561→	if (!World) return;
   562→
   563→	// Standard 타입 벽돌 수집 (현재 그리드 좌표와 함께)
   564→	struct FBrickCandidate
   565→	{
   566→		UWjWorldBrickMovement* Movement;
   567→		FIntPoint GridPos;
   568→	};
   569→
   570→	TArray<FBrickCandidate> AvailableBricks;
   571→
   572→	for (TActorIterator<AWjWorldBrickActor> It(World); It; ++It)
   573→	{
   574→		AWjWorldBrickActor* BrickActor = *It;
   575→		if (!BrickActor) continue;
   576→
   577→		UWjWorldBrickComponent* BrickComp = BrickActor->GetBrickComponent();
   578→		if (!BrickComp) continue;
   579→		if (BrickComp->GetBrickProperties().BrickType != EWjWorldBrickType::Standard) continue;
   580→
   581→		UWjWorldBrickMovement* Movement = BrickComp->GetBrickMovement();
   582→		if (!Movement) continue;
   583→		if (Movement->IsMoving()) continue;
   584→
   585→		AvailableBricks.Add({ Movement, Movement->GetCurrentGridPosition() });
   586→	}
   587→
   588→	// Greedy 할당: 각 FloodFillPoint에 가장 가까운 미할당 벽돌 배정
   589→	TSet<int32> AssignedBrickIndices;
   590→
   591→	for (const FIntPoint& Target : FloodFillPoints)
   592→	{
   593→		int32 BestIndex = -1;
   594→		int32 BestDistance = INT_MAX;
   595→
   596→		for (int32 i = 0; i < AvailableBricks.Num(); i++)
   597→		{
   598→			if (AssignedBrickIndices.Contains(i)) continue;
   599→
   600→			// 맨해튼 거리
   601→			int32 Distance = FMath::Abs(AvailableBricks[i].GridPos.X - Target.X)
   602→				+ FMath::Abs(AvailableBricks[i].GridPos.Y - Target.Y);
   603→
   604→			if (Distance < BestDistance)
   605→			{
   606→				BestDistance = Distance;
   607→				BestIndex = i;
   608→			}
   609→		}
   610→
   611→		if (BestIndex >= 0)
   612→		{
   613→			AvailableBricks[BestIndex].Movement->SetAssignedTarget(Target);
   614→			AssignedBrickIndices.Add(BestIndex);
   615→		}
   616→		else
   617→		{
   618→			UE_LOG(LogWjWorld, Warning, TEXT("AssignBrickTargets: No available brick for target (%d, %d)"), Target.X, Target.Y);
   619→		}
   620→	}
   621→
   622→	UE_LOG(LogWjWorld, Log, TEXT("AssignBrickTargets: %d targets, %d bricks available, %d assigned"),
   623→		FloodFillPoints.Num(), AvailableBricks.Num(), AssignedBrickIndices.Num());
   624→}
