   626→void UWjWorldGameRuleApproachingWall::RecordKillStat(AWjWorldPlayerStatePlay* KillerPlayerState)
   627→{
   628→	if (!KillerPlayerState) return;
   629→
   630→	// 서버에서만 실행
   631→	if (!HasAuthority()) return;
   632→
   633→	// 킬러의 PlayerController를 통해 스탯 기록
   634→	APlayerController* KillerPC = Cast<APlayerController>(KillerPlayerState->GetOwner());
   635→	if (KillerPC && KillerPC->IsLocalController())
   636→	{
   637→		// 로컬 플레이어면 직접 기록
   638→		UWjWorldStatsSubsystem* Stats = GetWorld()->GetGameInstance()->GetSubsystem<UWjWorldStatsSubsystem>();
   639→		if (Stats)
   640→		{
   641→			Stats->IncrementLocalStat(WjWorldStats::ApproachingWall::Kills);
   642→			Stats->StoreStats();
   643→		}
   644→	}
   645→	// 원격 플레이어의 킬은 게임 종료 시 클라이언트에서 각자 처리하거나
   646→	// 별도 RPC로 처리해야 함 (현재는 로컬 플레이어만 즉시 기록)
   647→
   648→	UE_LOG(LogWjWorld, Log, TEXT("UWjWorldGameRuleApproachingWall::RecordKillStat - Recorded kill for %s"),
   649→		*KillerPlayerState->GetPlayerName());
   650→}
