   176→void UWjWorldGameRuleSumo::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   177→{
   178→	Super::OnPlayerLeft(Player);
   179→
   180→	if (!HasAuthority() || !Player) return;
   181→
   182→	// 관전자(AllPlayers에 없는 플레이어)는 게임 카운터에 영향 없음
   183→	if (AllPlayers.Remove(Player) == 0)
   184→	{
   185→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Spectator left: %s"), *Player->GetPlayerName());
   186→		return;
   187→	}
   188→
   189→	// 캐릭터 제거 처리
   190→	APawn* PlayerPawn = Player->GetPawn();
   191→	AWjWorldCharacterPlay* PlayerCharacter = Cast<AWjWorldCharacterPlay>(PlayerPawn);
   192→	if (PlayerCharacter && !PlayerCharacter->IsEliminated())
   193→	{
   194→		PlayerCharacter->OnEliminated();
   195→	}
   196→
   197→	if (AlivePlayers.Remove(Player) > 0)
   198→	{
   199→		AlivePlayerCount--;
   200→	}
   201→	TotalPlayerCount--;
   202→
   203→	UpdateGameData();
   204→
   205→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Player Left - %s, Alive: %d, Total: %d"),
   206→		*Player->GetPlayerName(), AlivePlayerCount, TotalPlayerCount);
   207→
   208→	// 모든 참여자 이탈
   209→	if (TotalPlayerCount <= 0)
   210→	{
   211→		bGameOverConditionMet = true;
   212→		WinnerPlayer = nullptr;
   213→		OnGameEnd();
   214→		return;
   215→	}
   216→
   217→	// 승리 조건 체크
   218→	if (bIsGameStarted && bIsRoundActive && AlivePlayerCount <= 1)
   219→	{
   220→		OnRoundEnd();
   221→	}
   222→}
