   224→void UWjWorldGameRuleSumo::OnPlayerEliminated(AWjWorldCharacterPlay* EliminatedCharacter)
   225→{
   226→	if (!HasAuthority() || !EliminatedCharacter) return;
   227→	if (EliminatedCharacter->IsEliminated()) return;
   228→
   229→	AWjWorldPlayerStatePlay* VictimPS = EliminatedCharacter->GetPlayerState<AWjWorldPlayerStatePlay>();
   230→	FString VictimName = VictimPS ? VictimPS->GetPlayerName() : TEXT("Unknown");
   231→
   232→	// ???ㅽ꺈 湲곕줉 + ?ы뵾??
   233→	AWjWorldCharacterPlay* Attacker = EliminatedCharacter->GetLastAttacker();
   234→	FString KillerName;
   235→	if (Attacker && !Attacker->IsEliminated())
   236→	{
   237→		AWjWorldPlayerStatePlay* AttackerPS = Attacker->GetPlayerState<AWjWorldPlayerStatePlay>();
   238→		if (AttackerPS)
   239→		{
   240→			KillerName = AttackerPS->GetPlayerName();
   241→			RecordKillStat(AttackerPS);
   242→		}
   243→	}
   244→
   245→	// ?ы뵾??釉뚮줈?쒖틦?ㅽ듃
   246→	BroadcastKillFeed(KillerName, VictimName);
   247→
   248→	// 罹먮┃???쒓굅
   249→	EliminatedCharacter->OnEliminated();
   250→
   251→	// PlayerData ?낅뜲?댄듃
   252→	if (VictimPS)
   253→	{
   254→		if (USumoPlayerDataComponent* PlayerData = VictimPS->GetGameData<USumoPlayerDataComponent>())
   255→		{
   256→			PlayerData->OnEliminated();
   257→		}
   258→
   259→		// ?덈씫 ?쒖꽌 湲곕줉
   260→		EliminationOrder.Add(VictimPS);
   261→
   262→		if (AlivePlayers.Remove(VictimPS) > 0)
   263→		{
   264→			AlivePlayerCount--;
   265→		}
   266→
   267→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Player eliminated: %s. Alive: %d (Round %d)"),
   268→			*VictimPS->GetPlayerName(), AlivePlayerCount, CurrentRound);
   269→	}
   270→
   271→	UpdateGameData();
   272→
   273→	// ?숈떆 ?꾩썝 ?덈씫
   274→	if (AlivePlayerCount == 0)
   275→	{
   276→		OnRoundEnd();
   277→		return;
   278→	}
   279→
   280→	// ?쇱슫???밸━ 議곌굔 (1紐??댄븯 ?앹〈)
   281→	if (bIsGameStarted && bIsRoundActive && AlivePlayerCount <= 1)
   282→	{
   283→		OnRoundEnd();
   284→	}
   285→}
