   354→void UWjWorldGameRuleSumo::AwardRoundScores()
   355→{
   356→	// ?덈씫 ?쒖꽌 ??닚?쇰줈 ?먯닔 遺??
   357→	// 泥?踰덉㎏ ?덈씫 = 1?? ??踰덉㎏ = 2?? ... 留덉?留??앹〈 = N??
   358→	int32 NumPlayers = EliminationOrder.Num();
   359→	for (int32 i = 0; i < NumPlayers; i++)
   360→	{
   361→		if (EliminationOrder[i].IsValid())
   362→		{
   363→			int32 Score = i + 1; // 泥??덈씫??1?? 留덉?留??앹〈??N??
   364→			AWjWorldPlayerStatePlay* PS = EliminationOrder[i].Get();
   365→			if (USumoPlayerDataComponent* PlayerData = PS->GetGameData<USumoPlayerDataComponent>())
   366→			{
   367→				PlayerData->AddScore(Score);
   368→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Round score - %s: +%d (Total: %d)"),
   369→					*PS->GetPlayerName(), Score, PlayerData->GetTotalScore());
   370→			}
   371→		}
   372→	}
