   375→void UWjWorldGameRuleSumo::UpdatePlayerScores()
   376→{
   377→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   378→	if (!GameState) return;
   379→
   380→	USumoGameDataComponent* GameData = GameState->GetGameData<USumoGameDataComponent>();
   381→	if (!GameData) return;
   382→
   383→	TArray<FSumoPlayerScore> Scores;
   384→	for (const auto& WeakPS : AllPlayers)
   385→	{
   386→		if (!WeakPS.IsValid()) continue;
   387→		AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   388→		USumoPlayerDataComponent* PlayerData = PS->GetGameData<USumoPlayerDataComponent>();
   389→
   390→		FSumoPlayerScore Entry;
   391→		Entry.PlayerName = PS->GetPlayerName();
   392→		Entry.Score = PlayerData ? PlayerData->GetTotalScore() : 0;
   393→		Scores.Add(Entry);
   394→	}
   395→
   396→	// ?먯닔 ?대┝李⑥닚 ?뺣젹
   397→	Scores.Sort([](const FSumoPlayerScore& A, const FSumoPlayerScore& B) { return A.Score > B.Score; });
   398→	GameData->SetPlayerScores(Scores);
   399→}
