   401→AWjWorldPlayerStatePlay* UWjWorldGameRuleSumo::GetFinalWinner() const
   402→{
   403→	AWjWorldPlayerStatePlay* BestPlayer = nullptr;
   404→	int32 BestScore = -1;
   405→
   406→	for (const auto& WeakPS : AllPlayers)
   407→	{
   408→		if (!WeakPS.IsValid()) continue;
   409→		AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   410→		USumoPlayerDataComponent* PlayerData = PS->GetGameData<USumoPlayerDataComponent>();
   411→		int32 Score = PlayerData ? PlayerData->GetTotalScore() : 0;
   412→
   413→		if (Score > BestScore)
   414→		{
   415→			BestScore = Score;
   416→			BestPlayer = PS;
   417→		}
   418→	}
   419→
   420→	return BestPlayer;
   421→}
