   423→void UWjWorldGameRuleSumo::ResetRound()
   424→{
   425→	bIsResettingRound = false;
   426→
   427→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Resetting for round %d"), CurrentRound + 1);
   428→
   429→	UWorld* World = GetWorld();
   430→	if (!World) return;
   431→
   432→	// ?뚯썙???뺣━
   433→	CleanupPowerUps();
   434→
   435→	// 踰꾪봽 ?뺣━
   436→	RemoveAllPlayerBuffs();
   437→
   438→	// ?뚮옯??蹂듭썝
   439→	for (ASumoFloorRingActor* Ring : FloorRings)
   440→	{
   441→		if (Ring)
   442→		{
   443→			Ring->ResetRing();
   444→		}
   445→	}
   446→	CurrentShrinkLevel = 0;
   447→	TimeSinceLastShrink = 0.f;
   448→	bIsWarningActive = false;
   449→	WarningElapsed = 0.f;
   450→	TimeSinceLastPowerUp = 0.f;
   451→
   452→	// ?덈씫 ?쒖꽌 珥덇린??
   453→	EliminationOrder.Empty();
   454→
   455→	// 紐⑤뱺 ?뚮젅?댁뼱 由ъ뒪??
   456→	AlivePlayers.Empty();
   457→	AlivePlayerCount = 0;
   458→
   459→	AWjWorldGameModePlay* GM = GetGameModePlay();
   460→	if (!GM) return;
   461→
   462→	for (const auto& WeakPS : AllPlayers)
   463→	{
   464→		if (!WeakPS.IsValid()) continue;
   465→		AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   466→
   467→		// PlayerData 由ъ뀑
   468→		if (USumoPlayerDataComponent* PlayerData = PS->GetGameData<USumoPlayerDataComponent>())
   469→		{
   470→			PlayerData->ResetForNewRound();
   471→		}
   472→
   473→		AlivePlayers.Add(PS);
   474→		AlivePlayerCount++;
   475→
   476→		// 罹먮┃??由ъ뒪??
   477→		APlayerController* PC = Cast<APlayerController>(PS->GetOwner());
   478→		if (PC)
   479→		{
   480→			// 湲곗〈 Pawn ?뚭눼
   481→			// 기존 Pawn 제거 (이미 Destroy된 경우 무시)
   482→			if (APawn* OldPawn = PC->GetPawn())
   483→			{
   484→				if (::IsValid(OldPawn))
   485→				{
   486→					OldPawn->Destroy();
   487→				}
   488→			}
   489→
   490→			// UnPossess 후 RestartPlayer (Pawn 없이 리스폰 보장)
   491→			PC->UnPossess();
   492→			GM->RestartPlayer(PC);
   493→
   494→			// 리스폰 성공 확인
   495→			if (APawn* NewPawn = PC->GetPawn())
   496→			{
   497→				UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Player %s respawned successfully"), *PS->GetPlayerName());
   498→			}
   499→			else
   500→			{
   501→				UE_LOG(LogWjWorld, Warning, TEXT("GameRuleSumo: Player %s respawn FAILED"), *PS->GetPlayerName());
   502→			}
   503→		}
   504→	}
   505→
   506→	// ?쇱슫???쒖옉
   507→	OnRoundStart();
   508→}
