   639→void UWjWorldGameRuleSumo::TickShrinkPlatform(float DeltaTime)
   640→{
   641→	if (FloorRings.Num() == 0) return;
   642→
   643→	// Warning 以묒씠硫?寃쎄퀬 ?쒓컙 泥댄겕
   644→	if (bIsWarningActive)
   645→	{
   646→		WarningElapsed += DeltaTime;
   647→		if (WarningElapsed >= WarningDuration)
   648→		{
   649→			// Warning ?꾨즺 ??留??뚭눼
   650→			for (ASumoFloorRingActor* Ring : FloorRings)
   651→			{
   652→				if (Ring && Ring->GetRingState() == ESumoRingState::Warning)
   653→				{
   654→					Ring->DestroyRing();
   655→				}
   656→			}
   657→			bIsWarningActive = false;
   658→			WarningElapsed = 0.f;
   659→			CurrentShrinkLevel++;
   660→		}
   661→		return;
   662→	}
   663→
   664→	TimeSinceLastShrink += DeltaTime;
   665→	if (TimeSinceLastShrink >= ShrinkInterval)
   666→	{
   667→		TimeSinceLastShrink = 0.f;
   668→
   669→		// ?ㅼ쓬 ?뚭눼 ???留?李얘린
   670→		ASumoFloorRingActor* TargetRing = nullptr;
   671→		for (ASumoFloorRingActor* Ring : FloorRings)
   672→		{
   673→			if (Ring && Ring->GetRingState() == ESumoRingState::Active && Ring->RingOrder > 0)
   674→			{
   675→				TargetRing = Ring;
   676→				break; // ?대? ?대┝李⑥닚?대?濡?泥?Active媛 理쒖쇅怨?
   677→			}
   678→		}
   679→
   680→		if (TargetRing)
   681→		{
   682→			// 媛숈? RingOrder??紐⑤뱺 留곸뿉 Warning ?쒖옉
   683→			int32 TargetOrder = TargetRing->RingOrder;
   684→			for (ASumoFloorRingActor* Ring : FloorRings)
   685→			{
   686→				if (Ring && Ring->RingOrder == TargetOrder && Ring->GetRingState() == ESumoRingState::Active)
   687→				{
   688→					Ring->StartWarning();
   689→				}
   690→			}
   691→
   692→			bIsWarningActive = true;
   693→			WarningElapsed = 0.f;
   694→
   695→			UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Shrink warning - RingOrder %d"), TargetOrder);
   696→		}
   697→	}
   698→}
