   725→
   726→	FVector SpawnLoc = GetRandomSpawnLocationOnActiveRings();
   727→	SpawnLoc.Z += 100.f; // ?뚮옯???꾩뿉 ?꾩슦湲?
   728→
   729→	FActorSpawnParameters SpawnParams;
   730→	SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;
   731→
   732→	ASumoPowerUpActor* PowerUp = World->SpawnActor<ASumoPowerUpActor>(PowerUpActorClass, SpawnLoc, FRotator::ZeroRotator, SpawnParams);
   733→	if (PowerUp)
   734→	{
   735→		// ?쒕뜡 ????ㅼ젙
   736→		int32 RandType = FMath::RandRange(0, 2);
   737→		PowerUp->SetPowerUpType(static_cast<ESumoPowerUpType>(RandType));
   738→
   739→		ActivePowerUps.Add(PowerUp);
   740→
   741→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleSumo: Spawned PowerUp type %d at %s"), RandType, *SpawnLoc.ToString());
   742→	}
