   744→
   745→FVector UWjWorldGameRuleSumo::GetRandomSpawnLocationOnActiveRings() const
   746→{
   747→	// Active ?곹깭??留?以??섎굹瑜??쒕뜡 ?좏깮
   748→	TArray<ASumoFloorRingActor*> ActiveRings;
   749→	for (ASumoFloorRingActor* Ring : FloorRings)
   750→	{
   751→		if (Ring && Ring->GetRingState() == ESumoRingState::Active)
   752→		{
   753→			ActiveRings.Add(Ring);
   754→		}
   755→	}
   756→
   757→	if (ActiveRings.Num() > 0)
   758→	{
   759→		ASumoFloorRingActor* ChosenRing = ActiveRings[FMath::RandRange(0, ActiveRings.Num() - 1)];
   760→		FVector Center = ChosenRing->GetActorLocation();
   761→		float Radius = ChosenRing->RingRadius;
   762→
   763→		// 留????쒕뜡 ?꾩튂
   764→		float Angle = FMath::FRandRange(0.f, 2.f * PI);
   765→		float Dist = FMath::FRandRange(0.f, Radius);
   766→		return Center + FVector(FMath::Cos(Angle) * Dist, FMath::Sin(Angle) * Dist, 0.f);
   767→	}
   768→
   769→	return FVector::ZeroVector;
   770→}
