   784→void UWjWorldGameRuleSumo::RemoveAllPlayerBuffs()
   785→{
   786→	for (const auto& WeakPS : AllPlayers)
   787→	{
   788→		if (!WeakPS.IsValid()) continue;
   789→		AWjWorldPlayerStatePlay* PS = WeakPS.Get();
   790→
   791→		// PlayerState에서 ASC 가져오기 (ASC는 PlayerState에 있음)
   792→		UAbilitySystemComponent* ASC = PS->GetAbilitySystemComponent();
   793→		if (!ASC) continue;
   794→
   795→		// 紐⑤뱺 踰꾪봽 ?쒓렇 ?쒓굅
   796→		ASC->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_SpeedBoost());
   797→		ASC->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_SuperPush());
   798→		ASC->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_Shield());
   799→
   800→		// State_Eliminated 태그 제거 (다음 라운드 어빌리티 활성화를 위해)
   801→		ASC->RemoveLooseGameplayTag(WjWorldGameplayTag::State_Eliminated());
   802→
   803→		// 이동속도 복원 (기존 캐릭터가 존재하는 경우에만)
   804→		APawn* Pawn = PS->GetPawn();
   805→		AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(Pawn);
   806→		if (Character)
   807→		{
   808→			if (UCharacterMovementComponent* MC = Character->GetCharacterMovement())
   809→			{
   810→				// 기본값으로 복원 (CDO에서)
   811→				MC->MaxWalkSpeed = Character->GetClass()->GetDefaultObject<ACharacter>()->GetCharacterMovement()->MaxWalkSpeed;
   812→			}
   813→		}
   814→	}
   815→}
