   297→void UWjWorldGameRuleJumpMap::OnPlayerJoined(AWjWorldPlayerStatePlay* Player)
   298→{
   299→	Super::OnPlayerJoined(Player);
   300→
   301→	if (!HasAuthority() || !Player) return;
   302→
   303→	// 게임 진행 중 입장한 관전자는 참여자로 등록하지 않음
   304→	if (IsGameInProgress())
   305→	{
   306→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Spectator joined mid-game: %s"), *Player->GetPlayerName());
   307→		return;
   308→	}
   309→
   310→	AllPlayers.Add(Player);
   311→	TotalPlayerCount++;
   312→
   313→	UpdateGameData();
   314→
   315→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player Joined - %s, Total: %d"),
   316→		*Player->GetPlayerName(), TotalPlayerCount);
