   319→void UWjWorldGameRuleJumpMap::OnPlayerLeft(AWjWorldPlayerStatePlay* Player)
   320→{
   321→	Super::OnPlayerLeft(Player);
   322→
   323→	if (!HasAuthority() || !Player) return;
   324→
   325→	// 관전자(AllPlayers에 없는 플레이어)는 게임 카운터에 영향 없음
   326→	if (AllPlayers.Remove(Player) == 0)
   327→	{
   328→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Spectator left: %s"), *Player->GetPlayerName());
   329→		return;
   330→	}
   331→	TotalPlayerCount--;
   332→
   333→	UpdateGameData();
   334→
   335→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player Left - %s, Total: %d"),
   336→		*Player->GetPlayerName(), TotalPlayerCount);
   337→
   338→	// 모든 참여자 이탈
   339→	if (TotalPlayerCount <= 0)
   340→	{
   341→		bGameOverConditionMet = true;
   342→		WinnerPlayer = nullptr;
   343→		OnGameEnd();
   344→		return;
   345→	}
   346→
   347→	// 남은 플레이어가 모두 완주했는지 체크
   348→	int32 ActivePlayers = 0;
   349→	for (const auto& WeakPS : AllPlayers)
   350→	{
   351→		if (!WeakPS.IsValid()) continue;
   352→		UJumpMapPlayerDataComponent* PlayerData = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   353→		if (!PlayerData || !PlayerData->HasFinished())
   354→		{
   355→			ActivePlayers++;
   356→		}
   357→	}
   358→
   359→	if (ActivePlayers == 0 && FinishedPlayerCount > 0)
   360→	{
   361→		bGameOverConditionMet = true;
   362→		OnGameEnd();
   363→	}
   364→}
