   366→void UWjWorldGameRuleJumpMap::OnPlayerDied(AWjWorldCharacterPlay* Character)
   367→{
   368→	if (!HasAuthority() || !Character) return;
   369→
   370→	AWjWorldPlayerStatePlay* PS = Character->GetPlayerState<AWjWorldPlayerStatePlay>();
   371→	if (!PS) return;
   372→
   373→	// 이미 완주한 플레이어는 무시
   374→	UJumpMapPlayerDataComponent* PlayerData = PS->GetGameData<UJumpMapPlayerDataComponent>();
   375→	if (!PlayerData || PlayerData->HasFinished()) return;
