   389→void UWjWorldGameRuleJumpMap::RespawnPlayerAtCheckpoint(AWjWorldCharacterPlay* Character, int32 CheckpointIndex)
   390→{
   391→	if (!Character) return;
   392→
   393→	FVector RespawnLocation;
   394→	if (CheckpointIndex >= 0 && CheckpointIndex < CheckpointLocations.Num())
   395→	{
   396→		RespawnLocation = CheckpointLocations[CheckpointIndex];
   397→	}
   398→	else
   399→	{
   400→		RespawnLocation = StartLocation;
   401→	}
   402→
   403→	// 약간 위에 스폰 (바닥 충돌 방지)
   404→	RespawnLocation.Z += 100.f;
   405→
   406→	Character->SetActorLocation(RespawnLocation);
   407→
   408→	// 속도 초기화
   409→	if (UCharacterMovementComponent* MC = Character->GetCharacterMovement())
   410→	{
   411→		MC->StopMovementImmediately();
   412→	}
   413→
   414→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Respawned at checkpoint %d (%s)"),
   415→		CheckpointIndex, *RespawnLocation.ToString());
   416→}
