   418→void UWjWorldGameRuleJumpMap::OnPlayerFinished(AWjWorldCharacterPlay* Character)
   419→{
   420→	if (!HasAuthority() || !Character) return;
   421→
   422→	AWjWorldPlayerStatePlay* PS = Character->GetPlayerState<AWjWorldPlayerStatePlay>();
   423→	if (!PS) return;
   424→
   425→	UJumpMapPlayerDataComponent* PlayerData = PS->GetGameData<UJumpMapPlayerDataComponent>();
   426→	if (!PlayerData || PlayerData->HasFinished()) return;
   427→
   428→	// 완주 기록
   429→	PlayerData->SetFinished(ElapsedTime);
   430→	FinishedPlayerCount++;
   431→
   432→	// GameData에 완주 순서 추가
   433→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   434→	if (GameState)
   435→	{
   436→		UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   437→		if (GameData)
   438→		{
   439→			FJumpMapPlayerFinish FinishInfo;
   440→			FinishInfo.PlayerName = PS->GetPlayerName();
   441→			FinishInfo.FinishTime = ElapsedTime;
   442→			GameData->AddPlayerFinish(FinishInfo);
   443→			GameData->SetFinishedPlayerCount(FinishedPlayerCount);
   444→		}
   445→	}
   446→
   447→	UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Player finished: %s (Time: %.2f, Order: %d/%d)"),
   448→		*PS->GetPlayerName(), ElapsedTime, FinishedPlayerCount, TotalPlayerCount);
   449→
   450→	// 첫 번째 완주자가 승자
   451→	if (!WinnerPlayer.IsValid())
   452→	{
   453→		WinnerPlayer = PS;
   454→	}
   455→
   456→	// 모든 플레이어가 완주했는지 체크
   457→	int32 ActivePlayers = 0;
   458→	for (const auto& WeakPS : AllPlayers)
   459→	{
   460→		if (!WeakPS.IsValid()) continue;
   461→		UJumpMapPlayerDataComponent* PD = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   462→		if (!PD || !PD->HasFinished())
   463→		{
   464→			ActivePlayers++;
   465→		}
   466→	}
   467→
   468→	if (ActivePlayers == 0)
   469→	{
   470→		bGameOverConditionMet = true;
   471→		OnGameEnd();
   472→	}
   473→}
