   486→void UWjWorldGameRuleJumpMap::TickGameRule(float DeltaTime)
   487→{
   488→	if (!HasAuthority()) return;
   489→	if (!bIsGameStarted || bGameOverConditionMet) return;
   490→
   491→	// 경과 시간 업데이트
   492→	ElapsedTime += DeltaTime;
   493→
   494→	// GameData 업데이트
   495→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   496→	if (GameState)
   497→	{
   498→		UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   499→		if (GameData)
   500→		{
   501→			GameData->SetElapsedTime(ElapsedTime);
   502→		}
   503→	}
   504→
   505→	// 낙하 플레이어 체크
   506→	for (const auto& WeakPS : AllPlayers)
   507→	{
   508→		if (!WeakPS.IsValid()) continue;
   509→
   510→		APawn* Pawn = WeakPS->GetPawn();
   511→		AWjWorldCharacterPlay* Character = Cast<AWjWorldCharacterPlay>(Pawn);
   512→		if (!Character) continue;
   513→
   514→		UJumpMapPlayerDataComponent* PlayerData = WeakPS->GetGameData<UJumpMapPlayerDataComponent>();
   515→		if (PlayerData && PlayerData->HasFinished()) continue;
   516→
   517→		if (Character->GetActorLocation().Z < FallThresholdZ)
   518→		{
   519→			OnPlayerDied(Character);
   520→		}
   521→	}
   522→
   523→	// 시간 제한 체크
   524→	if (TimeLimit > 0.f && ElapsedTime >= TimeLimit)
   525→	{
   526→		UE_LOG(LogWjWorld, Log, TEXT("GameRuleJumpMap: Time limit reached (%.1f)"), TimeLimit);
   527→		bGameOverConditionMet = true;
   528→		OnGameEnd();
   529→	}
   530→}
