   532→void UWjWorldGameRuleJumpMap::UpdateGameData()
   533→{
   534→	AWjWorldGameStatePlay* GameState = GetGameStatePlay();
   535→	if (!GameState) return;
   536→
   537→	UJumpMapGameDataComponent* GameData = GameState->GetGameData<UJumpMapGameDataComponent>();
   538→	if (!GameData) return;
   539→
   540→	GameData->SetTotalPlayerCount(TotalPlayerCount);
   541→	GameData->SetFinishedPlayerCount(FinishedPlayerCount);
   542→}
