   192→void UWjWorldCosmeticComponent::OnAssetLoaded(ECosmeticSlot Slot, FName ItemId)
   193→{
   194→	if (!IsValid(this) || !GetOwner())
   195→	{
   196→		return;
   197→	}
   198→
   199→	// 로드 완료 시 해당 슬롯이 여전히 같은 아이템인지 확인
   200→	FName CurrentItem = AppliedLoadout.GetEquippedItem(Slot);
   201→	if (CurrentItem != ItemId)
   202→	{
   203→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("비동기 로드 완료되었으나 슬롯이 변경됨 (기대: %s, 현재: %s)"),
   204→			*ItemId.ToString(), *CurrentItem.ToString());
   205→		return;
   206→	}
   207→
   208→	if (!Catalog)
   209→	{
   210→		return;
   211→	}
   212→
   213→	const FCosmeticItemDefinition* Def = Catalog->FindByItemId(ItemId);
   214→	if (!Def)
   215→	{
   216→		return;
   217→	}
   218→
   219→	ACharacter* OwnerCharacter = Cast<ACharacter>(GetOwner());
   220→	if (!OwnerCharacter)
   221→	{
   222→		return;
   223→	}
   224→
   225→	// 소켓 이름 결정 (아이템 정의 우선, 없으면 슬롯 기본값)
   226→	FName SocketName = Def->AttachSocketName.IsNone() ? GetDefaultSocketName(Slot) : Def->AttachSocketName;
   227→
   228→	// SkeletalMesh 적용 (Head, Body 슬롯)
   229→	if (!Def->SkeletalMesh.IsNull() && Def->SkeletalMesh.IsValid())
   230→	{
   231→		USkeletalMesh* LoadedMesh = Def->SkeletalMesh.Get();
   232→		if (LoadedMesh)
   233→		{
   234→			// Body 슬롯: 캐릭터의 메인 메시 교체
   235→			if (Slot == ECosmeticSlot::Body)
   236→			{
   237→				USkeletalMeshComponent* MeshComp = OwnerCharacter->GetMesh();
   238→				if (MeshComp)
   239→				{
   240→					MeshComp->SetSkeletalMesh(LoadedMesh);
   241→
   242→					// AnimBlueprint 오버라이드 적용
   243→					if (!Def->AnimBlueprintOverride.IsNull())
   244→					{
   245→						UClass* AnimClass = Def->AnimBlueprintOverride.LoadSynchronous();
   246→						if (AnimClass)
   247→						{
   248→							MeshComp->SetAnimInstanceClass(AnimClass);
   249→						}
   250→					}
   251→
   252→					UE_LOG(LogWjWorldCosmetic, Log, TEXT("Body 메시 적용: %s"), *LoadedMesh->GetName());
   253→				}
   254→			}
   255→			else
   256→			{
   257→				// 다른 슬롯: 소켓에 부착
   258→				USkeletalMeshComponent* SlotMesh = NewObject<USkeletalMeshComponent>(OwnerCharacter);
   259→				SlotMesh->SetSkeletalMesh(LoadedMesh);
   260→				SlotMesh->AttachToComponent(
   261→					OwnerCharacter->GetMesh(),
   262→					FAttachmentTransformRules::SnapToTargetNotIncludingScale,
   263→					SocketName
   264→				);
   265→
   266→				// 오프셋 적용
   267→				SlotMesh->SetRelativeLocation(Def->AttachLocationOffset);
   268→				SlotMesh->SetRelativeRotation(Def->AttachRotationOffset);
   269→				SlotMesh->SetRelativeScale3D(Def->AttachScale);
   270→
   271→				SlotMesh->RegisterComponent();
   272→				SlotMeshComponents.Add(Slot, SlotMesh);
   273→
   274→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("슬롯 %d 메시 소켓 부착: %s → %s"),
   275→					static_cast<int32>(Slot), *LoadedMesh->GetName(), *SocketName.ToString());
   276→			}
   277→		}
   278→	}
   279→
   280→	// StaticMesh 적용 (Back, Effect 슬롯)
   281→	if (!Def->StaticMesh.IsNull() && Def->StaticMesh.IsValid())
   282→	{
   283→		UStaticMesh* LoadedStaticMesh = Def->StaticMesh.Get();
   284→		if (LoadedStaticMesh)
   285→		{
   286→			UStaticMeshComponent* SlotStaticMesh = NewObject<UStaticMeshComponent>(OwnerCharacter);
   287→			SlotStaticMesh->SetStaticMesh(LoadedStaticMesh);
   288→			SlotStaticMesh->AttachToComponent(
   289→				OwnerCharacter->GetMesh(),
   290→				FAttachmentTransformRules::SnapToTargetNotIncludingScale,
   291→				SocketName
   292→			);
   293→
   294→			// 오프셋 적용
   295→			SlotStaticMesh->SetRelativeLocation(Def->AttachLocationOffset);
   296→			SlotStaticMesh->SetRelativeRotation(Def->AttachRotationOffset);
   297→			SlotStaticMesh->SetRelativeScale3D(Def->AttachScale);
   298→
   299→			SlotStaticMesh->RegisterComponent();
   300→			SlotMeshComponents.Add(Slot, SlotStaticMesh);
   301→
   302→			UE_LOG(LogWjWorldCosmetic, Log, TEXT("슬롯 %d 스태틱 메시 소켓 부착: %s → %s"),
   303→				static_cast<int32>(Slot), *LoadedStaticMesh->GetName(), *SocketName.ToString());
   304→		}
   305→	}
   306→
   307→	// 로드 핸들 정리
   308→	ActiveStreamHandles.Remove(Slot);
   309→}
