   344→void UWjWorldCosmeticComponent::RestoreDefaultMesh(ECosmeticSlot Slot)
   345→{
   346→	if (Slot != ECosmeticSlot::Body)
   347→	{
   348→		return;
   349→	}
   350→
   351→	ACharacter* OwnerCharacter = Cast<ACharacter>(GetOwner());
   352→	if (!OwnerCharacter)
   353→	{
   354→		return;
   355→	}
   356→
   357→	if (const TSoftObjectPtr<USkeletalMesh>* DefaultMesh = DefaultMeshes.Find(Slot))
   358→	{
   359→		if (DefaultMesh->IsValid())
   360→		{
   361→			USkeletalMeshComponent* MeshComp = OwnerCharacter->GetMesh();
   362→			if (MeshComp)
   363→			{
   364→				MeshComp->SetSkeletalMesh(DefaultMesh->Get());
   365→
   366→				// AnimBlueprint도 기본값으로 복원
   367→				if (DefaultAnimClass)
   368→				{
   369→					MeshComp->SetAnimInstanceClass(DefaultAnimClass);
   370→				}
   371→
   372→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("기본 메시 복원: 슬롯 %d"), static_cast<int32>(Slot));
   373→			}
   374→		}
   375→	}
   376→}
