   378→void UWjWorldCosmeticComponent::OnLoadoutChangedHandler(ECosmeticSlot Slot, FName ItemId)
   379→{
   380→	// 로컬 플레이어 캐릭터만 처리 (멀티플레이어에서 다른 플레이어 캐릭터 제외)
   381→	APawn* OwnerPawn = Cast<APawn>(GetOwner());
   382→	if (!OwnerPawn)
   383→	{
   384→		return;
   385→	}
   386→
   387→	// 로컬 컨트롤 여부 확인
   388→	if (!OwnerPawn->IsLocallyControlled())
   389→	{
   390→		return;
   391→	}
   392→
   393→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticComponent: 로드아웃 변경 감지 - 슬롯 %d, 아이템 %s"),
   394→		static_cast<int32>(Slot), *ItemId.ToString());
   395→
   396→	if (ItemId.IsNone())
   397→	{
   398→		// 아이템 해제
   399→		ClearSlot(Slot);
   400→	}
   401→	else
   402→	{
   403→		// 아이템 장착
   404→		ApplySlot(Slot, ItemId);
   405→	}
   406→}
