   514→bool UWjWorldCosmeticSubsystem::GenerateTestItem(FName ItemId)
   515→{
   516→#if WITH_STEAM && !UE_BUILD_SHIPPING
   517→	if (ItemId.IsNone())
   518→	{
   519→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: 유효하지 않은 ItemId"));
   520→		return false;
   521→	}
   522→
   523→	ISteamInventory* SteamInv = SteamInventory();
   524→	if (!SteamInv)
   525→	{
   526→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: Steam Inventory API 사용 불가"));
   527→		return false;
   528→	}
   529→
   530→	if (!Catalog)
   531→	{
   532→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: 카탈로그 없음"));
   533→		return false;
   534→	}
   535→
   536→	int32 SteamDefId = Catalog->ItemIdToSteamItemDefId(ItemId);
   537→	if (SteamDefId == 0)
   538→	{
   539→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: SteamItemDefId를 찾을 수 없음 (%s)"), *ItemId.ToString());
   540→		return false;
   541→	}
   542→
   543→	SteamItemDef_t ItemDef = static_cast<SteamItemDef_t>(SteamDefId);
   544→	uint32 Quantity = 1;
   545→	SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   546→
   547→	if (SteamInv->GenerateItems(&ResultHandle, &ItemDef, &Quantity, 1))
   548→	{
   549→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("GenerateTestItem: 테스트 아이템 생성 요청 성공 (%s, DefId: %d)"), *ItemId.ToString(), SteamDefId);
   550→
   551→		// 결과 핸들 정리 (비동기이므로 즉시 파괴하면 안됨 - 실제 구현시 폴링 필요)
   552→		// 간단한 테스트를 위해 로컬 인벤토리에도 추가
   553→		GrantItemLocally(ItemId, 1);
   554→
   555→		SteamInv->DestroyResult(ResultHandle);
   556→		return true;
   557→	}
   558→	else
   559→	{
   560→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GenerateTestItem: Steam GenerateItems 실패"));
   561→		return false;
   562→	}
   563→#else
   564→	// 비 Steam 또는 Shipping 빌드: 로컬로 아이템 부여
   565→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("GenerateTestItem: 로컬 아이템 부여 (비Steam 환경) - %s"), *ItemId.ToString());
   566→	GrantItemLocally(ItemId, 1);
   567→	return true;
   568→#endif
   569→}
