   571→void UWjWorldCosmeticSubsystem::GrantAllItemsLocally()
   572→{
   573→#if !UE_BUILD_SHIPPING
   574→	if (!Catalog)
   575→	{
   576→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("GrantAllItemsLocally: 카탈로그 없음"));
   577→		return;
   578→	}
   579→
   580→	int32 GrantedCount = 0;
   581→	for (const FCosmeticItemDefinition& Def : Catalog->Items)
   582→	{
   583→		if (Def.IsValid() && !HasItem(Def.ItemId))
   584→		{
   585→			GrantItemLocally(Def.ItemId, 1);
   586→			GrantedCount++;
   587→		}
   588→	}
   589→
   590→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("GrantAllItemsLocally: %d개 아이템 부여 완료"), GrantedCount);
