    88→	static FName GetDefaultSocketName(ECosmeticSlot Slot);
    89→
    90→	/** 비동기 로드 핸들 */
    91→	FStreamableManager StreamableManager;
    92→	TMap<ECosmeticSlot, TSharedPtr<FStreamableHandle>> ActiveStreamHandles;
    93→
    94→	/** 렌더 타겟 크기 */
    95→	static constexpr int32 RenderTargetWidth = 500;
    96→	static constexpr int32 RenderTargetHeight = 1000;
    97→};
