    85→void ACharacterPreviewActor::SetupFromPawn(APawn* SourcePawn)
    86→{
    87→	if (!SourcePawn)
    88→	{
    89→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CharacterPreviewActor: SetupFromPawn called with null pawn"));
    90→		return;
    91→	}
    92→
    93→	// ACharacter에서 메시 컴포넌트 가져오기
    94→	ACharacter* SourceCharacter = Cast<ACharacter>(SourcePawn);
    95→	if (!SourceCharacter)
    96→	{
    97→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CharacterPreviewActor: SourcePawn is not a Character"));
    98→		return;
    99→	}
   100→
   101→	USkeletalMeshComponent* SourceMesh = SourceCharacter->GetMesh();
   102→	if (!SourceMesh)
   103→	{
   104→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CharacterPreviewActor: Source character has no mesh"));
   105→		return;
   106→	}
   107→
   108→	// SkeletalMesh 복사
   109→	USkeletalMesh* SkelMesh = SourceMesh->GetSkeletalMeshAsset();
   110→	if (SkelMesh)
   111→	{
   112→		PreviewMeshComponent->SetSkeletalMesh(SkelMesh);
   113→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Copied SkeletalMesh %s"), *SkelMesh->GetName());
   114→	}
   115→
   116→	// 소스 메시의 회전값 복사 (ACharacter의 Yaw=-90° 보정 포함)
   117→	PreviewMeshComponent->SetRelativeRotation(SourceMesh->GetRelativeRotation());
   118→
   119→	// AnimBlueprint 복사
   120→	UClass* AnimClass = SourceMesh->GetAnimClass();
   121→	if (AnimClass)
   122→	{
   123→		PreviewMeshComponent->SetAnimInstanceClass(AnimClass);
   124→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Copied AnimBlueprint %s"), *AnimClass->GetName());
   125→	}
   126→
   127→	// 애니메이션 재생을 위해 가시성 및 틱 활성화
   128→	PreviewMeshComponent->SetVisibility(true);
   129→	PreviewMeshComponent->VisibilityBasedAnimTickOption = EVisibilityBasedAnimTickOption::AlwaysTickPoseAndRefreshBones;
   130→
   131→	// 원본 메시/애니메이션 백업 (Body 프리뷰 교체 후 복원용)
   132→	OriginalMesh = SkelMesh;
   133→	OriginalAnimClass = AnimClass;
   134→
   135→	// 메시 설정 완료 후 실시간 캡처 활성화 (Idle 모션 반영)
   136→	SceneCaptureComponent->bCaptureEveryFrame = true;
   137→
   138→	RefreshCapture();
   139→}
