   146→void ACharacterPreviewActor::SetupPreview(const FCosmeticLoadout& Loadout)
   147→{
   148→	// 기존 코스메틱 메시 제거
   149→	for (auto& Pair : SlotMeshComponents)
   150→	{
   151→		if (Pair.Value)
   152→		{
   153→			Pair.Value->DestroyComponent();
   154→		}
   155→	}
   156→	SlotMeshComponents.Empty();
   157→	ActiveStreamHandles.Empty();
   158→
   159→	// Body 슬롯 프리뷰 메시/애님을 원본으로 복원
   160→	if (OriginalMesh.IsValid())
   161→	{
   162→		PreviewMeshComponent->SetSkeletalMesh(OriginalMesh.Get());
   163→	}
   164→	if (OriginalAnimClass)
   165→	{
   166→		PreviewMeshComponent->SetAnimInstanceClass(OriginalAnimClass);
   167→	}
   168→
   169→	// 카탈로그 가져오기
   170→	UGameInstance* GI = GetGameInstance();
   171→	if (!GI)
   172→	{
   173→		return;
   174→	}
   175→
   176→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   177→	if (!CosmeticSub)
   178→	{
   179→		return;
   180→	}
   181→
   182→	UWjWorldCosmeticCatalogDataAsset* Catalog = CosmeticSub->GetCatalog();
   183→	if (!Catalog)
   184→	{
   185→		RefreshCapture();
   186→		return;
   187→	}
   188→
   189→	// 코스메틱 로드아웃 적용
   190→	for (const FCosmeticSlotEntry& Entry : Loadout.Entries)
   191→	{
   192→		if (Entry.Slot == ECosmeticSlot::None || Entry.ItemId.IsNone())
   193→		{
   194→			continue;
   195→		}
   196→
   197→		const FCosmeticItemDefinition* ItemDef = Catalog->FindByItemId(Entry.ItemId);
   198→		if (!ItemDef)
   199→		{
   200→			continue;
   201→		}
   202→
   203→		// StaticMesh 또는 SkeletalMesh 비동기 로드
   204→		FSoftObjectPath MeshPath;
   205→		if (!ItemDef->StaticMesh.IsNull())
   206→		{
   207→			MeshPath = ItemDef->StaticMesh.ToSoftObjectPath();
   208→		}
   209→		else if (!ItemDef->SkeletalMesh.IsNull())
   210→		{
   211→			MeshPath = ItemDef->SkeletalMesh.ToSoftObjectPath();
   212→		}
   213→
   214→		if (!MeshPath.IsNull())
   215→		{
   216→			ECosmeticSlot CapturedSlot = Entry.Slot;
   217→			FName CapturedItemId = Entry.ItemId;
   218→
   219→			TSharedPtr<FStreamableHandle> Handle = StreamableManager.RequestAsyncLoad(
   220→				MeshPath,
   221→				FStreamableDelegate::CreateWeakLambda(this, [this, CapturedSlot, CapturedItemId]()
   222→				{
   223→					OnCosmeticAssetLoaded(CapturedSlot, CapturedItemId);
   224→				})
   225→			);
   226→
   227→			if (Handle.IsValid())
   228→			{
   229→				ActiveStreamHandles.Add(CapturedSlot, Handle);
   230→			}
   231→		}
   232→	}
   233→
   234→	// 코스메틱이 없으면 바로 캡처
   235→	if (Loadout.IsEmpty())
   236→	{
   237→		RefreshCapture();
   238→	}
   239→}
   240→
   241→void ACharacterPreviewActor::OnCosmeticAssetLoaded(ECosmeticSlot Slot, FName ItemId)
   242→{
   243→	UGameInstance* GI = GetGameInstance();
   244→	if (!GI)
   245→	{
   246→		return;
   247→	}
   248→
   249→	UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   250→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   251→	{
   252→		return;
   253→	}
   254→
   255→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(ItemId);
   256→	if (!ItemDef)
   257→	{
   258→		return;
   259→	}
   260→
   261→	// Body 슬롯: PreviewMeshComponent 메시 직접 교체
   262→	if (Slot == ECosmeticSlot::Body)
   263→	{
   264→		if (!ItemDef->SkeletalMesh.IsNull())
   265→		{
   266→			USkeletalMesh* SkelMesh = Cast<USkeletalMesh>(ItemDef->SkeletalMesh.ToSoftObjectPath().ResolveObject());
   267→			if (SkelMesh)
   268→			{
   269→				PreviewMeshComponent->SetSkeletalMesh(SkelMesh);
   270→
   271→				if (!ItemDef->AnimBlueprintOverride.IsNull())
   272→				{
   273→					UClass* AnimClass = ItemDef->AnimBlueprintOverride.LoadSynchronous();
   274→					if (AnimClass)
   275→					{
   276→						PreviewMeshComponent->SetAnimInstanceClass(AnimClass);
   277→					}
   278→				}
   279→
   280→				UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Body 프리뷰 메시 교체: %s"), *ItemId.ToString());
   281→			}
   282→		}
   283→
   284→		ActiveStreamHandles.Remove(Slot);
   285→		if (ActiveStreamHandles.Num() == 0)
   286→		{
   287→			RefreshCapture();
   288→		}
   289→		return;
   290→	}
   291→
   292→	// StaticMesh 우선, 없으면 SkeletalMesh 시도
   293→	UObject* LoadedAsset = nullptr;
   294→	if (!ItemDef->StaticMesh.IsNull())
   295→	{
   296→		LoadedAsset = ItemDef->StaticMesh.ToSoftObjectPath().ResolveObject();
   297→	}
   298→	else if (!ItemDef->SkeletalMesh.IsNull())
   299→	{
   300→		LoadedAsset = ItemDef->SkeletalMesh.ToSoftObjectPath().ResolveObject();
   301→	}
   302→
   303→	// 부착 소켓 결정
   304→	FName SocketName = ItemDef->AttachSocketName;
   305→	if (SocketName.IsNone())
   306→	{
   307→		SocketName = GetDefaultSocketName(ItemDef->Slot);
   308→	}
   309→
   310→	// 메시 컴포넌트 생성 및 부착
   311→	UMeshComponent* NewMeshComp = nullptr;
   312→
   313→	if (UStaticMesh* StaticMesh = Cast<UStaticMesh>(LoadedAsset))
   314→	{
   315→		UStaticMeshComponent* StaticMeshComp = NewObject<UStaticMeshComponent>(this);
   316→		StaticMeshComp->SetCollisionEnabled(ECollisionEnabled::NoCollision);
   317→		StaticMeshComp->SetStaticMesh(StaticMesh);
   318→		NewMeshComp = StaticMeshComp;
   319→	}
   320→	else if (USkeletalMesh* SkeletalMesh = Cast<USkeletalMesh>(LoadedAsset))
   321→	{
   322→		USkeletalMeshComponent* SkelMeshComp = NewObject<USkeletalMeshComponent>(this);
   323→		SkelMeshComp->SetCollisionEnabled(ECollisionEnabled::NoCollision);
   324→		SkelMeshComp->SetSkeletalMesh(SkeletalMesh);
   325→		NewMeshComp = SkelMeshComp;
   326→	}
   327→
   328→	if (NewMeshComp)
   329→	{
   330→		// Socket 부착 또는 단순 부착
   331→		if (!SocketName.IsNone() && PreviewMeshComponent->DoesSocketExist(SocketName))
   332→		{
   333→			NewMeshComp->AttachToComponent(PreviewMeshComponent,
   334→				FAttachmentTransformRules::SnapToTargetNotIncludingScale, SocketName);
   335→		}
   336→		else
   337→		{
   338→			NewMeshComp->SetupAttachment(PreviewMeshComponent);
   339→		}
   340→
   341→		// 오프셋 및 스케일 적용
   342→		NewMeshComp->SetRelativeLocation(ItemDef->AttachLocationOffset);
   343→		NewMeshComp->SetRelativeRotation(ItemDef->AttachRotationOffset);
   344→		NewMeshComp->SetRelativeScale3D(ItemDef->AttachScale);
   345→
   346→		NewMeshComp->RegisterComponent();
   347→
   348→		SlotMeshComponents.Add(Slot, NewMeshComp);
   349→		SceneCaptureComponent->ShowOnlyComponents.Add(NewMeshComp);
   350→
   351→		UE_LOG(LogWjWorldCosmetic, Log, TEXT("CharacterPreviewActor: Loaded cosmetic %s on slot %d (socket: %s)"),
   352→			*ItemId.ToString(), static_cast<int32>(Slot), *SocketName.ToString());
   353→	}
   354→
   355→	// 모든 로드가 완료되었는지 확인
   356→	ActiveStreamHandles.Remove(Slot);
   357→	if (ActiveStreamHandles.Num() == 0)
   358→	{
   359→		RefreshCapture();
   360→	}
   361→}
