   363→FName ACharacterPreviewActor::GetDefaultSocketName(ECosmeticSlot Slot)
   364→{
   365→	switch (Slot)
   366→	{
   367→	case ECosmeticSlot::Head:
   368→		return FName("head");
   369→	case ECosmeticSlot::Back:
   370→		return FName("spine_03");
   371→	case ECosmeticSlot::Effect:
   372→		return FName("root");
   373→	default:
   374→		return NAME_None;
   375→	}
   376→}
