   388→UMaterialInstanceDynamic* ACharacterPreviewActor::GetPreviewMaterial()
   389→{
   390→	if (PreviewMID)
   391→	{
   392→		return PreviewMID;
   393→	}
   394→
   395→	if (!PreviewMaterialBase)
   396→	{
   397→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   398→		if (Settings && !Settings->CharacterPreviewMaterial.IsNull())
   399→		{
   400→			PreviewMaterialBase = Settings->CharacterPreviewMaterial.LoadSynchronous();
   401→		}
   402→	}
   403→
   404→	if (!PreviewMaterialBase)
   405→	{
   406→		UE_LOG(LogWjWorldCosmetic, Warning, TEXT("CharacterPreviewActor: M_CharacterPreview not found"));
   407→		return nullptr;
   408→	}
   409→
   410→	PreviewMID = UMaterialInstanceDynamic::Create(PreviewMaterialBase, this);
   411→	if (PreviewMID && RenderTarget)
   412→	{
   413→		PreviewMID->SetTextureParameterValue(FName("PreviewTexture"), RenderTarget);
   414→	}
   415→
   416→	return PreviewMID;
   417→}
