    93→int32 UWjWorldCurrencySubsystem::GetRemainingDailyRewards() const
    94→{
    95→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    96→	if (!Settings || Settings->MaxDailyMatchRewards <= 0)
    97→	{
    98→		return MAX_int32; // 무제한
