   104→void UWjWorldCurrencySubsystem::TriggerMatchReward(bool bIsWinner)
   105→{
   106→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   107→	if (!Settings)
   108→	{
   109→		return;
   110→	}
   111→
   112→	// 일일 제한 체크
   113→	CheckDailyReset();
   114→	if (Settings->MaxDailyMatchRewards > 0 && TodayMatchRewardCount >= Settings->MaxDailyMatchRewards)
   115→	{
   116→		UE_LOG(LogWjWorldCurrency, Log, TEXT("일일 보상 한도 도달 (%d/%d) — 보상 지급 생략"),
   117→			TodayMatchRewardCount, Settings->MaxDailyMatchRewards);
   118→		return;
   119→	}
   120→
   121→	int32 GeneratorDefId = bIsWinner ? Settings->MatchWinRewardDefId : Settings->MatchLossRewardDefId;
   122→	int32 FallbackRewardAmount = bIsWinner ? 50 : 10;
   123→
   124→	UE_LOG(LogWjWorldCurrency, Log, TEXT("매치 보상 트리거: %s (GeneratorDefId: %d, DailyCount: %d/%d)"),
   125→		bIsWinner ? TEXT("승리") : TEXT("패배"), GeneratorDefId,
   126→		TodayMatchRewardCount, Settings->MaxDailyMatchRewards);
   127→
   128→#if WITH_STEAM
   129→	ISteamInventory* SteamInv = SteamInventory();
   130→	if (SteamInv)
   131→	{
   132→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   133→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   134→
   135→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   136→		{
   137→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam TriggerItemDrop 요청 성공 (DefId: %d)"), GeneratorDefId);
   138→			SteamInv->DestroyResult(ResultHandle);
   139→
   140→			// 2.5초 후 인벤토리 갱신 + 5초 후 재시도
   141→			ScheduleInventoryRefresh();
   142→		}
   143→		else
   144→		{
   145→			// TriggerItemDrop 실패 시 로컬 폴백
   146→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam TriggerItemDrop 실패 (DefId: %d) — 로컬 폴백 지급: %d Coin"),
   147→				GeneratorDefId, FallbackRewardAmount);
   148→			GrantCurrencyLocally(ECurrencyType::Coin, FallbackRewardAmount);
   149→		}
   150→
   151→		// 일일 카운트 증가
   152→		TodayMatchRewardCount++;
   153→		SaveDailyRewardData();
   154→		return;
   155→	}
   156→#endif
   157→
   158→	// 비Steam 폴백: 로컬 잔액 직접 증가
   159→	GrantCurrencyLocally(ECurrencyType::Coin, FallbackRewardAmount);
   160→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 매치 보상 지급: %d Coin"), FallbackRewardAmount);
   161→
   162→	// 일일 카운트 증가
   163→	TodayMatchRewardCount++;
   164→	SaveDailyRewardData();
   165→}
   166→
   167→bool UWjWorldCurrencySubsystem::PurchaseItemWithCurrency(FName CosmeticItemId, ECurrencyType CurrencyType)
   168→{
   169→	if (bExchangePending)
   170→	{
   171→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   172→		return false;
   173→	}
   174→
   175→	if (CosmeticItemId.IsNone())
   176→	{
   177→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 CosmeticItemId"));
   178→		return false;
   179→	}
   180→
   181→	// 카탈로그에서 아이템 정보 조회
   182→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   183→	if (!CosmeticSub || !CosmeticSub->GetCatalog())
   184→	{
   185→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("CosmeticSubsystem 또는 카탈로그 없음"));
   186→		return false;
   187→	}
   188→
   189→	const FCosmeticItemDefinition* ItemDef = CosmeticSub->GetCatalog()->FindByItemId(CosmeticItemId);
   190→	if (!ItemDef)
   191→	{
   192→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("카탈로그에서 아이템 '%s' 찾을 수 없음"), *CosmeticItemId.ToString());
   193→		return false;
   194→	}
   195→
   196→	// 가격 확인
   197→	int32 ItemPrice = (CurrencyType == ECurrencyType::Coin) ? ItemDef->CoinPrice : ItemDef->GemPrice;
   198→	if (ItemPrice <= 0)
   199→	{
   200→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("아이템 '%s'은 %s로 구매할 수 없습니다 (가격: %d)"),
   201→			*CosmeticItemId.ToString(),
   202→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   203→			ItemPrice);
   204→		return false;
   205→	}
   206→
   207→	// 잔액 확인
   208→	int32 CurrentBalance = GetBalance(CurrencyType);
   209→	if (CurrentBalance < ItemPrice)
   210→	{
   211→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("잔액 부족: %s %d < %d"),
   212→			(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   213→			CurrentBalance, ItemPrice);
   214→		return false;
   215→	}
   216→
   217→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   218→	if (!Settings)
   219→	{
   220→		return false;
   221→	}
   222→
   223→	int32 CurrencyDefId = (CurrencyType == ECurrencyType::Coin) ? Settings->CoinSteamItemDefId : Settings->GemSteamItemDefId;
   224→	int32 CosmeticDefId = ItemDef->SteamItemDefId;
   225→
   226→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 구매 요청: %s (%d %s → CosmeticDefId %d)"),
   227→		*CosmeticItemId.ToString(), ItemPrice,
   228→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"),
   229→		CosmeticDefId);
   230→
   231→#if WITH_STEAM
   232→	ISteamInventory* SteamInv = SteamInventory();
   233→	if (SteamInv && CosmeticDefId > 0)
   234→	{
   235→		// 캐시된 재화 인스턴스 ID 조회
   236→		SteamItemInstanceID_t CurrencyInstanceId = (CurrencyType == ECurrencyType::Coin)
   237→			? CachedCoinInstanceId
   238→			: CachedGemInstanceId;
   239→
   240→		if (CurrencyInstanceId == k_SteamItemInstanceIDInvalid)
   241→		{
   242→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("재화 인스턴스 ID가 캐싱되지 않음 — 인벤토리 갱신 필요"));
   243→			return false;
   244→		}
   245→
   246→		// 기존 핸들 정리
   247→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   248→		{
   249→			SteamInv->DestroyResult(ExchangeResultHandle);
   250→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   251→		}
   252→
   253→		// ExchangeItems: 재화 소비 → 코스메틱 아이템 획득
   254→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(CosmeticDefId);
   255→		uint32 OutputQuantity = 1;
   256→
   257→		uint32 InputQuantity = static_cast<uint32>(ItemPrice);
   258→
   259→		bool bExchangeResult = SteamInv->ExchangeItems(
   260→			&ExchangeResultHandle,
   261→			&OutputItemDef, &OutputQuantity, 1,       // 출력: 코스메틱 아이템 1개
   262→			&CurrencyInstanceId, &InputQuantity, 1     // 입력: 재화 인스턴스 × 가격
   263→		);
   264→
   265→		if (bExchangeResult)
   266→		{
   267→			bExchangePending = true;
   268→			bPendingIsPlacement = false;
   269→			PendingExchangeItemId = CosmeticItemId;
   270→			StartExchangePolling();
   271→
   272→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam ExchangeItems 요청 성공: %s (CurrencyInstanceId=%llu, Price=%d)"),
   273→				*CosmeticItemId.ToString(), CurrencyInstanceId, ItemPrice);
   274→			return true;
   275→		}
   276→		else
   277→		{
   278→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam ExchangeItems 호출 실패: %s"), *CosmeticItemId.ToString());
   279→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   280→			return false;
   281→		}
   282→	}
   283→#endif
   284→
   285→	// 비Steam 폴백: 로컬 잔액 차감 + 아이템 부여
   286→	SetBalance(CurrencyType, CurrentBalance - ItemPrice);
   287→	CosmeticSub->GrantItemLocally(CosmeticItemId, 1);
   288→
   289→	OnCurrencyPurchaseComplete.Broadcast(CosmeticItemId, true);
   290→
   291→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 재화 구매 완료: %s (%d %s 차감)"),
   292→		*CosmeticItemId.ToString(), ItemPrice,
   293→		(CurrencyType == ECurrencyType::Coin) ? TEXT("Coin") : TEXT("Gem"));
   294→
   295→	return true;
   296→}
