   474→void UWjWorldCurrencySubsystem::RefreshBalancesFromInventory()
   475→{
   476→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   477→	if (!Settings)
   478→	{
   479→		return;
   480→	}
   481→
   482→#if WITH_STEAM
   483→	ISteamInventory* SteamInv = SteamInventory();
   484→	if (SteamInv)
   485→	{
   486→		// CosmeticSubsystem의 캐시에서 잔액 및 인스턴스 ID 읽기
   487→		// (ParseInventoryResult()에서 이미 업데이트됨 — 중복 GetAllItems() 비동기 호출 제거)
   488→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   489→		if (CosmeticSub)
   490→		{
   491→			int32 NewCoinBalance = 0;
   492→			int32 NewGemBalance = 0;
   493→
   494→			const int32* CoinQty = CosmeticSub->AllItemQuantities.Find(Settings->CoinSteamItemDefId);
   495→			if (CoinQty)
   496→			{
   497→				NewCoinBalance = *CoinQty;
   498→			}
   499→
   500→			const int32* GemQty = CosmeticSub->AllItemQuantities.Find(Settings->GemSteamItemDefId);
   501→			if (GemQty)
   502→			{
   503→				NewGemBalance = *GemQty;
   504→			}
   505→
   506→			// 인스턴스 ID 캐시 갱신
   507→			const uint64* CoinInstId = CosmeticSub->AllItemInstanceIds.Find(Settings->CoinSteamItemDefId);
   508→			CachedCoinInstanceId = CoinInstId ? static_cast<SteamItemInstanceID_t>(*CoinInstId) : k_SteamItemInstanceIDInvalid;
   509→
   510→			const uint64* GemInstId = CosmeticSub->AllItemInstanceIds.Find(Settings->GemSteamItemDefId);
   511→			CachedGemInstanceId = GemInstId ? static_cast<SteamItemInstanceID_t>(*GemInstId) : k_SteamItemInstanceIDInvalid;
   512→
   513→			// 잔액 갱신
   514→			if (NewCoinBalance != CoinBalance)
   515→			{
   516→				SetBalance(ECurrencyType::Coin, NewCoinBalance);
   517→			}
   518→			if (NewGemBalance != GemBalance)
   519→			{
   520→				SetBalance(ECurrencyType::Gem, NewGemBalance);
   521→			}
   522→
   523→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam 잔액 갱신: Coin=%d (InstanceId=%llu), Gem=%d (InstanceId=%llu)"),
   524→				CoinBalance, CachedCoinInstanceId, GemBalance, CachedGemInstanceId);
   525→			return;
   526→		}
   527→	}
   528→#endif
   529→
   530→	// 비Steam: 로컬 값 유지
   531→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 잔액: Coin=%d, Gem=%d"), CoinBalance, GemBalance);
   532→}
