   616→void UWjWorldCurrencySubsystem::DebugConsumeAllSteamItems()
   617→{
   618→#if WITH_STEAM
   619→	ISteamInventory* SteamInv = SteamInventory();
   620→	if (!SteamInv)
   621→	{
   622→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam Inventory API 없음"));
   623→		return;
   624→	}
   625→
   626→	SteamInventoryResult_t AllItemsHandle = k_SteamInventoryResultInvalid;
   627→	if (!SteamInv->GetAllItems(&AllItemsHandle))
   628→	{
   629→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 실패"));
   630→		return;
   631→	}
   632→
   633→	EResult Status = SteamInv->GetResultStatus(AllItemsHandle);
   634→	if (Status != k_EResultOK)
   635→	{
   636→		SteamInv->DestroyResult(AllItemsHandle);
   637→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 상태 실패 (%d)"), static_cast<int32>(Status));
   638→		return;
   639→	}
   640→
   641→	uint32 ItemCount = 0;
   642→	if (!SteamInv->GetResultItems(AllItemsHandle, nullptr, &ItemCount) || ItemCount == 0)
   643→	{
   644→		SteamInv->DestroyResult(AllItemsHandle);
   645→		UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: 인벤토리가 이미 비어있음"));
   646→		return;
   647→	}
   648→
   649→	TArray<SteamItemDetails_t> Items;
   650→	Items.SetNum(ItemCount);
   651→	SteamInv->GetResultItems(AllItemsHandle, Items.GetData(), &ItemCount);
   652→	SteamInv->DestroyResult(AllItemsHandle);
   653→
   654→	int32 ConsumedCount = 0;
   655→	for (const SteamItemDetails_t& Detail : Items)
   656→	{
   657→		if (Detail.m_unQuantity == 0)
   658→		{
   659→			continue;
   660→		}
   661→
   662→		SteamInventoryResult_t ConsumeHandle = k_SteamInventoryResultInvalid;
   663→		if (SteamInv->ConsumeItem(&ConsumeHandle, Detail.m_itemId, Detail.m_unQuantity))
   664→		{
   665→			UE_LOG(LogWjWorldCurrency, Log, TEXT("  소비: DefId=%d, Quantity=%d, InstanceId=%llu"),
   666→				Detail.m_iDefinition, Detail.m_unQuantity, Detail.m_itemId);
   667→			SteamInv->DestroyResult(ConsumeHandle);
   668→			++ConsumedCount;
   669→		}
   670→	}
   671→
   672→	// 캐시 초기화
   673→	CachedCoinInstanceId = k_SteamItemInstanceIDInvalid;
   674→	CachedGemInstanceId = k_SteamItemInstanceIDInvalid;
   675→
   676→	// 인벤토리 갱신
   677→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   678→	if (CosmeticSub)
   679→	{
   680→		CosmeticSub->RequestInventoryRefresh();
   681→	}
   682→
   683→	UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: %d/%d 아이템 소비 완료"), ConsumedCount, ItemCount);
   684→#else
   685→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam 환경에서만 사용 가능"));
   686→#endif
   687→}
