   278→bool AWjWorldTreasureChestActor::TryGrantReward()
   279→{
   280→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   281→	if (!Settings)
   282→	{
   283→		return false;
   284→	}
   285→
   286→#if WITH_STEAM
   287→	ISteamInventory* SteamInv = SteamInventory();
   288→	if (SteamInv)
   289→	{
   290→		SteamInventoryResult_t ResultHandle = k_SteamInventoryResultInvalid;
   291→		int32 GeneratorDefId = Settings->TreasureChestGeneratorStartDefId + ChestIndex;
   292→		SteamItemDef_t DropDef = static_cast<SteamItemDef_t>(GeneratorDefId);
   293→
   294→		if (SteamInv->TriggerItemDrop(&ResultHandle, DropDef))
   295→		{
   296→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 요청 성공 (DefId: %d)"),
   297→				ChestIndex, GeneratorDefId);
   298→			SteamInv->DestroyResult(ResultHandle);
   299→
   300→			// 2.5초 후 인벤토리 갱신 + 5초 후 재시도
   301→			TWeakObjectPtr<AWjWorldTreasureChestActor> WeakThis(this);
   302→
   303→			FTimerHandle FirstTimerHandle;
   304→			GetWorldTimerManager().SetTimer(FirstTimerHandle, [WeakThis]()
   305→			{
   306→				if (AWjWorldTreasureChestActor* Self = WeakThis.Get())
   307→				{
   308→					UGameInstance* GI = Self->GetGameInstance();
   309→					if (GI)
   310→					{
   311→						UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   312→						if (CosmeticSub)
   313→						{
   314→							CosmeticSub->RequestInventoryRefresh();
   315→							UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest: 인벤토리 갱신 (2.5초 후)"));
   316→						}
   317→					}
   318→				}
   319→			}, 2.5f, false);
   320→
   321→			FTimerHandle RetryTimerHandle;
   322→			GetWorldTimerManager().SetTimer(RetryTimerHandle, [WeakThis]()
   323→			{
   324→				if (AWjWorldTreasureChestActor* Self = WeakThis.Get())
   325→				{
   326→					UGameInstance* GI = Self->GetGameInstance();
   327→					if (GI)
   328→					{
   329→						UWjWorldCosmeticSubsystem* CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   330→						if (CosmeticSub)
   331→						{
   332→							CosmeticSub->RequestInventoryRefresh();
   333→							UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest: 인벤토리 갱신 재시도 (5초 후)"));
   334→						}
   335→					}
   336→				}
   337→			}, 5.0f, false);
   338→
   339→			return true;
   340→		}
   341→		else
   342→		{
   343→			// TriggerItemDrop 실패 시 로컬 폴백
   344→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("TreasureChest[%d]: Steam TriggerItemDrop 실패 (DefId: %d) — 로컬 폴백"),
   345→				ChestIndex, GeneratorDefId);
   346→
   347→			int32 FallbackReward = Settings->TreasureChestCoinReward;
   348→			UGameInstance* GI = GetGameInstance();
   349→			if (GI)
   350→			{
   351→				UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   352→				if (CurrencySub)
   353→				{
   354→					CurrencySub->GrantCurrencyLocally(ECurrencyType::Coin, FallbackReward);
   355→					UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest: 로컬 폴백 보상 %d Coin 지급"), FallbackReward);
   356→				}
   357→			}
   358→			return true; // 폴백 지급 성공으로 처리
   359→		}
   360→	}
   361→#endif
   362→
   363→	// 비Steam 폴백: 로컬 재화 부여
   364→	int32 RewardAmount = Settings->TreasureChestCoinReward;
   365→	UGameInstance* GI = GetGameInstance();
   366→	if (GI)
   367→	{
   368→		UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   369→		if (CurrencySub)
   370→		{
   371→			CurrencySub->GrantCurrencyLocally(ECurrencyType::Coin, RewardAmount);
   372→			UE_LOG(LogWjWorldCurrency, Log, TEXT("TreasureChest: 로컬 보상 %d Coin 지급"), RewardAmount);
   373→		}
   374→	}
   375→
   376→	return true;
   377→}
