   444→bool AWjWorldTreasureChestActor::IsOnCooldown() const
   445→{
   446→	if (CachedLastOpenedTime.GetTicks() == 0)
   447→	{
   448→		return false;
   449→	}
   450→
   451→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   452→	float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   453→	return (FDateTime::UtcNow() - CachedLastOpenedTime).GetTotalSeconds() < CooldownSeconds;
   454→}
   455→
   456→FTimespan AWjWorldTreasureChestActor::GetRemainingCooldown() const
   457→{
   458→	if (CachedLastOpenedTime.GetTicks() == 0)
   459→	{
   460→		return FTimespan::Zero();
   461→	}
   462→
   463→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   464→	float CooldownSeconds = Settings ? Settings->TreasureChestCooldownSeconds : 86400.0f;
   465→
   466→	FDateTime CooldownEnd = CachedLastOpenedTime + FTimespan::FromSeconds(CooldownSeconds);
   467→	FTimespan Remaining = CooldownEnd - FDateTime::UtcNow();
   468→
   469→	if (Remaining.GetTotalSeconds() > 0)
   470→	{
   471→		return Remaining;
   472→	}
   473→	return FTimespan::Zero();
   474→}
