   106→void AWjWorldGameStatePlay::OnRep_GamePhase()
   107→{
   108→	switch (CurrentPhase)
   109→	{
   110→	case EGamePhase::Ready:
   111→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Ready"));
   112→		break;
   113→	case EGamePhase::Playing:
   114→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Started"));
   115→		break;
   116→	case EGamePhase::Finished:
   117→		// 결과 표시는 OnRep_GameResult에서 처리
   118→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Match Finished"));
   119→		// 게임 종료 후 ServerTravel 중 호스트 퇴장 시 마이그레이션 스킵용
   120→		if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   121→		{
   122→			GI->MarkGameEndTraveling();
   123→		}
   124→		break;
   125→	}
   126→
   127→	UE_LOG(LogWjWorld, Log, TEXT("GameState: Phase changed to %d"), static_cast<int32>(CurrentPhase));
   128→}
