   130→void AWjWorldGameStatePlay::OnRep_IsGameStartCountDownReady()
   131→{
   132→	if (bIsGameStartCountDownReady)
   133→	{
   134→		UWorld* World = GetWorld();
   135→		if (!World) return;
   136→
   137→		APlayerController* PC = World->GetFirstPlayerController();
   138→		if (!PC) return;
   139→
   140→		AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   141→		if (!HUD) return;
   142→
   143→		// 늦게 참여한 클라이언트를 위해 남은 시간 계산
   144→		float RemainingTime = StartCountDownTime;
   145→		if (CountdownStartServerTime > 0.0)
   146→		{
   147→			double CurrentServerTime = GetServerWorldTimeSeconds();
   148→			double Elapsed = CurrentServerTime - CountdownStartServerTime;
   149→			RemainingTime = FMath::Max(0.0f, StartCountDownTime - static_cast<float>(Elapsed));
   150→		}
   151→
   152→		HUD->StartGameStartCountDown(RemainingTime);
   153→
   154→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Game Start Countdown Ready - %f seconds (original: %f)"), RemainingTime, StartCountDownTime);
   155→	}
   156→}
   157→
   158→void AWjWorldGameStatePlay::OnRep_IsGameEndCountDownReady()
   159→{
   160→	if (bIsGameEndCountDownReady)
   161→	{
   162→		UWorld* World = GetWorld();
   163→		if (!World) return;
   164→
   165→		APlayerController* PC = World->GetFirstPlayerController();
   166→		if (!PC) return;
   167→
   168→		AWjWorldHUDPlay* HUD = PC->GetHUD<AWjWorldHUDPlay>();
   169→		if (!HUD) return;
   170→
   171→		HUD->StartGameStartCountDown(EndCountDownTime);
   172→
   173→		UE_LOG(LogWjWorld, Log, TEXT("GameState: Game End Countdown Ready - %f seconds"), EndCountDownTime);
   174→	}
   175→}
