    27→	}
    28→
    29→	// 저장된 마스터 볼륨 복원
    30→	USettingsWidget::ApplySavedMasterVolume();
    31→
    32→	// NetworkFailure 핸들러 등록
    33→	if (GEngine)
    34→	{
    35→		NetworkFailureHandle = GEngine->OnNetworkFailure().AddUObject(
    36→			this, &UWjWorldGameInstance::HandleNetworkFailure);
    37→		TravelFailureHandle = GEngine->OnTravelFailure().AddUObject(
    38→			this, &UWjWorldGameInstance::HandleTravelFailure);
