    43→void UWjWorldGameInstance::Shutdown()
    44→{
    45→	// 타이머 정리
    46→	UWorld* World = GetWorld();
    47→	if (World)
    48→	{
    49→		World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
    50→		World->GetTimerManager().ClearTimer(MigrationRetryHandle);
    51→	}
    52→
    53→	// NetworkFailure / TravelFailure 핸들러 해제
    54→	if (GEngine)
    55→	{
    56→		GEngine->OnNetworkFailure().Remove(NetworkFailureHandle);
    57→		GEngine->OnTravelFailure().Remove(TravelFailureHandle);
    58→	}
    59→
    60→	// SessionManager 정리
    61→	if (SessionManager)
    62→	{
    63→		SessionManager->Shutdown();
    64→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: SessionManager shutdown"));
