   176→void UWjWorldGameInstance::HandleNetworkFailure(UWorld* World, UNetDriver* NetDriver,
   177→	ENetworkFailure::Type FailureType, const FString& ErrorString)
   178→{
   179→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: HandleNetworkFailure called - Type: %d, Error: %s"),
   180→		static_cast<int32>(FailureType), *ErrorString);
   181→
   182→	// 이미 마이그레이션 중이면 무시
   183→	if (MigrationContext.bIsMigrating)
   184→	{
   185→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure ignored - already migrating"));
   186→		return;
   187→	}
   188→
   189→	// 자신이 호스트(서버)면 마이그레이션 불필요
   190→	if (World && World->GetAuthGameMode() != nullptr)
   191→	{
   192→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure on server - ignoring (Type: %d, Error: %s)"),
   193→			static_cast<int32>(FailureType), *ErrorString);
   194→		return;
   195→	}
   196→
   197→	// 게임 종료 후 WaitingRoom 복귀 중 호스트 퇴장 → 마이그레이션 없이 로비 복귀
   198→	if (bGameEndTraveling)
   199→	{
   200→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure during game-end travel - skipping migration, returning to lobby"));
   201→		bGameEndTraveling = false;
   202→		MigrationFailed();
   203→		return;
   204→	}
   205→
   206→	// 연결 관련 Failure 타입은 모두 마이그레이션 시도
   207→	// (Steam P2P에서는 다양한 에러 타입이 발생할 수 있음)
   208→	switch (FailureType)
   209→	{
   210→	case ENetworkFailure::ConnectionLost:
   211→	case ENetworkFailure::FailureReceived:
   212→	case ENetworkFailure::ConnectionTimeout:
   213→	case ENetworkFailure::PendingConnectionFailure:
   214→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: NetworkFailure detected - Type: %d, Error: %s. Beginning host migration."),
   215→			static_cast<int32>(FailureType), *ErrorString);
   216→		BeginHostMigration();
   217→		break;
   218→	default:
   219→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: NetworkFailure type %d not handled for migration"),
   220→			static_cast<int32>(FailureType));
   221→		break;
   222→	}
   223→}
