   273→// ============================================================================
   274→
   275→void UWjWorldGameInstance::BeginHostMigration()
   276→{
   277→	MigrationContext.bIsMigrating = true;
   278→	MigrationContext.MigrationStartTime = FPlatformTime::Seconds();
   279→	MigrationContext.RetryCount = 0;
   280→	SetMigrationState(EHostMigrationState::Detected);
   281→
   282→	// 클라이언트: CachedPlayerList가 비어있으면 PlayerArray에서 직접 빌드
   283→	if (MigrationContext.CachedPlayerList.Num() == 0)
   284→	{
   285→		UWorld* World = GetWorld();
   286→		if (World)
   287→		{
   288→			if (AGameStateBase* GS = World->GetGameState())
   289→			{
   290→				for (APlayerState* PS : GS->PlayerArray)
   291→				{
   292→					if (PS)
   293→					{
   294→						FPlayerDisplayInfo Info;
   295→						Info.PlayerName = PS->GetPlayerName();
   296→						Info.PlayerID = PS->GetPlayerId();
   297→						MigrationContext.CachedPlayerList.Add(Info);
   298→					}
   299→				}
   300→			}
   301→
   302→			APlayerController* PC = UGameplayStatics::GetPlayerController(World, 0);
   303→			if (PC && PC->PlayerState)
   304→			{
   305→				MigrationContext.LocalPlayerID = PC->PlayerState->GetPlayerId();
   306→			}
   307→
   308→			UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Built player cache from PlayerArray - %d players (LocalID: %d)"),
   309→				MigrationContext.CachedPlayerList.Num(), MigrationContext.LocalPlayerID);
   310→		}
   311→	}
   312→
   313→	// SessionManager의 LastRoomSettings 동기화 (클라이언트에서 올바른 NetworkMode 사용)
   314→	if (SessionManager)
   315→	{
   316→		SessionManager->UpdateLastRoomSettings(MigrationContext.CachedRoomSettings);
   317→	}
   318→
   319→	// 마이그레이션 태그 생성 (모든 클라이언트 동일)
   320→	MigrationContext.MigrationSessionTag = GenerateMigrationTag();
   321→
   322→	UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Host migration started - Tag: '%s', NetworkMode: %s"),
   323→		*MigrationContext.MigrationSessionTag,
   324→		MigrationContext.CachedRoomSettings.NetworkMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
   325→
   326→	// 기존 세션 파괴
   327→	if (SessionManager)
   328→	{
   329→		SessionManager->DestroySession();
   330→	}
   331→
   332→	// 타임아웃 타이머 설정
   333→	UWorld* World = GetWorld();
   334→	if (World)
   335→	{
   336→		World->GetTimerManager().SetTimer(MigrationTimeoutHandle,
   337→			FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::OnMigrationTimeout),
   338→			FHostMigrationContext::MigrationTimeout, false);
   339→	}
   340→
   341→	// 새 호스트 결정
   342→	MigrationContext.bIsNewHost = DetermineIfNewHost();
   343→
   344→	if (MigrationContext.bIsNewHost)
   345→	{
   346→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: This client is the new host"));
   347→		MigrationCreateSession();
   348→	}
   349→	else
   350→	{
   351→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: This client is NOT the new host - waiting 3s before searching"));
   352→
   353→		// 3초 대기 후 검색 시작
   354→		if (World)
   355→		{
   356→			World->GetTimerManager().SetTimer(MigrationRetryHandle,
   357→				FTimerDelegate::CreateUObject(this, &UWjWorldGameInstance::MigrationSearchForNewHost),
   358→				3.0f, false);
   359→		}
   360→	}
   361→}
   362→
   363→bool UWjWorldGameInstance::DetermineIfNewHost() const
   364→{
   365→	const TArray<FPlayerDisplayInfo>& CachedPlayers = MigrationContext.CachedPlayerList;
   366→
   367→	if (CachedPlayers.Num() == 0)
   368→	{
   369→		// 캐시가 비어있으면 자신이 호스트
   370→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: No cached players - assuming new host"));
   371→		return true;
   372→	}
   373→
   374→	// PlayerID 오름차순 정렬 (이전 호스트 제외)
   375→	TArray<FPlayerDisplayInfo> Candidates;
   376→	for (const FPlayerDisplayInfo& Info : CachedPlayers)
   377→	{
   378→		if (!Info.bIsHost) // 이전 호스트 제외
   379→		{
   380→			Candidates.Add(Info);
   381→		}
   382→	}
   383→
   384→	if (Candidates.Num() == 0)
   385→	{
   386→		// 모든 플레이어가 호스트? 자신이 새 호스트
   387→		return true;
   388→	}
   389→
   390→	// PlayerID 오름차순 정렬
   391→	Candidates.Sort([](const FPlayerDisplayInfo& A, const FPlayerDisplayInfo& B)
   392→	{
   393→		return A.PlayerID < B.PlayerID;
   394→	});
   395→
   396→	// 첫 번째 = 새 호스트
   397→	return (Candidates[0].PlayerID == MigrationContext.LocalPlayerID);
   398→}
