   400→FString UWjWorldGameInstance::GenerateMigrationTag() const
   401→{
   402→	// 결정론적 태그: "MIG_{RoomName}_{OriginalHostPlayerID}"
   403→	FString RoomName = MigrationContext.CachedRoomSettings.RoomName;
   404→	int32 OriginalHostID = -1;
   405→
   406→	for (const FPlayerDisplayInfo& Info : MigrationContext.CachedPlayerList)
   407→	{
   408→		if (Info.bIsHost)
   409→		{
   410→			OriginalHostID = Info.PlayerID;
   411→			break;
   412→		}
   413→	}
   414→
   415→	return FString::Printf(TEXT("MIG_%s_%d"), *RoomName, OriginalHostID);
   416→}
