   418→void UWjWorldGameInstance::MigrationCreateSession()
   419→{
   420→	SetMigrationState(EHostMigrationState::CreatingSession);
   421→
   422→	if (!SessionManager)
   423→	{
   424→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: MigrationCreateSession - SessionManager is null"));
   425→		MigrationFailed();
   426→		return;
   427→	}
   428→
   429→	// 콜백 바인딩
   430→	SessionManager->OnRoomCreatedEvent.AddDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   431→
   432→	bool bSuccess = SessionManager->CreateMigrationSession(
   433→		MigrationContext.CachedRoomSettings,
   434→		MigrationContext.MigrationSessionTag);
   435→
   436→	if (!bSuccess)
   437→	{
   438→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   439→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to create migration session"));
   440→		MigrationRetryOrFail();
   441→	}
   442→}
   443→
   444→void UWjWorldGameInstance::OnMigrationSessionCreated(bool bWasSuccessful)
   445→{
   446→	if (SessionManager)
   447→	{
   448→		SessionManager->OnRoomCreatedEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSessionCreated);
   449→	}
   450→
   451→	if (bWasSuccessful)
   452→	{
   453→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session created - ServerTraveling to WaitingRoom"));
   454→		SetMigrationState(EHostMigrationState::Complete);
   455→
   456→		UWorld* World = GetWorld();
   457→		if (World)
   458→		{
   459→			World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   460→			const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   461→			World->ServerTravel(Settings->GetWaitingRoomOpenLevelURL());
   462→		}
   463→	}
   464→	else
   465→	{
   466→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration session creation failed"));
   467→		MigrationRetryOrFail();
   468→	}
   469→}
