   471→void UWjWorldGameInstance::MigrationSearchForNewHost()
   472→{
   473→	SetMigrationState(EHostMigrationState::SearchingSession);
   474→
   475→	if (!SessionManager)
   476→	{
   477→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: MigrationSearchForNewHost - SessionManager is null"));
   478→		MigrationFailed();
   479→		return;
   480→	}
   481→
   482→	// 콜백 바인딩
   483→	SessionManager->OnRoomsFoundEvent.AddDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   484→
   485→	bool bSuccess = SessionManager->FindMigrationSession(MigrationContext.MigrationSessionTag);
   486→
   487→	if (!bSuccess)
   488→	{
   489→		SessionManager->OnRoomsFoundEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   490→		UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Failed to start migration session search"));
   491→		MigrationRetryOrFail();
   492→	}
   493→}
   494→
   495→void UWjWorldGameInstance::OnMigrationSearchResult(bool bWasSuccessful, const TArray<FRoomInfo>& Rooms)
   496→{
   497→	if (SessionManager)
   498→	{
   499→		SessionManager->OnRoomsFoundEvent.RemoveDynamic(this, &UWjWorldGameInstance::OnMigrationSearchResult);
   500→	}
   501→
   502→	if (bWasSuccessful)
   503→	{
   504→		// JoinSession은 FindMigrationSession 내부에서 자동으로 호출됨
   505→		UE_LOG(LogWjWorld, Log, TEXT("WjWorldGameInstance: Migration session found and joining"));
   506→		SetMigrationState(EHostMigrationState::JoiningSession);
   507→
   508→		UWorld* World = GetWorld();
   509→		if (World)
   510→		{
   511→			World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   512→		}
   513→		// JoinSession → ClientTravel이 자동으로 발생
   514→	}
   515→	else
   516→	{
   517→		UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration session not found - will retry"));
   518→		MigrationRetryOrFail();
   519→	}
   520→}
