   564→void UWjWorldGameInstance::OnMigrationTimeout()
   565→{
   566→	UE_LOG(LogWjWorld, Error, TEXT("WjWorldGameInstance: Migration timeout (%.0f seconds)"),
   567→		FHostMigrationContext::MigrationTimeout);
   568→	MigrationFailed();
