   571→void UWjWorldGameInstance::MigrationFailed()
   572→{
   573→	SetMigrationState(EHostMigrationState::Failed);
   574→
   575→	UWorld* World = GetWorld();
   576→	if (World)
   577→	{
   578→		World->GetTimerManager().ClearTimer(MigrationTimeoutHandle);
   579→		World->GetTimerManager().ClearTimer(MigrationRetryHandle);
   580→	}
   581→
   582→	UE_LOG(LogWjWorld, Warning, TEXT("WjWorldGameInstance: Migration failed - returning to lobby"));
   583→
   584→	// 세션 정리
   585→	if (SessionManager)
   586→	{
   587→		SessionManager->DestroySession();
   588→	}
   589→
   590→	// 마이그레이션 컨텍스트 리셋
   591→	MigrationContext.Reset();
   592→	bGameEndTraveling = false;
   593→	SetMigrationState(EHostMigrationState::None);
   594→
   595→	// 로비로 복귀
   596→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   597→	UGameplayStatics::OpenLevel(this, FName(*Settings->GetLobbyMapPath()));
   598→}
