   211→void AWjWorldGameModeLobby::ExitPlacementMode()
   212→{
   213→	APlayerController* PC = GetWorld()->GetFirstPlayerController();
   214→	AWjWorldPlayerControllerLobby* LobbyPC = Cast<AWjWorldPlayerControllerLobby>(PC);
   215→	if (!LobbyPC)
   216→	{
   217→		return;
   218→	}
   219→
   220→	UWjWorldPlacementComponent* PlacementComp = LobbyPC->GetPlacementComponent();
   221→	if (PlacementComp && PlacementComp->GetCurrentMode() != EPlacementMode::None)
   222→	{
   223→		PlacementComp->ExitPlacementMode();
   224→		// → OnPlacementModeChanged(None) 브로드캐스트
   225→		// → HandlePlacementModeChanged가 카메라 복귀 + HUD 처리
   226→	}
   227→}
   228→
   229→void AWjWorldGameModeLobby::HandlePlacementModeChanged(EPlacementMode NewMode)
   230→{
   231→	if (NewMode != EPlacementMode::None)
   232→	{
   233→		return;
   234→	}
   235→
   236→	AWjWorldPlayerControllerLobby* LobbyPC = Cast<AWjWorldPlayerControllerLobby>(
   237→		GetWorld()->GetFirstPlayerController());
   238→
   239→	// 카메라 Pawn 복귀
   240→	if (LobbyPC && LobbyPC->IsInPlacementCameraMode())
   241→	{
   242→		LobbyPC->RestoreOriginalPawn();
   243→	}
   244→
   245→	// HUD 복원
   246→	AWjWorldHUDLobby* LobbyHUD = LobbyPC ? Cast<AWjWorldHUDLobby>(LobbyPC->GetHUD()) : nullptr;
   247→	if (LobbyHUD)
   248→	{
   249→		LobbyHUD->HidePlacementHUD();
   250→	}
   251→
   252→	// 델리게이트 해제
   253→	UWjWorldPlacementComponent* PlacementComp = LobbyPC ? LobbyPC->GetPlacementComponent() : nullptr;
   254→	if (PlacementComp)
   255→	{
   256→		PlacementComp->OnPlacementModeChanged.RemoveDynamic(
   257→			this, &AWjWorldGameModeLobby::HandlePlacementModeChanged);
   258→	}
   259→
   260→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeLobby: Exited placement mode"));
   261→}
