    39→void AWjWorldGameStateLobby::AddPlacedObject(const FPlacedObjectSaveEntry& Entry)
    40→{
    41→	if (!HasAuthority())
    42→	{
    43→		return;
    44→	}
    45→
    46→	// 서버 측 배치 수량 검증
    47→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    48→	if (Settings && Settings->MaxTotalLobbyPlacedObjects > 0)
    49→	{
    50→		if (PlacedObjects.Num() >= Settings->MaxTotalLobbyPlacedObjects)
    51→		{
    52→			UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateLobby: 서버 거부 — 전체 배치 상한 도달 (%d/%d)"),
    53→				PlacedObjects.Num(), Settings->MaxTotalLobbyPlacedObjects);
    54→			return;
    55→		}
    56→	}
    57→
    58→	EnsureCatalogLoaded();
    59→	if (Catalog)
    60→	{
    61→		const FPlaceableObjectDefinition* Def = Catalog->FindByObjectId(Entry.ObjectId);
    62→		if (Def && Def->MaxPlacementCount > 0)
    63→		{
    64→			int32 TypeCount = CountObjectsByType(PlacedObjects, Entry.ObjectId);
    65→			if (TypeCount >= Def->MaxPlacementCount)
    66→			{
    67→				UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateLobby: 서버 거부 — 종류당 배치 상한 도달 (%s: %d/%d)"),
    68→					*Entry.ObjectId.ToString(), TypeCount, Def->MaxPlacementCount);
    69→				return;
    70→			}
    71→		}
    72→	}
    73→
    74→	PlacedObjects.Add(Entry);
    75→
    76→	// 서버에서도 즉시 오브젝트 스폰 (클라이언트는 OnRep에서 처리)
    77→	RespawnAllPlacedObjects();
    78→
    79→	OnPlacementDataChanged.Broadcast();
    80→
    81→	UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby: Added object %s (Total: %d)"),
    82→		*Entry.ObjectId.ToString(), PlacedObjects.Num());
    83→}
