   227→void AWjWorldGameStateLobby::EnsureCatalogLoaded()
   228→{
   229→	// 이미 Catalog가 설정되어 있으면 스킵
   230→	if (Catalog)
   231→	{
   232→		return;
   233→	}
   234→
   235→	// DeveloperSettings에서 Catalog 로드 (폴백 메커니즘)
   236→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   237→	if (!Settings || Settings->LobbyPlaceableCatalog.IsNull())
   238→	{
   239→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("GameStateLobby: No LobbyPlaceableCatalog configured in DeveloperSettings"));
   240→		return;
   241→	}
   242→
   243→	Catalog = Settings->LobbyPlaceableCatalog.LoadSynchronous();
   244→	if (Catalog)
   245→	{
   246→		UE_LOG(LogWjWorldPlacement, Log, TEXT("GameStateLobby: Catalog loaded from DeveloperSettings (fallback)"));
   247→	}
   248→	else
   249→	{
   250→		UE_LOG(LogWjWorldPlacement, Error, TEXT("GameStateLobby: Failed to load LobbyPlaceableCatalog"));
   251→	}
   252→}
