     8→void UCoinGainNotificationWidget::NativeConstruct()
     9→{
    10→	Super::NativeConstruct();
    11→
    12→	// 초기 잔액 캐시
    13→	UGameInstance* GI = GetGameInstance();
    14→	if (GI)
    15→	{
