    65→void AWjWorldPlayerControllerLobby::SwitchToPlacementCamera()
    66→{
    67→	if (PlacementCameraPawn)
    68→	{
    69→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlayerControllerLobby: Already in placement camera mode"));
    70→		return;
    71→	}
    72→
    73→	OriginalPawn = GetPawn();
    74→
    75→	// 캐릭터의 GamePlayCamera 비활성화 (Possess 전 해제해야 재 Possess 시 Activate()가 정상 동작)
    76→	if (AWjWorldCharacterBase* CharBase = Cast<AWjWorldCharacterBase>(GetPawn()))
    77→	{
    78→		if (UGameplayCameraComponent* GamePlayCamera = CharBase->GetGamePlayCamera())
    79→		{
    80→			GamePlayCamera->Deactivate();
    81→		}
    82→	}
    83→
    84→	// 현재 카메라 위치/회전을 스폰 기준으로 사용
    85→	FVector CameraSpawnLoc = FVector::ZeroVector;
    86→	FRotator CameraSpawnRot = FRotator::ZeroRotator;
    87→	if (PlayerCameraManager)
    88→	{
    89→		CameraSpawnLoc = PlayerCameraManager->GetCameraLocation();
    90→		CameraSpawnRot = PlayerCameraManager->GetCameraRotation();
    91→	}
    92→
    93→	FActorSpawnParameters SpawnParams;
    94→	SpawnParams.Owner = this;
    95→	SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
    96→
    97→	PlacementCameraPawn = GetWorld()->SpawnActor<AWjWorldPlacementCameraPawn>(
    98→		AWjWorldPlacementCameraPawn::StaticClass(), CameraSpawnLoc, CameraSpawnRot, SpawnParams);
    99→
   100→	if (!PlacementCameraPawn)
   101→	{
   102→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlayerControllerLobby: Failed to spawn PlacementCameraPawn"));
   103→		return;
   104→	}
   105→
   106→	Possess(PlacementCameraPawn);
   107→	SetControlRotation(CameraSpawnRot);
   108→
   109→	// 마우스 커서 유지
   110→	SetInputMode(FInputModeGameAndUI().SetHideCursorDuringCapture(false));
   111→
   112→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlayerControllerLobby: Switched to placement camera"));
   113→}
