   245→void AWjWorldGameModeWaitingRoom::LoadPlacementCatalog()
   246→{
   247→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   248→	if (!Settings || Settings->PlaceableObjectCatalog.IsNull())
   249→	{
   250→		UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeWaitingRoom: No PlaceableObjectCatalog configured"));
   251→		return;
   252→	}
   253→
   254→	CachedPlacementCatalog = Settings->PlaceableObjectCatalog.LoadSynchronous();
   255→	if (!CachedPlacementCatalog)
   256→	{
   257→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("WjWorldGameModeWaitingRoom: Failed to load PlaceableObjectCatalog"));
   258→		return;
   259→	}
   260→
   261→	// GameState에도 카탈로그 설정 (GameStateWaitingRoom은 GameStateLobby 상속)
   262→	AWjWorldGameStateWaitingRoom* WaitingRoomGameState = GetGameState<AWjWorldGameStateWaitingRoom>();
   263→	if (WaitingRoomGameState)
   264→	{
   265→		WaitingRoomGameState->SetCatalog(CachedPlacementCatalog);
   266→	}
   267→
   268→	UE_LOG(LogWjWorldPlacement, Log, TEXT("WjWorldGameModeWaitingRoom: Placement catalog loaded"));
   269→}
