    51→		return;
    52→	}
    53→
    54→	// 변경된 내용 로그
    55→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Updating room settings - GameMode: %s -> %s, Map: %s -> %s"),
    56→		*RoomSettings.GameMode, *NewSettings.GameMode,
