   180→void AWjWorldGameStateWaitingRoom::AddPlayerState(APlayerState* PlayerState)
   181→{
   182→	Super::AddPlayerState(PlayerState);
   183→
   184→	AWjWorldPlayerStateBase* WjPS = Cast<AWjWorldPlayerStateBase>(PlayerState);
   185→	if (WjPS)
   186→	{
   187→		FString PlayerName = WjPS->GetPlayerName();
   188→
   189→		// ⭐ PlayerName 업데이트 이벤트 구독
   190→		WjPS->OnPlayerNameUpdated.AddDynamic(this, &AWjWorldGameStateWaitingRoom::OnPlayerNameUpdated);
   191→
   192→		// ⭐ Ready 상태 변경 이벤트 구독
   193→		WjPS->OnReadyStateChanged.AddDynamic(this, &AWjWorldGameStateWaitingRoom::OnPlayerReadyStateChanged);
   194→
   195→		// ⭐ 이름이 비어있으면 아직 초기화 중 (나중에 OnPlayerNameUpdated 호출됨)
   196→		if (PlayerName.IsEmpty())
   197→		{
   198→			UE_LOG(LogWjWorld, Warning, TEXT("GameStateWaitingRoom: Player added with empty name (ID: %d) - Waiting for replication"), 
   199→				WjPS->GetPlayerId());
   200→			return;
   201→		}
   202→
   203→		// 첫 번째 플레이어를 호스트로 설정
   204→		if (HostPlayerID == -1)
   205→		{
   206→			HostPlayerID = WjPS->GetPlayerId();
   207→			UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Host set to PlayerID %d"), HostPlayerID);
   208→		}
   209→
   210→		UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Player added - %s (ID: %d, Total: %d)"),
   211→			*PlayerName, WjPS->GetPlayerId(), GetPlayerCount());
   212→	}
   213→
   214→	// 플레이어 목록 변경 브로드캐스트
   215→	BroadcastPlayerListChanged();
   216→}
   217→
   218→void AWjWorldGameStateWaitingRoom::RemovePlayerState(APlayerState* PlayerState)
   219→{
   220→	AWjWorldPlayerStateBase* WjPS = Cast<AWjWorldPlayerStateBase>(PlayerState);
   221→	if (WjPS)
   222→	{
   223→		// 이벤트 구독 해제
   224→		WjPS->OnPlayerNameUpdated.RemoveDynamic(this, &AWjWorldGameStateWaitingRoom::OnPlayerNameUpdated);
   225→		WjPS->OnReadyStateChanged.RemoveDynamic(this, &AWjWorldGameStateWaitingRoom::OnPlayerReadyStateChanged);
   226→
   227→		UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Player removed - %s (ID: %d, Remaining: %d)"),
   228→			*WjPS->GetPlayerName(), WjPS->GetPlayerId(), GetPlayerCount() - 1);
   229→
   230→		// 호스트가 나갔다면 새로운 호스트 지정
   231→		if (WjPS->GetPlayerId() == HostPlayerID && PlayerArray.Num() > 1)
   232→		{
   233→			// 나가는 플레이어를 제외한 첫 번째 유효한 플레이어를 새 호스트로
   234→			for (APlayerState* PS : PlayerArray)
   235→			{
   236→				AWjWorldPlayerStateBase* NextHost = Cast<AWjWorldPlayerStateBase>(PS);
   237→				if (NextHost && NextHost != WjPS && !NextHost->GetPlayerName().IsEmpty())
   238→				{
   239→					HostPlayerID = NextHost->GetPlayerId();
   240→					UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: New host set to PlayerID %d"), HostPlayerID);
   241→					break;
   242→				}
   243→			}
   244→		}
   245→	}
   246→
   247→	Super::RemovePlayerState(PlayerState);
   248→
   249→	// 플레이어 목록 변경 브로드캐스트
   250→	BroadcastPlayerListChanged();
   251→}
   252→
   253→void AWjWorldGameStateWaitingRoom::OnPlayerNameUpdated(const FString& PlayerName)
   254→{
   255→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: OnPlayerNameUpdated called - %s"), *PlayerName);
   256→
   257→	// 플레이어 목록 재브로드캐스트
   258→	BroadcastPlayerListChanged();
   259→}
   260→
   261→void AWjWorldGameStateWaitingRoom::OnPlayerReadyStateChanged(int32 PlayerID, bool bIsReady)
   262→{
   263→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: OnPlayerReadyStateChanged - PlayerID: %d, IsReady: %s"),
   264→		PlayerID, bIsReady ? TEXT("true") : TEXT("false"));
   265→
   266→	// 플레이어 목록 재브로드캐스트 (Ready 상태 포함)
   267→	BroadcastPlayerListChanged();
   268→}
   269→
   270→void AWjWorldGameStateWaitingRoom::BroadcastPlayerListChanged()
   271→{
   272→	TArray<FPlayerDisplayInfo> PlayerList = GetPlayerList();
   273→
   274→	UE_LOG(LogWjWorld, Log, TEXT("GameStateWaitingRoom: Broadcasting player list change - %d players"), PlayerList.Num());
   275→
   276→	// GameInstance에 플레이어 목록 캐시 (호스트 마이그레이션용)
   277→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   278→	{
   279→		GI->CachePlayerList(PlayerList);
   280→	}
   281→
   282→	// 이벤트 브로드캐스트
   283→	OnPlayerListChanged.Broadcast(PlayerList);
   284→}
