    31→void AWjWorldGameModePlay::InitGame(const FString& MapName, const FString& Options, FString& ErrorMessage)
    32→{
    33→	Super::InitGame(MapName, Options, ErrorMessage);
    34→
    35→	// URL Options에서 GameModeId, MapOption 파싱
    36→	GameModeId = UGameplayStatics::ParseOption(Options, TEXT("GameModeId"));
    37→	MapOption = UGameplayStatics::ParseOption(Options, TEXT("MapOption"));
    38→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: GameModeId='%s', MapOption='%s'"), *GameModeId, *MapOption);
    39→
    40→	// 카탈로그에서 GameRuleClass 조회
    41→	TSubclassOf<UWjWorldGameRuleBase> ResolvedGameRuleClass = nullptr;
    42→
    43→	const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
    44→	if (DevSettings && !DevSettings->MinigameCatalog.IsNull())
    45→	{
    46→		UWjWorldMinigameDataAsset* Catalog = DevSettings->MinigameCatalog.LoadSynchronous();
    47→		if (Catalog && !GameModeId.IsEmpty())
    48→		{
    49→			const FWjWorldMinigameDefinition* Def = Catalog->FindByGameModeId(FName(*GameModeId));
    50→			if (Def && Def->GameRuleClass)
    51→			{
    52→				ResolvedGameRuleClass = Def->GameRuleClass;
    53→				UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: GameRuleClass resolved from catalog - %s"),
    54→					*ResolvedGameRuleClass->GetName());
    55→			}
    56→		}
    57→	}
    58→
    59→	// 카탈로그에서 못 찾으면 폴백 (Deprecated)
    60→	if (!ResolvedGameRuleClass && GameRuleClass)
    61→	{
    62→		ResolvedGameRuleClass = GameRuleClass;
    63→		UE_LOG(LogWjWorld, Warning, TEXT("GameModePlay: Using fallback GameRuleClass (deprecated) - %s"),
    64→			*ResolvedGameRuleClass->GetName());
    65→	}
    66→
    67→	// GameRule 생성
    68→	if (ResolvedGameRuleClass)
    69→	{
    70→		CurrentGameRule = NewObject<UWjWorldGameRuleBase>(this, ResolvedGameRuleClass);
    71→		CurrentGameRule->Initialize(this);
    72→	}
    73→	else
    74→	{
    75→		UE_LOG(LogWjWorld, Error, TEXT("GameModePlay: No GameRuleClass found!"));
    76→	}
    77→
    78→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: InitGame completed"));
    79→}
