   104→void AWjWorldGameModePlay::PostLogin(APlayerController* NewPlayer)
   105→{
   106→	Super::PostLogin(NewPlayer);
   107→
   108→	if (CurrentGameRule)
   109→	{
   110→		AWjWorldPlayerStatePlay* NewPlayerState = Cast<AWjWorldPlayerStatePlay>(NewPlayer->PlayerState);
   111→		if (NewPlayerState)
   112→		{
   113→			CurrentGameRule->OnPlayerJoined(NewPlayerState);
   114→		}
   115→	}
   116→
   117→	// Play 중 플레이어 목록 캐시 (호스트 마이그레이션용)
   118→	if (UWjWorldGameInstance* GI = Cast<UWjWorldGameInstance>(GetGameInstance()))
   119→	{
   120→		AGameStateBase* GS = GetGameState<AGameStateBase>();
   121→		if (GS)
   122→		{
   123→			TArray<FPlayerDisplayInfo> PlayerList;
   124→			bool bFirstPlayer = true;
   125→			for (APlayerState* PS : GS->PlayerArray)
   126→			{
   127→				if (PS && !PS->GetPlayerName().IsEmpty())
   128→				{
   129→					FPlayerDisplayInfo Info;
   130→					Info.PlayerName = PS->GetPlayerName();
   131→					Info.PlayerID = PS->GetPlayerId();
   132→					Info.bIsHost = bFirstPlayer; // 서버의 첫 번째 플레이어 = 호스트
   133→					Info.bIsReady = true;
   134→					PlayerList.Add(Info);
   135→					bFirstPlayer = false;
   136→				}
   137→			}
   138→			GI->CachePlayerList(PlayerList);
   139→		}
   140→	}
   141→
   142→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: PostLogin completed for %s"), *NewPlayer->GetName());
   143→}
   144→
   145→void AWjWorldGameModePlay::HandleStartingNewPlayer_Implementation(APlayerController* NewPlayer)
   146→{
   147→	// 게임 진행 중 또는 종료 후 입장한 플레이어는 관전자로 처리
   148→	AWjWorldGameStatePlay* PlayGameState = GetGameState<AWjWorldGameStatePlay>();
   149→	if (PlayGameState)
   150→	{
   151→		EGamePhase Phase = PlayGameState->GetGamePhase();
   152→		if (Phase == EGamePhase::Playing || Phase == EGamePhase::Finished)
   153→		{
   154→			NewPlayer->StartSpectatingOnly();
   155→			UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Mid-game join - %s set to spectator (Phase: %d)"),
   156→				*NewPlayer->GetName(), static_cast<int32>(Phase));
   157→			return;
   158→		}
   159→	}
   160→
   161→	Super::HandleStartingNewPlayer_Implementation(NewPlayer);
   162→}
   163→
   164→void AWjWorldGameModePlay::Logout(AController* Exiting)
   165→{
   166→	// GameRule에 플레이어 이탈 알림 (Super::Logout 전에 호출해야 PlayerState가 유효함)
   167→	if (CurrentGameRule && Exiting)
   168→	{
   169→		AWjWorldPlayerStatePlay* ExitingPlayerState = Cast<AWjWorldPlayerStatePlay>(Exiting->PlayerState);
   170→		if (ExitingPlayerState)
   171→		{
   172→			UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Logout - Notifying GameRule for player %s"), *ExitingPlayerState->GetPlayerName());
   173→			CurrentGameRule->OnPlayerLeft(ExitingPlayerState);
   174→		}
   175→	}
   176→
   177→	Super::Logout(Exiting);
   178→
   179→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Logout completed for %s"), Exiting ? *Exiting->GetName() : TEXT("Unknown"));
   180→}
   181→
   182→void AWjWorldGameModePlay::StartGame(float SecondsForStartCount)
   183→{
   184→	GetGameState<AWjWorldGameStatePlay>()->GameStartWithCountdown(SecondsForStartCount);
   185→	GetGameState<AWjWorldGameStatePlay>()->SetGameRuleClass(CurrentGameRule->GetClass());
   186→
   187→	if(GetWorld() && CurrentGameRule)
   188→	{
   189→		GetWorld()->GetTimerManager().SetTimer(StartGameHandle, FTimerDelegate::CreateLambda([this, SecondsForStartCount]()
   190→		{
   191→			CurrentGameRule->OnGameStart();
   192→			OnGameStart.Broadcast();
   193→		}), SecondsForStartCount, false);
   194→	}
   195→
   196→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: StartGame scheduled in %f seconds"), SecondsForStartCount);
   197→}
   198→
   199→void AWjWorldGameModePlay::EndGamePredict(float SecondsForEndCount)
   200→{
   201→	GetGameState<AWjWorldGameStatePlay>()->GameEndWithCountdown(SecondsForEndCount);
   202→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: EndGame scheduled in %f seconds"), SecondsForEndCount);
   203→}
   204→
   205→void AWjWorldGameModePlay::OnGameLevelUp(int32 NewLevel)
   206→{
   207→	OnGameLevelChange.Broadcast(NewLevel);
   208→	UE_LOG(LogWjWorld, Log, TEXT("GameModePlay: Game Level Up to %d"), NewLevel);
   209→}
   210→
   211→void AWjWorldGameModePlay::BeginDestroy()
   212→{
   213→	Super::BeginDestroy();
   214→
   215→	UWorld* World = GetWorld();
   216→	if (World)
   217→	{
   218→		World->GetTimerManager().ClearTimer(StartGameHandle);
   219→	}
   220→}

