   293→FRoomSettings UCreateRoomWindow::BuildRoomSettings()
   294→{
   295→	FRoomSettings Settings;
   296→
   297→	// 방 이름
   298→	if (RoomNameTextBox)
   299→	{
   300→		Settings.RoomName = RoomNameTextBox->GetText().ToString();
   301→	}
   302→
   303→	// 게임 모드: DisplayName → GameModeId 변환
   304→	if (GameModeComboBox)
   305→	{
   306→		FString SelectedDisplay = GameModeComboBox->GetSelectedOption();
   307→		if (const FName* FoundId = GameModeDisplayToId.Find(SelectedDisplay))
   308→		{
   309→			Settings.GameMode = FoundId->ToString();
   310→		}
   311→		else
   312→		{
   313→			Settings.GameMode = SelectedDisplay;
   314→		}
   315→	}
   316→
   317→	// 맵: DisplayName → OptionValue 변환
   318→	if (MapComboBox)
   319→	{
   320→		FString SelectedDisplay = MapComboBox->GetSelectedOption();
   321→		if (const FString* FoundValue = MapOptionDisplayToValue.Find(SelectedDisplay))
   322→		{
   323→			Settings.MapName = *FoundValue;
   324→		}
   325→		else
   326→		{
   327→			Settings.MapName = SelectedDisplay;
   328→		}
   329→	}
   330→
   331→	// 최대 인원
   332→	Settings.MaxPlayers = CurrentMaxPlayers;
   333→
   334→	// 비공개 방
   335→	if (PrivateCheckBox)
   336→	{
   337→		Settings.bIsPrivate = PrivateCheckBox->IsChecked();
   338→	}
   339→
   340→	// 비밀번호
   341→	if (Settings.bIsPrivate && PasswordTextBox)
   342→	{
   343→		Settings.Password = PasswordTextBox->GetText().ToString();
   344→	}
   345→
   346→	// 게임 중 입장 허용
   347→	if (AllowJoinInProgressCheckBox)
   348→	{
   349→		Settings.bAllowJoinInProgress = AllowJoinInProgressCheckBox->IsChecked();
   350→	}
   351→
   352→	// 네트워크 모드
   353→	if (NetworkModeComboBox)
   354→	{
   355→		FString SelectedMode = NetworkModeComboBox->GetSelectedOption();
   356→		Settings.NetworkMode = (SelectedMode == TEXT("Steam")) ? ENetworkMode::Steam : ENetworkMode::LAN;
   357→	}
   358→	else
   359→	{
   360→		Settings.NetworkMode = ENetworkMode::LAN; // 기본값
   361→	}
   362→
   363→	UE_LOG(LogWjWorld, Log, TEXT("CreateRoomWindow: Built settings - Name: %s, Mode: %s, Map: %s, Players: %d, Network: %s"),
   364→		*Settings.RoomName, *Settings.GameMode, *Settings.MapName, Settings.MaxPlayers,
   365→		Settings.NetworkMode == ENetworkMode::Steam ? TEXT("Steam") : TEXT("LAN"));
   366→
   367→	return Settings;
   368→}
