{
	if (!HasAuthority()) return;
	if (!Player) return;

	if (PlayerDataComponentClass)
	{
		Player->AddGameDataComponent(PlayerDataComponentClass);
	}

	UE_LOG(LogWjWorld, Log, TEXT("GameRuleBase: Player Joined - %s"), *Player->GetName());
}

