{
	Super::BeginDestroy();

	UWorld* World = GetWorld();
	if (World)
	{
		World->GetTimerManager().ClearTimer(DelayStartHandle);
		World->GetTimerManager().ClearTimer(GotoWaitingRoomHandle);
