    30→void UWjWorldPlacementComponent::EnterPlacementMode()
    31→{
    32→	// 기본 컨텍스트: Lobby
    33→	EnterPlacementModeWithContext(EPlacementContext::Lobby);
    34→}
    35→
    36→void UWjWorldPlacementComponent::EnterPlacementModeWithContext(EPlacementContext Context)
    37→{
    38→	if (CurrentMode != EPlacementMode::None)
    39→	{
    40→		return;
    41→	}
    42→
    43→	CurrentContext = Context;
    44→
    45→	// DeveloperSettings에서 입력 설정 및 Catalog 로드 (컨텍스트별)
    46→	LoadInputSettings();
    47→	EnsureCatalogLoaded();
    48→
    49→	CurrentMode = EPlacementMode::Placing;
    50→	SetComponentTickEnabled(true);
    51→	BindInputActions();
    52→	RefreshPlacementModeVisuals();
    53→
    54→	OnPlacementModeChanged.Broadcast(CurrentMode);
    55→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Entered placement mode (Context: %s)"),
    56→		*GetPlacementContextName(CurrentContext));
    57→}
    58→
    59→void UWjWorldPlacementComponent::ExitPlacementMode()
    60→{
    61→	if (CurrentMode == EPlacementMode::None)
    62→	{
    63→		return;
    64→	}
    65→
    66→	// 호버 하이라이트 해제
    67→	if (HoveredObject)
    68→	{
    69→		HoveredObject->SetHighlighted(false);
    70→		HoveredObject = nullptr;
    71→	}
    72→
    73→	DestroyPreview();
    74→	UnbindInputActions();
    75→	SetComponentTickEnabled(false);
    76→
    77→	SelectedObjectId = NAME_None;
    78→	CurrentMode = EPlacementMode::None;
    79→	bAirPlacementMode = false;
    80→	AirPlaneHeight = 0.f;
    81→	// 컨텍스트는 리셋하지 않음 (다음 EnterPlacementMode 시 설정)
    82→
    83→	RefreshPlacementModeVisuals();
    84→
    85→	OnPlacementModeChanged.Broadcast(CurrentMode);
    86→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Exited placement mode"));
    87→}
    88→
    89→void UWjWorldPlacementComponent::ToggleDeleteMode()
    90→{
    91→	if (CurrentMode == EPlacementMode::None)
    92→	{
    93→		return;
    94→	}
    95→
    96→	if (CurrentMode == EPlacementMode::Deleting)
    97→	{
    98→		// 삭제 모드 해제 → 배치 모드 복귀
    99→		if (HoveredObject)
   100→		{
   101→			HoveredObject->SetHighlighted(false);
   102→			HoveredObject = nullptr;
   103→		}
   104→		CurrentMode = EPlacementMode::Placing;
   105→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to placing mode"));
   106→	}
   107→	else
   108→	{
   109→		// 배치 모드 → 삭제 모드
   110→		DestroyPreview();
   111→		CurrentMode = EPlacementMode::Deleting;
   112→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Switched to delete mode"));
   113→	}
   114→
   115→	OnPlacementModeChanged.Broadcast(CurrentMode);
   116→}
