   224→
   225→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   226→	if (!DataProvider)
   227→	{
   228→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: PlacementDataProvider not found"));
   229→		return;
   230→	}
   231→
   232→	// 로비 컨텍스트: 배치 수량 제한 체크
   233→	if (CurrentContext == EPlacementContext::Lobby)
   234→	{
   235→		const UWjWorldDeveloperSettings* DevSettings = GetDefault<UWjWorldDeveloperSettings>();
   236→
   237→		// 전체 배치 상한
   238→		if (DevSettings && DevSettings->MaxTotalLobbyPlacedObjects > 0)
   239→		{
   240→			if (DataProvider->GetPlacedObjects().Num() >= DevSettings->MaxTotalLobbyPlacedObjects)
   241→			{
   242→				UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: 전체 배치 상한 도달 (%d/%d)"),
   243→					DataProvider->GetPlacedObjects().Num(), DevSettings->MaxTotalLobbyPlacedObjects);
   244→				return;
   245→			}
   246→		}
   247→
   248→		// 종류당 배치 상한
   249→		{
   250→			int32 CurrentTypeCount = CountPlacedObjectsByType(SelectedObjectId);
   251→			int32 PlacementLimit = Def->MaxPlacementCount; // 0 = 무제한
   252→
   253→			// 유료 아이템 + 상한: 구매 수량(OwnedQty)이 배치 상한
   254→			if (Def->CoinPrice > 0 && Def->SteamItemDefId > 0 && Def->MaxPlacementCount > 0)
   255→			{
   256→				UGameInstance* GI = GetWorld() ? GetWorld()->GetGameInstance() : nullptr;
   257→				UWjWorldCosmeticSubsystem* CosmeticSub = GI ? GI->GetSubsystem<UWjWorldCosmeticSubsystem>() : nullptr;
   258→				if (CosmeticSub)
   259→				{
   260→					PlacementLimit = CosmeticSub->GetItemQuantityByDefId(Def->SteamItemDefId);
   261→				}
   262→			}
   263→
   264→			if (PlacementLimit > 0 && CurrentTypeCount >= PlacementLimit)
   265→			{
   266→				UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: 종류당 배치 상한 도달 (%s: %d/%d)"),
   267→					*SelectedObjectId.ToString(), CurrentTypeCount, PlacementLimit);
   268→				return;
   269→			}
   270→		}
   271→	}
   272→
   273→	// 배치 데이터 생성
   274→	FVector SpawnLocation = PreviewActor->GetActorLocation();
   275→	FRotator SpawnRotation = PreviewActor->GetCurrentRotation();
   276→	SpawnRotation.Normalize(); // 회전값 정규화 (서버/클라이언트 FQuat 변환 일관성 보장)
   277→
   278→	FPlacedObjectSaveEntry Entry;
   279→	Entry.ObjectId = SelectedObjectId;
   280→	Entry.Transform = FTransform(SpawnRotation, SpawnLocation, Def->DefaultScale);
   281→
   282→	// JumpMap 컨텍스트: Checkpoint 오브젝트에 자동 CheckpointOrder 할당
   283→	if (CurrentContext == EPlacementContext::JumpMap)
   284→	{
   285→		FString ObjectIdStr = SelectedObjectId.ToString();
   286→		if (ObjectIdStr.Contains(TEXT("Checkpoint")))
   287→		{
   288→			int32 MaxOrder = -1;
   289→			const TArray<FPlacedObjectSaveEntry>& Existing = DataProvider->GetPlacedObjects();
   290→			for (const FPlacedObjectSaveEntry& Obj : Existing)
   291→			{
   292→				if (Obj.ObjectId.ToString().Contains(TEXT("Checkpoint")))
   293→				{
   294→					const FString* OrderStr = Obj.CustomProperties.Find(TEXT("CheckpointOrder"));
   295→					if (OrderStr)
   296→					{
   297→						MaxOrder = FMath::Max(MaxOrder, FCString::Atoi(**OrderStr));
   298→					}
   299→				}
   300→			}
   301→			Entry.CustomProperties.Add(TEXT("CheckpointOrder"), FString::FromInt(MaxOrder + 1));
   302→		}
   303→	}
   304→
   305→	// DataProvider에 추가 (서버에서 스폰 + 클라이언트 리플리케이션)
   306→	DataProvider->AddPlacedObject(Entry);
   307→
   308→	// 새로 생성된 액터에도 배치 모드 비주얼 적용
   309→	RefreshPlacementModeVisuals();
   310→
   311→	// 로컬 SaveGame에도 저장 (호스트 영구 저장용)
   312→	SaveLayout();
   313→
   314→	OnObjectPlaced.Broadcast();
   315→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Object placed - ObjectId=%s at %s (Context: %s)"),
   316→		*SelectedObjectId.ToString(), *SpawnLocation.ToString(), *GetPlacementContextName(CurrentContext));
   317→}
