		ExitButton->OnClicked.AddDynamic(this, &UPlacementHUDWidgetBase::OnExitClicked);
	}

	if (DeleteModeButton)
	{
		DeleteModeButton->OnClicked.AddDynamic(this, &UPlacementHUDWidgetBase::OnDeleteModeClicked);
	}

