DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnAirModeChanged, bool, bIsAirMode);
DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnSnapDegreesChanged, float, NewSnapDegrees);
