/**
 * 로비 오브젝트 배치 핵심 컴포넌트
 * PlayerControllerLobby에 부착되어 배치/삭제 로직을 처리
 */
UCLASS(ClassGroup=(Custom), meta=(BlueprintSpawnableComponent))
class WJWORLD_API UWjWorldPlacementComponent : public UActorComponent
