	UPROPERTY(meta = (BindWidgetOptional))
	TObjectPtr<UTextBlock> SelectedItemDescriptionText;

	UPROPERTY(meta = (BindWidgetOptional))
	TObjectPtr<UTextBlock> SelectedItemPriceText;

	//~ 잔액 표시 위젯
	UPROPERTY(meta = (BindWidgetOptional))
	TObjectPtr<UCurrencyBalanceWidget> CurrencyBalanceWidget;

	//~ 프리뷰 패널
