	/** 알림 숨기기 */
	void HideNotification();

	FTimerHandle NotificationTimerHandle;

	static constexpr float NotificationDisplayDuration = 3.0f;

	/** 그리드 열 수 */
	static constexpr int32 GridColumnCount = 4;
};

