    50→void UGemPackStoreWidget::OnPackPurchaseClicked(int32 PackDefId)
    51→{
    52→	UGameInstance* GI = GetGameInstance();
    53→	if (!GI)
    54→	{
    55→		return;
    56→	}
    57→
    58→	UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
    59→	if (CurrencySub)
    60→	{
    61→		CurrencySub->PurchaseGemPack(PackDefId);
    62→		UE_LOG(LogWjWorldCurrency, Log, TEXT("GemPackStoreWidget: Purchase requested for PackDefId=%d"), PackDefId);
    63→	}
    64→}
