    66→void UGemPackStoreWidget::PopulatePackList()
    67→{
    68→	ClearPackList();
    69→
    70→	if (!PackEntryWidgetClass)
    71→	{
    72→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("GemPackStoreWidget: PackEntryWidgetClass is not set"));
    73→		return;
    74→	}
    75→
    76→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
    77→	if (!Settings)
    78→	{
    79→		return;
    80→	}
    81→
    82→	for (const FGemPackDefinition& PackDef : Settings->GemPackDefinitions)
    83→	{
    84→		UGemPackEntryWidget* EntryWidget = CreateWidget<UGemPackEntryWidget>(GetOwningPlayer(), PackEntryWidgetClass);
    85→		if (!EntryWidget)
    86→		{
    87→			continue;
    88→		}
    89→
    90→		EntryWidget->SetPackDefinition(PackDef);
    91→		EntryWidget->OnBuyClicked.AddDynamic(this, &UGemPackStoreWidget::OnPackPurchaseClicked);
    92→
    93→		if (PackListBox)
    94→		{
    95→			PackListBox->AddChild(EntryWidget);
    96→		}
    97→
    98→		PackEntryWidgets.Add(EntryWidget);
    99→	}
   100→
   101→	UE_LOG(LogWjWorldCurrency, Log, TEXT("GemPackStoreWidget: Populated %d pack entries"), PackEntryWidgets.Num());
   102→}
   103→
   104→void UGemPackStoreWidget::ClearPackList()
   105→{
   106→	for (UGemPackEntryWidget* Entry : PackEntryWidgets)
   107→	{
   108→		if (Entry)
   109→		{
   110→			Entry->OnBuyClicked.RemoveDynamic(this, &UGemPackStoreWidget::OnPackPurchaseClicked);
   111→			Entry->RemoveFromParent();
   112→		}
   113→	}
   114→	PackEntryWidgets.Empty();
   115→
   116→	if (PackListBox)
   117→	{
   118→		PackListBox->ClearChildren();
   119→	}
   120→}
