    37→void UWjWorldCurrencySubsystem::Deinitialize()
    38→{
    39→	StopExchangePolling();
    40→	StopGemPurchasePolling();
    41→
    42→	// 로컬 잔액 저장
    43→	SaveBalancesToLocal();
    44→
    45→	// 델리게이트 해제
    46→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
    47→	if (CosmeticSub)
    48→	{
    49→		CosmeticSub->OnInventoryUpdated.RemoveDynamic(this, &UWjWorldCurrencySubsystem::HandleInventoryUpdated);
    50→	}
    51→
    52→#if WITH_STEAM
    53→	ISteamInventory* SteamInv = SteamInventory();
    54→	if (SteamInv)
    55→	{
    56→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
    57→		{
    58→			SteamInv->DestroyResult(ExchangeResultHandle);
    59→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
    60→		}
    61→		if (GemPurchaseResultHandle != k_SteamInventoryResultInvalid)
    62→		{
    63→			SteamInv->DestroyResult(GemPurchaseResultHandle);
    64→			GemPurchaseResultHandle = k_SteamInventoryResultInvalid;
    65→		}
    66→	}
    67→
    68→	CachedCoinInstanceId = k_SteamItemInstanceIDInvalid;
    69→	CachedGemInstanceId = k_SteamItemInstanceIDInvalid;
    70→#endif
    71→
    72→	Super::Deinitialize();
    73→}
