   298→bool UWjWorldCurrencySubsystem::PurchasePlacementObject(FName ObjectId)
   299→{
   300→	if (bExchangePending)
   301→	{
   302→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("이미 교환이 진행 중입니다."));
   303→		return false;
   304→	}
   305→
   306→	if (ObjectId.IsNone())
   307→	{
   308→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("유효하지 않은 ObjectId"));
   309→		return false;
   310→	}
   311→
   312→	// DeveloperSettings에서 LobbyPlaceableCatalog 로드
   313→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   314→	if (!Settings)
   315→	{
   316→		return false;
   317→	}
   318→
   319→	UWjWorldPlaceableObjectDataAsset* PlacementCatalog = Settings->GetPlaceableCatalogForContext(EPlacementContext::Lobby);
   320→	if (!PlacementCatalog)
   321→	{
   322→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("LobbyPlaceableCatalog 없음"));
   323→		return false;
   324→	}
   325→
   326→	const FPlaceableObjectDefinition* Def = PlacementCatalog->FindByObjectId(ObjectId);
   327→	if (!Def)
   328→	{
   329→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("카탈로그에서 오브젝트 '%s' 찾을 수 없음"), *ObjectId.ToString());
   330→		return false;
   331→	}
   332→
   333→	if (Def->CoinPrice <= 0)
   334→	{
   335→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("오브젝트 '%s'은 무료입니다 (구매 불필요)"), *ObjectId.ToString());
   336→		return false;
   337→	}
   338→
   339→	if (Def->SteamItemDefId <= 0)
   340→	{
   341→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("오브젝트 '%s'에 SteamItemDefId가 설정되지 않음"), *ObjectId.ToString());
   342→		return false;
   343→	}
   344→
   345→	// 잔액 확인
   346→	int32 CurrentBalance = GetBalance(ECurrencyType::Coin);
   347→	if (CurrentBalance < Def->CoinPrice)
   348→	{
   349→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Coin 잔액 부족: %d < %d"), CurrentBalance, Def->CoinPrice);
   350→		return false;
   351→	}
   352→
   353→	UE_LOG(LogWjWorldCurrency, Log, TEXT("배치 오브젝트 구매 요청: %s (%d Coin → DefId %d)"),
   354→		*ObjectId.ToString(), Def->CoinPrice, Def->SteamItemDefId);
   355→
   356→#if WITH_STEAM
   357→	ISteamInventory* SteamInv = SteamInventory();
   358→	if (SteamInv)
   359→	{
   360→		SteamItemInstanceID_t CoinInstanceId = CachedCoinInstanceId;
   361→		if (CoinInstanceId == k_SteamItemInstanceIDInvalid)
   362→		{
   363→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Coin 인스턴스 ID가 캐싱되지 않음 — 인벤토리 갱신 필요"));
   364→			return false;
   365→		}
   366→
   367→		// 기존 핸들 정리
   368→		if (ExchangeResultHandle != k_SteamInventoryResultInvalid)
   369→		{
   370→			SteamInv->DestroyResult(ExchangeResultHandle);
   371→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   372→		}
   373→
   374→		// ExchangeItems: Coin 소비 → 배치 오브젝트 아이템 획득
   375→		SteamItemDef_t OutputItemDef = static_cast<SteamItemDef_t>(Def->SteamItemDefId);
   376→		uint32 OutputQuantity = 1;
   377→		uint32 InputQuantity = static_cast<uint32>(Def->CoinPrice);
   378→
   379→		bool bExchangeResult = SteamInv->ExchangeItems(
   380→			&ExchangeResultHandle,
   381→			&OutputItemDef, &OutputQuantity, 1,
   382→			&CoinInstanceId, &InputQuantity, 1
   383→		);
   384→
   385→		if (bExchangeResult)
   386→		{
   387→			bExchangePending = true;
   388→			bPendingIsPlacement = true;
   389→			PendingExchangeItemId = ObjectId;
   390→			StartExchangePolling();
   391→
   392→			UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam ExchangeItems 요청 성공 (배치): %s (CoinInstanceId=%llu, Price=%d)"),
   393→				*ObjectId.ToString(), CoinInstanceId, Def->CoinPrice);
   394→			return true;
   395→		}
   396→		else
   397→		{
   398→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam ExchangeItems 호출 실패 (배치): %s"), *ObjectId.ToString());
   399→			ExchangeResultHandle = k_SteamInventoryResultInvalid;
   400→			return false;
   401→		}
   402→	}
   403→#endif
   404→
   405→	// 비Steam 폴백: 로컬 잔액 차감 + 로컬 소유 수량 증가
   406→	SetBalance(ECurrencyType::Coin, CurrentBalance - Def->CoinPrice);
   407→
   408→	// GConfig에 소유 수량 기록
   409→	static const FString PlacementInventorySection = TEXT("PlacementInventory");
   410→	int32 CurrentOwned = 0;
   411→	GConfig->GetInt(*PlacementInventorySection, *ObjectId.ToString(), CurrentOwned, GGameUserSettingsIni);
   412→	GConfig->SetInt(*PlacementInventorySection, *ObjectId.ToString(), CurrentOwned + 1, GGameUserSettingsIni);
   413→	GConfig->Flush(false, GGameUserSettingsIni);
   414→
   415→	// CosmeticSubsystem의 AllItemQuantities도 갱신 (비Steam)
   416→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   417→	if (CosmeticSub)
   418→	{
   419→		CosmeticSub->AllItemQuantities.FindOrAdd(Def->SteamItemDefId) += 1;
   420→	}
   421→
   422→	OnPlacementPurchaseComplete.Broadcast(ObjectId, true);
   423→
   424→	UE_LOG(LogWjWorldCurrency, Log, TEXT("로컬 배치 오브젝트 구매 완료: %s (%d Coin 차감)"),
   425→		*ObjectId.ToString(), Def->CoinPrice);
   426→
   427→	return true;
   428→}
