   615→
   616→void UWjWorldCurrencySubsystem::DebugConsumeAllSteamItems()
   617→{
   618→#if WITH_STEAM
   619→	ISteamInventory* SteamInv = SteamInventory();
   620→	if (!SteamInv)
   621→	{
   622→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam Inventory API 없음"));
   623→		return;
   624→	}
   625→
   626→	SteamInventoryResult_t AllItemsHandle = k_SteamInventoryResultInvalid;
   627→	if (!SteamInv->GetAllItems(&AllItemsHandle))
   628→	{
   629→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 실패"));
   630→		return;
   631→	}
   632→
   633→	EResult Status = SteamInv->GetResultStatus(AllItemsHandle);
   634→	if (Status != k_EResultOK)
   635→	{
   636→		SteamInv->DestroyResult(AllItemsHandle);
   637→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: GetAllItems 상태 실패 (%d)"), static_cast<int32>(Status));
   638→		return;
   639→	}
   640→
   641→	uint32 ItemCount = 0;
   642→	if (!SteamInv->GetResultItems(AllItemsHandle, nullptr, &ItemCount) || ItemCount == 0)
   643→	{
   644→		SteamInv->DestroyResult(AllItemsHandle);
   645→		UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: 인벤토리가 이미 비어있음"));
   646→		return;
   647→	}
   648→
   649→	TArray<SteamItemDetails_t> Items;
   650→	Items.SetNum(ItemCount);
   651→	SteamInv->GetResultItems(AllItemsHandle, Items.GetData(), &ItemCount);
   652→	SteamInv->DestroyResult(AllItemsHandle);
   653→
   654→	int32 ConsumedCount = 0;
   655→	for (const SteamItemDetails_t& Detail : Items)
   656→	{
   657→		if (Detail.m_unQuantity == 0)
   658→		{
   659→			continue;
   660→		}
   661→
   662→		SteamInventoryResult_t ConsumeHandle = k_SteamInventoryResultInvalid;
   663→		if (SteamInv->ConsumeItem(&ConsumeHandle, Detail.m_itemId, Detail.m_unQuantity))
   664→		{
   665→			UE_LOG(LogWjWorldCurrency, Log, TEXT("  소비: DefId=%d, Quantity=%d, InstanceId=%llu"),
   666→				Detail.m_iDefinition, Detail.m_unQuantity, Detail.m_itemId);
   667→			SteamInv->DestroyResult(ConsumeHandle);
   668→			++ConsumedCount;
   669→		}
   670→	}
   671→
   672→	// 캐시 초기화
   673→	CachedCoinInstanceId = k_SteamItemInstanceIDInvalid;
   674→	CachedGemInstanceId = k_SteamItemInstanceIDInvalid;
   675→
   676→	// 인벤토리 갱신
   677→	UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   678→	if (CosmeticSub)
   679→	{
   680→		CosmeticSub->RequestInventoryRefresh();
   681→	}
   682→
   683→	UE_LOG(LogWjWorldCurrency, Log, TEXT("DebugConsumeAllSteamItems: %d/%d 아이템 소비 완료"), ConsumedCount, ItemCount);
   684→#else
   685→	UE_LOG(LogWjWorldCurrency, Warning, TEXT("DebugConsumeAllSteamItems: Steam 환경에서만 사용 가능"));
   686→#endif
   687→}
   688→
   689→void UWjWorldCurrencySubsystem::HandleInventoryUpdated()
   690→{
   691→	RefreshBalancesFromInventory();
   692→}
   693→
   694→void UWjWorldCurrencySubsystem::PollExchangeResult()
   695→{
   696→#if WITH_STEAM
   697→	if (!bExchangePending || ExchangeResultHandle == k_SteamInventoryResultInvalid)
   698→	{
   699→		StopExchangePolling();
   700→		return;
   701→	}
   702→
   703→	ISteamInventory* SteamInv = SteamInventory();
   704→	if (!SteamInv)
   705→	{
   706→		StopExchangePolling();
   707→		bExchangePending = false;
   708→		if (bPendingIsPlacement)
   709→		{
   710→			OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   711→		}
   712→		else
   713→		{
   714→			OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, false);
   715→		}
   716→		bPendingIsPlacement = false;
   717→		PendingExchangeItemId = NAME_None;
   718→		return;
   719→	}
   720→
   721→	EResult Status = SteamInv->GetResultStatus(ExchangeResultHandle);
   722→	if (Status == k_EResultPending)
   723→	{
   724→		return;
   725→	}
   726→
   727→	bool bSuccess = (Status == k_EResultOK);
   728→	if (bSuccess)
   729→	{
   730→		UE_LOG(LogWjWorldCurrency, Log, TEXT("Steam Exchange 성공: %s"), *PendingExchangeItemId.ToString());
   731→
   732→		// 인벤토리 갱신
   733→		UWjWorldCosmeticSubsystem* CosmeticSub = GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   734→		if (CosmeticSub)
   735→		{
   736→			CosmeticSub->RequestInventoryRefresh();
   737→		}
   738→	}
   739→	else
   740→	{
   741→		UE_LOG(LogWjWorldCurrency, Warning, TEXT("Steam Exchange 실패: %s (Status: %d)"),
   742→			*PendingExchangeItemId.ToString(), static_cast<int32>(Status));
   743→	}
   744→
   745→	SteamInv->DestroyResult(ExchangeResultHandle);
   746→	ExchangeResultHandle = k_SteamInventoryResultInvalid;
   747→
   748→	bExchangePending = false;
   749→
   750→	// 배치 vs 코스메틱 분기
   751→	if (bPendingIsPlacement)
   752→	{
   753→		OnPlacementPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   754→	}
   755→	else
   756→	{
   757→		OnCurrencyPurchaseComplete.Broadcast(PendingExchangeItemId, bSuccess);
   758→	}
   759→	bPendingIsPlacement = false;
   760→	PendingExchangeItemId = NAME_None;
   761→
   762→	StopExchangePolling();
   763→#else
   764→	StopExchangePolling();
   765→#endif
   766→}
   767→
   768→void UWjWorldCurrencySubsystem::StartExchangePolling()
   769→{
   770→	UWorld* World = GetWorld();
   771→	if (!World)
   772→	{
   773→		return;
   774→	}
   775→
   776→	World->GetTimerManager().SetTimer(
   777→		ExchangePollTimerHandle,
   778→		this,
   779→		&UWjWorldCurrencySubsystem::PollExchangeResult,
   780→		0.5f,
   781→		true
   782→	);
   783→}
   784→
   785→void UWjWorldCurrencySubsystem::StopExchangePolling()
   786→{
   787→	UWorld* World = GetWorld();
   788→	if (World)
   789→	{
   790→		World->GetTimerManager().ClearTimer(ExchangePollTimerHandle);
   791→	}
   792→}
   793→
   794→void UWjWorldCurrencySubsystem::PollGemPurchaseResult()
   795→{
   796→#if WITH_STEAM
   797→	if (!bGemPurchasePending)
   798→	{
   799→		StopGemPurchasePolling();
   800→		return;
   801→	}
   802→
   803→	// Gem 팩 구매는 Steam 오버레이를 통해 처리되므로
   804→	// 인벤토리 변경을 감지하여 완료 판단
   805→	// CosmeticSubsystem의 OnInventoryUpdated → HandleInventoryUpdated → RefreshBalancesFromInventory
   806→	// 에서 Gem 잔액 변경이 감지되면 구매 완료로 판단
   807→
   808→	// 간단한 타임아웃 처리 (300초)
   809→	UWorld* World = GetWorld();
   810→	if (World)
   811→	{
   812→		if (GemPurchaseStartTime == 0.0f)
   813→		{
   814→			GemPurchaseStartTime = World->GetTimeSeconds();
   815→		}
   816→
   817→		float ElapsedTime = World->GetTimeSeconds() - GemPurchaseStartTime;
   818→		if (ElapsedTime > 300.0f)
   819→		{
   820→			UE_LOG(LogWjWorldCurrency, Warning, TEXT("Gem 팩 구매 타임아웃"));
   821→			bGemPurchasePending = false;
   822→			GemPurchaseStartTime = 0.0f;
   823→			StopGemPurchasePolling();
   824→		}
   825→	}
   826→#else
   827→	StopGemPurchasePolling();
   828→#endif
   829→}
   830→
   831→void UWjWorldCurrencySubsystem::StartGemPurchasePolling()
   832→{
   833→	UWorld* World = GetWorld();
   834→	if (!World)
   835→	{
   836→		return;
   837→	}
   838→
   839→	World->GetTimerManager().SetTimer(
   840→		GemPurchasePollTimerHandle,
   841→		this,
   842→		&UWjWorldCurrencySubsystem::PollGemPurchaseResult,
   843→		1.0f,
   844→		true
   845→	);
   846→}
   847→
   848→void UWjWorldCurrencySubsystem::StopGemPurchasePolling()
   849→{
   850→	UWorld* World = GetWorld();
   851→	if (World)
   852→	{
   853→		World->GetTimerManager().ClearTimer(GemPurchasePollTimerHandle);
   854→	}
   855→}
