   857→void UWjWorldCurrencySubsystem::SaveBalancesToLocal()
   858→{
   859→	GConfig->SetInt(*CurrencyConfigSection, TEXT("CoinBalance"), CoinBalance, GGameUserSettingsIni);
   860→	GConfig->SetInt(*CurrencyConfigSection, TEXT("GemBalance"), GemBalance, GGameUserSettingsIni);
   861→
   862→	GConfig->Flush(false, GGameUserSettingsIni);
   863→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 저장 완료"));
   864→}
   865→
   866→void UWjWorldCurrencySubsystem::LoadBalancesFromLocal()
   867→{
   868→	int32 LoadedCoin = 0;
   869→	int32 LoadedGem = 0;
   870→
   871→	GConfig->GetInt(*CurrencyConfigSection, TEXT("CoinBalance"), LoadedCoin, GGameUserSettingsIni);
   872→	GConfig->GetInt(*CurrencyConfigSection, TEXT("GemBalance"), LoadedGem, GGameUserSettingsIni);
   873→
   874→	CoinBalance = FMath::Max(0, LoadedCoin);
   875→	GemBalance = FMath::Max(0, LoadedGem);
   876→
   877→	UE_LOG(LogWjWorldCurrency, Log, TEXT("재화 잔액 로컬 로드 완료 (Coin: %d, Gem: %d)"), CoinBalance, GemBalance);
   878→}
   879→
   880→void UWjWorldCurrencySubsystem::SetBalance(ECurrencyType Type, int32 NewAmount)
   881→{
   882→	NewAmount = FMath::Max(0, NewAmount);
   883→
   884→	switch (Type)
   885→	{
   886→	case ECurrencyType::Coin:
   887→		if (CoinBalance != NewAmount)
   888→		{
   889→			CoinBalance = NewAmount;
   890→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Coin, CoinBalance);
   891→		}
   892→		break;
   893→	case ECurrencyType::Gem:
   894→		if (GemBalance != NewAmount)
   895→		{
   896→			GemBalance = NewAmount;
   897→			OnCurrencyBalanceChanged.Broadcast(ECurrencyType::Gem, GemBalance);
   898→		}
   899→		break;
   900→	}
   901→}
   902→
   903→void UWjWorldCurrencySubsystem::LoadDailyRewardData()
   904→{
   905→	FString DateStr;
   906→	GConfig->GetString(*CurrencyConfigSection, TEXT("LastRewardDate"), DateStr, GGameUserSettingsIni);
   907→	GConfig->GetInt(*CurrencyConfigSection, TEXT("TodayMatchRewardCount"), TodayMatchRewardCount, GGameUserSettingsIni);
   908→
   909→	if (!DateStr.IsEmpty())
   910→	{
   911→		FDateTime::Parse(DateStr, LastRewardDate);
   912→	}
   913→
   914→	CheckDailyReset();
   915→}
   916→
   917→void UWjWorldCurrencySubsystem::SaveDailyRewardData()
   918→{
   919→	GConfig->SetString(*CurrencyConfigSection, TEXT("LastRewardDate"), *LastRewardDate.ToString(), GGameUserSettingsIni);
   920→	GConfig->SetInt(*CurrencyConfigSection, TEXT("TodayMatchRewardCount"), TodayMatchRewardCount, GGameUserSettingsIni);
   921→	GConfig->Flush(false, GGameUserSettingsIni);
   922→}
   923→
   924→void UWjWorldCurrencySubsystem::CheckDailyReset()
   925→{
   926→	FDateTime Now = FDateTime::Now();
   927→	if (Now.GetDay() != LastRewardDate.GetDay()
   928→		|| Now.GetMonth() != LastRewardDate.GetMonth()
   929→		|| Now.GetYear() != LastRewardDate.GetYear())
   930→	{
   931→		TodayMatchRewardCount = 0;
   932→		LastRewardDate = Now;
   933→		SaveDailyRewardData();
   934→		UE_LOG(LogWjWorldCurrency, Log, TEXT("일일 보상 카운트 리셋 (새 날짜: %s)"), *Now.ToString());
   935→	}
   936→}
   937→
   938→void UWjWorldCurrencySubsystem::ScheduleInventoryRefresh()
   939→{
   940→	UWorld* World = GetWorld();
   941→	if (!World)
   942→	{
   943→		return;
   944→	}
   945→
   946→	TWeakObjectPtr<UWjWorldCurrencySubsystem> WeakThis(this);
   947→
   948→	// 2.5초 후 첫 번째 갱신
   949→	FTimerHandle FirstTimerHandle;
   950→	World->GetTimerManager().SetTimer(FirstTimerHandle, [WeakThis]()
   951→	{
   952→		if (UWjWorldCurrencySubsystem* Self = WeakThis.Get())
   953→		{
   954→			UWjWorldCosmeticSubsystem* CosmeticSub = Self->GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   955→			if (CosmeticSub)
   956→			{
   957→				CosmeticSub->RequestInventoryRefresh();
   958→				UE_LOG(LogWjWorldCurrency, Log, TEXT("인벤토리 갱신 (2.5초 후)"));
   959→			}
   960→		}
   961→	}, 2.5f, false);
   962→
   963→	// 5초 후 재시도 갱신
   964→	FTimerHandle RetryTimerHandle;
   965→	World->GetTimerManager().SetTimer(RetryTimerHandle, [WeakThis]()
   966→	{
   967→		if (UWjWorldCurrencySubsystem* Self = WeakThis.Get())
   968→		{
   969→			UWjWorldCosmeticSubsystem* CosmeticSub = Self->GetGameInstance()->GetSubsystem<UWjWorldCosmeticSubsystem>();
   970→			if (CosmeticSub)
   971→			{
   972→				CosmeticSub->RequestInventoryRefresh();
   973→				UE_LOG(LogWjWorldCurrency, Log, TEXT("인벤토리 갱신 재시도 (5초 후)"));
   974→			}
   975→		}
   976→	}, 5.0f, false);
   977→}
